const lessons = [
{num:1,time:"00:00:30,000 --> 00:00:34,579",arabic:"السَّلَامُ عَلَى أَمِيرِ الْمُؤْمِنِينَ.",segs:[{ar:"السَّلَامُ",uz:"salom bo‘lsin"},{ar:"عَلَى أَمِيرِ الْمُؤْمِنِينَ",uz:"mo‘minlar amiriga"}],full_uz:"Mo‘minlar amiriga salom bo‘lsin.",note:"أَمِيرُ الْمُؤْمِنِينَ — «mo‘minlar amiri». عَلَى dan keyin أَمِيرِ shaklida keladi."},
{num:2,time:"00:00:34,579 --> 00:00:38,219",arabic:"وَعَلَيْكَ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ.",segs:[{ar:"وَعَلَيْكَ السَّلَامُ",uz:"sizga ham salom bo‘lsin"},{ar:"وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ",uz:"Allohning rahmati va barakalari ham"}],full_uz:"Sizga ham salom, Allohning rahmati va barakalari bo‘lsin.",note:null},
{num:3,time:"00:00:38,219 --> 00:00:39,859",arabic:"أَرْسَلْتَ فِي طَلَبِي؟",segs:null,full_uz:"Meni chaqirtirdingizmi?",note:"أَرْسَلَ فِي طَلَبِ فُلَانٍ — «falonchini chaqirtirdi, uni olib kelish uchun odam yubordi»."},
{num:4,time:"00:01:01,000 --> 00:01:03,000",arabic:"كَيْفَ حَالُكِ يَا أُمَّاهُ؟",segs:[{ar:"كَيْفَ حَالُكِ",uz:"ahvolingiz qanday"},{ar:"يَا أُمَّاهُ",uz:"ey onajon"}],full_uz:"Ahvolingiz qanday, onajon?",note:"حَالُكِ dagi ـكِ ayol kishiga murojaatni bildiradi. يَا أُمَّاهُ — mehr bilan «onajon» deb murojaat qilish shakli."},
{num:5,time:"00:01:07,000 --> 00:01:11,000",arabic:"بَارَكَ اللَّهُ فِيكَ، بِخَيْرٍ وَالْحَمْدُ لِلَّهِ.",segs:[{ar:"بَارَكَ اللَّهُ فِيكَ",uz:"Alloh sizga baraka bersin"},{ar:"بِخَيْرٍ",uz:"yaxshiman"},{ar:"وَالْحَمْدُ لِلَّهِ",uz:"Allohga hamd bo‘lsin"}],full_uz:"Alloh sizga baraka bersin. Yaxshiman, Allohga hamd bo‘lsin.",note:"بَارَكَ اللَّهُ فِيكَ shaklan o‘tgan zamonli gap bo‘lsa-da, duo ma’nosida ishlatiladi."},
{num:6,time:"00:01:18,000 --> 00:01:20,000",arabic:"وَكَيْفَ رِضَاكِ عَنِّي يَا أُمِّي؟",segs:[{ar:"وَكَيْفَ رِضَاكِ عَنِّي",uz:"mendan roziligingiz qanday"},{ar:"يَا أُمِّي",uz:"ey onam"}],full_uz:"Mendan qay darajada rozisiz, onajon?",note:"رَضِيَ عَنْ — «...dan rozi bo‘ldi». رِضَا — shu fe’lning masdari."},
{num:7,time:"00:01:27,000 --> 00:01:29,000",arabic:"وَكَيْفَ يَكُونُ قَلْبُ الْأُمِّ عَلَى وَلَدِهَا؟",segs:[{ar:"وَكَيْفَ يَكُونُ",uz:"qanday bo‘lishi mumkin"},{ar:"قَلْبُ الْأُمِّ",uz:"onaning qalbi"},{ar:"عَلَى وَلَدِهَا",uz:"farzandiga nisbatan"}],full_uz:"Onaning qalbi farzandiga nisbatan qanday bo‘lishi mumkin?",note:"Savol javob talab qilishdan ko‘ra, onaning farzandiga mehrini ta’kidlash uchun aytilgan."},
{num:8,time:"00:01:30,000 --> 00:01:33,840",arabic:"إِلَّا الدُّعَاءَ لَهُ بِالتَّوْفِيقِ وَالسَّدَادِ بُكْرَةً وَعَشِيًّا.",segs:[{ar:"إِلَّا الدُّعَاءَ لَهُ",uz:"uning haqqiga duo qilishdan boshqa"},{ar:"بِالتَّوْفِيقِ وَالسَّدَادِ",uz:"muvaffaqiyat va to‘g‘rilik tilab"},{ar:"بُكْرَةً وَعَشِيًّا",uz:"ertalab va kechqurun"}],full_uz:"Ertalab va kechqurun uning haqqiga muvaffaqiyat va to‘g‘rilik tilab duo qilishdan boshqa nima ham bo‘lardi?",note:"السَّدَادُ — fikr, so‘z va ishda to‘g‘ri yo‘l tutish. بُكْرَةً وَعَشِيًّا vaqtni bildiruvchi mansub birliklardir."},
{num:9,time:"00:01:33,840 --> 00:01:38,359",arabic:"أَطَالَ اللَّهُ فِي عُمْرِكَ.",segs:[{ar:"أَطَالَ اللَّهُ",uz:"Alloh uzoq qilsin"},{ar:"فِي عُمْرِكَ",uz:"umringizni"}],full_uz:"Alloh umringizni uzoq qilsin.",note:"أَطَالَ — «uzaytirdi». Bu gapda duo ma’nosida kelgan."},
{num:10,time:"00:01:38,359 --> 00:01:42,939",arabic:"وَأَخَذَ بِيَدِكَ لِمَا يُحِبُّهُ وَيَرْضَاهُ.",segs:[{ar:"وَأَخَذَ بِيَدِكَ",uz:"qo‘lingizdan tutib yo‘llasin"},{ar:"لِمَا يُحِبُّهُ وَيَرْضَاهُ",uz:"O‘zi sevadigan va rozi bo‘ladigan ishlarga"}],full_uz:"Sizni O‘zi sevadigan va rozi bo‘ladigan ishlarga yo‘llasin.",note:"أَخَذَ بِيَدِهِ so‘zma-so‘z «uning qo‘lidan tutdi»; ko‘chma ma’noda «yordam berdi, to‘g‘ri yo‘lga boshladi»."},
{num:11,time:"00:02:00,000 --> 00:02:10,719",arabic:"قُلْتُ لِنَفْسِي: أَرَى أُمِّي قَبْلَ الِانْغِمَاسِ فِي شُؤُونِ الدِّيوَانِ وَأَعْمَالِ الْحُجَّابِ.",segs:[{ar:"قُلْتُ لِنَفْسِي",uz:"o‘zimga dedim"},{ar:"أَرَى أُمِّي",uz:"onamni ko‘rib olay"},{ar:"قَبْلَ الِانْغِمَاسِ",uz:"sho‘ng‘ib ketishdan oldin"},{ar:"فِي شُؤُونِ الدِّيوَانِ",uz:"devon ishlariga"},{ar:"وَأَعْمَالِ الْحُجَّابِ",uz:"va hojiblar ishlariga"}],full_uz:"O‘zimga: «Devon va hojiblar ishlariga sho‘ng‘ib ketishdan oldin onamni ko‘rib olay», dedim.",note:"اِنْغَمَسَ فِي — «...ga sho‘ng‘idi, butunlay berilib ketdi». الدِّيوَانُ — davlat ishlarini yurituvchi idora; الْحُجَّابُ — saroy hojiblari."},
{num:12,time:"00:02:10,719 --> 00:02:15,360",arabic:"إِنَّ الرَّعِيَّةَ أَمَانَةٌ فِي عُنُقِكَ.",segs:[{ar:"إِنَّ الرَّعِيَّةَ أَمَانَةٌ",uz:"albatta, xalq omonatdir"},{ar:"فِي عُنُقِكَ",uz:"sizning zimmangizda"}],full_uz:"Xalq sizning zimmangizdagi omonatdir.",note:"الرَّعِيَّةُ — hukmdor boshqaruvidagi xalq. فِي عُنُقِكَ so‘zma-so‘z «bo‘yningizda», ya’ni «zimmangizda»."},
{num:13,time:"00:02:15,360 --> 00:02:18,939",arabic:"قَدْ كَانَ وَالِدُكَ، رَحِمَهُ اللَّهُ...",segs:[{ar:"قَدْ كَانَ وَالِدُكَ",uz:"otangiz ... qilar edilar"},{ar:"رَحِمَهُ اللَّهُ",uz:"Alloh u kishini rahmatiga olsin"}],full_uz:"Otangiz, Alloh u kishini rahmatiga olsin, ... qilar edilar.",note:"كَانَ dan keyingi muzori’ fe’l o‘tmishda odat bo‘lgan ishni bildiradi. Bu yerda fe’l keyingi bandda keladi."},
{num:14,time:"00:02:18,939 --> 00:02:21,639",arabic:"يَتَخَوَّلُهُمْ بِرِعَايَتِهِ.",segs:[{ar:"يَتَخَوَّلُهُمْ",uz:"ularning holidan muntazam xabar olar edilar"},{ar:"بِرِعَايَتِهِ",uz:"o‘z g‘amxo‘rliklari bilan"}],full_uz:"Ularga g‘amxo‘rlik qilib, hollaridan muntazam xabar olar edilar.",note:"تَخَوَّلَ فُلَانًا — «uning holidan vaqti-vaqti bilan xabar oldi, unga e’tibor ko‘rsatdi»."},
{num:15,time:"00:02:21,639 --> 00:02:24,400",arabic:"كَمَا يَتَخَوَّلُ الْوَالِدُ ابْنَهُ.",segs:[{ar:"كَمَا يَتَخَوَّلُ الْوَالِدُ",uz:"ota xabar olib turganidek"},{ar:"ابْنَهُ",uz:"o‘z o‘g‘lidan"}],full_uz:"Xuddi ota o‘z o‘g‘lining holidan xabar olib turganidek.",note:"الْوَالِدُ — ishni bajaruvchi ega; ابْنَهُ — harakat qaratilgan to‘ldiruvchi."},
{num:16,time:"00:02:26,800 --> 00:02:28,819",arabic:"رَحِمَ اللَّهُ أَبَا جَعْفَرٍ.",segs:[{ar:"رَحِمَ اللَّهُ",uz:"Alloh rahmatiga olsin"},{ar:"أَبَا جَعْفَرٍ",uz:"Abu Ja’farni"}],full_uz:"Alloh Abu Ja’farni rahmatiga olsin.",note:"أَبُو besh ismdan biridir. Bu yerda to‘ldiruvchi bo‘lgani uchun أَبَا shaklida kelgan."},
{num:17,time:"00:02:28,819 --> 00:02:32,259",arabic:"مَنْ مِنَّا يَقْوَى عَلَى مَا كَانَ يَقْوَى عَلَيْهِ؟",segs:[{ar:"مَنْ مِنَّا",uz:"qaysi birimiz"},{ar:"يَقْوَى عَلَى",uz:"qodir bo‘la olamiz"},{ar:"مَا كَانَ يَقْوَى عَلَيْهِ",uz:"u qodir bo‘lgan ishlarga"}],full_uz:"Qaysi birimiz u qodir bo‘lgan ishlarga qodir bo‘la olamiz?",note:"قَوِيَ عَلَى الشَّيْءِ — «bir ishga kuchi yetdi». مَا bu yerda «...gan narsa, ...gan ish» ma’nosida."},
{num:18,time:"00:02:32,259 --> 00:02:36,180",arabic:"وَفَّقَكَ اللَّهُ لِلسَّيْرِ عَلَى خُطَاهُ.",segs:[{ar:"وَفَّقَكَ اللَّهُ",uz:"Alloh sizga muvaffaqiyat bersin"},{ar:"لِلسَّيْرِ عَلَى خُطَاهُ",uz:"uning izidan borishda"}],full_uz:"Alloh uning izidan borishda sizga muvaffaqiyat bersin.",note:"سَارَ عَلَى خُطَاهُ — «uning izidan bordi, yo‘lini davom ettirdi». خُطًى — خُطْوَةٌ so‘zining ko‘pligi."},
{num:19,time:"00:02:36,180 --> 00:02:40,000",arabic:"وَجَعَلَكَ خَيْرَ خَلَفٍ لِخَيْرِ سَلَفٍ.",segs:[{ar:"وَجَعَلَكَ",uz:"va sizni qilsin"},{ar:"خَيْرَ خَلَفٍ",uz:"eng yaxshi voris"},{ar:"لِخَيْرِ سَلَفٍ",uz:"eng yaxshi o‘tmishdoshga"}],full_uz:"Va sizni eng yaxshi o‘tmishdoshning eng yaxshi vorisi qilsin.",note:"خَلَفٌ — keyin kelgan voris; سَلَفٌ — avval o‘tgan kishi. جَعَلَكَ خَيْرَ birikmasida ـكَ va خَيْرَ ikki to‘ldiruvchidir."},
{num:20,time:"00:02:40,000 --> 00:02:47,859",arabic:"رَحِمَ اللَّهُ أَخَاكَ الْأَمِينَ.",segs:[{ar:"رَحِمَ اللَّهُ",uz:"Alloh rahmatiga olsin"},{ar:"أَخَاكَ الْأَمِينَ",uz:"birodaringiz Aminni"}],full_uz:"Alloh birodaringiz Aminni rahmatiga olsin.",note:"أَخُوكَ so‘zi tushum holatida أَخَاكَ bo‘ladi."},
{num:21,time:"00:02:47,859 --> 00:02:51,699",arabic:"وَغَفَرَ لَكَ.",segs:null,full_uz:"Va sizni mag‘firat qilsin.",note:"غَفَرَ لَهُ — «uni kechirdi, gunohini mag‘firat qildi». Bu yerda duo ma’nosida."},
{num:22,time:"00:02:54,759 --> 00:02:57,599",arabic:"الْحَمْدُ لِلَّهِ عَلَى مَا قَضَى وَحَكَمَ.",segs:[{ar:"الْحَمْدُ لِلَّهِ",uz:"Allohga hamd bo‘lsin"},{ar:"عَلَى مَا قَضَى وَحَكَمَ",uz:"taqdir etgan va hukm qilgan narsalari uchun"}],full_uz:"Taqdir etgan va hukm qilgan narsalari uchun Allohga hamd bo‘lsin.",note:"مَا bu yerda so‘roq emas, «...gan narsa» ma’nosidagi nisbiy olmosh."},
{num:23,time:"00:02:57,599 --> 00:03:24,459",arabic:"لَا أَدْرِي لِمَاذَا تَشْغَلُ بَالَكَ بِمَا لَا يَجُرُّ عَلَيْكَ إِلَّا الضِّيقَ وَالْحُزْنَ.",segs:[{ar:"لَا أَدْرِي",uz:"bilmayman"},{ar:"لِمَاذَا تَشْغَلُ بَالَكَ",uz:"nega xayolingizni band qilasiz"},{ar:"بِمَا لَا يَجُرُّ عَلَيْكَ",uz:"sizga olib kelmaydigan narsa bilan"},{ar:"إِلَّا الضِّيقَ وَالْحُزْنَ",uz:"siqilish va g‘amdan boshqa hech narsa"}],full_uz:"Sizga siqilish va g‘amdan boshqa hech narsa keltirmaydigan ish bilan nega xayolingizni band qilishingizni bilmayman.",note:"شَغَلَ بَالَهُ — «xayolini band qildi». لَا ... إِلَّا tuzilishi «faqat ...» ma’nosini beradi."},
{num:24,time:"00:03:24,460 --> 00:03:27,840",arabic:"أَنْتِ تَقُولِينَ هَذَا يَا فَوْزُ؟",segs:[{ar:"أَنْتِ تَقُولِينَ هَذَا",uz:"buni siz aytyapsizmi"},{ar:"يَا فَوْزُ",uz:"ey Favz"}],full_uz:"Buni siz aytyapsizmi, Favz?",note:"أَنْتِ va تَقُولِينَ ayol kishiga qaratilgan. Gap boshidagi أَنْتِ ta’kidni kuchaytiradi."},
{num:25,time:"00:03:27,840 --> 00:03:32,219",arabic:"إِنَّكِ لَمْ تُفْنِي عُمْرَكِ فِي خِدْمَةِ السُّلْطَانِ وَأَبْنَائِهِ.",segs:[{ar:"إِنَّكِ لَمْ تُفْنِي عُمْرَكِ",uz:"axir siz umringizni sarflamagansiz"},{ar:"فِي خِدْمَةِ السُّلْطَانِ",uz:"sultonga xizmat qilishga"},{ar:"وَأَبْنَائِهِ",uz:"va uning o‘g‘illariga"}],full_uz:"Axir siz umringizni sulton va uning o‘g‘illariga xizmat qilishga sarflamagansiz.",note:"أَفْنَى عُمْرَهُ فِي — «umrini ...ga sarfladi». تُفْنِينَ fe’li لَمْ dan keyin nunini yo‘qotib, تُفْنِي bo‘ladi."},
{num:26,time:"00:03:32,219 --> 00:03:38,319",arabic:"ثُمَّ تَرَيْنَ ثَمَرَةَ ذَلِكَ تَذْهَبُ إِلَى أُنَاسٍ لَمْ يَكُونُوا إِلَّا خَدَمًا وَصُنَّاعًا بَيْنَ أَيْدِينَا.",segs:[{ar:"ثُمَّ تَرَيْنَ",uz:"keyin esa ko‘rasiz"},{ar:"ثَمَرَةَ ذَلِكَ",uz:"buning samarasini"},{ar:"تَذْهَبُ إِلَى أُنَاسٍ",uz:"ayrim odamlarga ketayotganini"},{ar:"لَمْ يَكُونُوا إِلَّا",uz:"ular ...dan boshqa bo‘lmagan"},{ar:"خَدَمًا وَصُنَّاعًا",uz:"xizmatkorlar va hunarmandlar"},{ar:"بَيْنَ أَيْدِينَا",uz:"qo‘limiz ostida"}],full_uz:"Keyin esa buning samarasi qo‘limiz ostidagi xizmatkor va hunarmandlardan boshqa hech kim bo‘lmagan odamlarga ketayotganini ko‘rasiz.",note:"بَيْنَ أَيْدِينَا so‘zma-so‘z «qo‘llarimiz orasida»; bu yerda «qo‘limiz ostida». صُنَّاعٌ — صَانِعٌ so‘zining ko‘pligi."},
{num:27,time:"00:03:38,319 --> 00:03:44,580",arabic:"لَا تُبَالِغْ يَا أَبَا الْجَحْجَاحِ.",segs:[{ar:"لَا تُبَالِغْ",uz:"oshirib yubormang"},{ar:"يَا أَبَا الْجَحْجَاحِ",uz:"ey Abu Jahjoh"}],full_uz:"Oshirib yubormang, Abu Jahjoh.",note:"لَا taqiq bildirgani uchun تُبَالِغْ fe’li jazm holatida, oxiri sukunli kelgan."},
{num:28,time:"00:03:44,580 --> 00:03:46,360",arabic:"وَاغْفِرْ لِي قَوْلِي هَذَا.",segs:[{ar:"وَاغْفِرْ لِي",uz:"meni kechiring"},{ar:"قَوْلِي هَذَا",uz:"bu gapim uchun"}],full_uz:"Bu gapim uchun meni kechiring.",note:null},
{num:29,time:"00:03:46,360 --> 00:03:49,200",arabic:"إِنَّكَ تُحَمِّلُ الْأُمُورَ فَوْقَ مَا تُطِيقُ.",segs:[{ar:"إِنَّكَ تُحَمِّلُ الْأُمُورَ",uz:"siz ishlarga yuklayapsiz"},{ar:"فَوْقَ مَا تُطِيقُ",uz:"ular ko‘tara oladiganidan ortiq"}],full_uz:"Siz ishlarga ular ko‘tara oladiganidan ortiq yuk yuklayapsiz.",note:"حَمَّلَ — «yukladi»; أَطَاقَ — «kuchi yetdi, ko‘tara oldi». Gap vaziyatga ortiqcha ma’no yoki ahamiyat yuklash haqida."},
{num:30,time:"00:03:49,200 --> 00:03:51,159",arabic:"وَكَيْفَ ذَلِكَ يَا فَوْزُ؟",segs:[{ar:"وَكَيْفَ ذَلِكَ",uz:"bu qanday deganingiz"},{ar:"يَا فَوْزُ",uz:"ey Favz"}],full_uz:"Bu qanday deganingiz, Favz?",note:null},
{num:31,time:"00:03:51,159 --> 00:03:53,460",arabic:"مَا يُعَذِّبُكَ وَيُنَغِّصُ عَلَيْكَ أَيَّامَكَ...",segs:[{ar:"مَا يُعَذِّبُكَ",uz:"sizni qiynayotgan narsa"},{ar:"وَيُنَغِّصُ عَلَيْكَ أَيَّامَكَ",uz:"va kunlaringizni g‘amga to‘ldirayotgan narsa"}],full_uz:"Sizni qiynayotgan va kunlaringizni g‘amga to‘ldirayotgan narsa...",note:"نَغَّصَ عَلَيْهِ حَيَاتَهُ — «uning hayotini g‘amga to‘ldirdi, hayoti huzurini buzdi»."},
{num:32,time:"00:03:53,460 --> 00:03:56,040",arabic:"هُوَ إِحْسَاسُكَ بِالْخِذْلَانِ وَنُكْرَانِ الْجَمِيلِ.",segs:[{ar:"هُوَ إِحْسَاسُكَ",uz:"bu sizning his qilishingizdir"},{ar:"بِالْخِذْلَانِ",uz:"yordamsiz tashlab qo‘yilganingizni"},{ar:"وَنُكْرَانِ الْجَمِيلِ",uz:"va yaxshiligingiz qadrlanmaganini"}],full_uz:"Bu — yordamsiz tashlab qo‘yilganingizni va yaxshiligingiz qadrlanmaganini his qilishingizdir.",note:"الْخِذْلَانُ — kerak paytda yordamsiz qoldirish. نُكْرَانُ الْجَمِيلِ — yaxshilikni tan olmaslik, nonko‘rlik."},
{num:33,time:"00:03:56,040 --> 00:04:00,800",arabic:"أَيْ أَنَّكَ تَحْتَكِمُ فِي عَلَاقَتِكَ مَعَ السُّلْطَانِ لِلْعَوَاطِفِ وَالْمَشَاعِرِ.",segs:[{ar:"أَيْ أَنَّكَ تَحْتَكِمُ",uz:"ya’ni siz mezon qilib olasiz"},{ar:"فِي عَلَاقَتِكَ مَعَ السُّلْطَانِ",uz:"sulton bilan munosabatingizda"},{ar:"لِلْعَوَاطِفِ وَالْمَشَاعِرِ",uz:"his-tuyg‘ularni"}],full_uz:"Ya’ni sulton bilan munosabatingizda his-tuyg‘ularni mezon qilib olasiz.",note:"اِحْتَكَمَ — hukm chiqarishda biror narsa yoki kishiga murojaat qildi; bu yerda «mezon qilib oldi»."},
{num:34,time:"00:04:00,800 --> 00:04:05,800",arabic:"بَيْنَمَا السُّلْطَانُ لَا يَحْتَكِمُ فِي عَلَاقَتِهِ مَعَ الْآخَرِينَ لِلْعَوَاطِفِ وَالْمَشَاعِرِ.",segs:[{ar:"بَيْنَمَا السُّلْطَانُ",uz:"sulton esa"},{ar:"لَا يَحْتَكِمُ",uz:"mezon qilib olmaydi"},{ar:"فِي عَلَاقَتِهِ مَعَ الْآخَرِينَ",uz:"boshqalar bilan munosabatida"},{ar:"لِلْعَوَاطِفِ وَالْمَشَاعِرِ",uz:"his-tuyg‘ularni"}],full_uz:"Sulton esa boshqalar bilan munosabatida his-tuyg‘ularni mezon qilib olmaydi.",note:"بَيْنَمَا bu yerda vaqtni emas, ikki holat orasidagi qarama-qarshilikni bildiradi: «...esa»."},
{num:35,time:"00:04:05,800 --> 00:04:09,640",arabic:"بَلْ يَحْتَكِمُ لِلْمَصَالِحِ وَيُقَرِّبُ مَنْ يَخْدُمُهُ.",segs:[{ar:"بَلْ يَحْتَكِمُ لِلْمَصَالِحِ",uz:"balki manfaatlarni mezon qilib oladi"},{ar:"وَيُقَرِّبُ",uz:"va o‘ziga yaqinlashtiradi"},{ar:"مَنْ يَخْدُمُهُ",uz:"unga xizmat qiladigan kishini"}],full_uz:"Balki manfaatlarni mezon qilib oladi va unga xizmat qiladigan kishini o‘ziga yaqinlashtiradi.",note:"قَرَّبَ — «yaqinlashtirdi»; قَرُبَ — «yaqin bo‘ldi». مَنْ bu yerda «...adigan kishi» ma’nosida."},
{num:36,time:"00:04:09,640 --> 00:04:12,659",arabic:"وَيَبْدُو أَنَّكَ لَمْ تَعُدْ تَخْدُمُ مَا يُرِيدُونَ.",segs:[{ar:"وَيَبْدُو أَنَّكَ",uz:"aftidan, siz"},{ar:"لَمْ تَعُدْ تَخْدُمُ",uz:"endi xizmat qilmay qo‘ygansiz"},{ar:"مَا يُرِيدُونَ",uz:"ular istayotgan narsaga"}],full_uz:"Aftidan, siz endi ular istayotgan narsaga xizmat qilmay qo‘ygansiz.",note:"لَمْ يَعُدْ + muzori’ fe’l — «endi ...may qo‘ydi». Bu yerda عَادَ «qaytdi» ma’nosida emas."},
{num:37,time:"00:04:12,659 --> 00:04:16,460",arabic:"لِذَلِكَ يُهَمِّشُونَكَ وَيُبْعِدُونَكَ عَنِ الْمَنَاصِبِ الْحَسَّاسَةِ.",segs:[{ar:"لِذَلِكَ يُهَمِّشُونَكَ",uz:"shu sababli sizni chetga surishmoqda"},{ar:"وَيُبْعِدُونَكَ",uz:"va uzoqlashtirishmoqda"},{ar:"عَنِ الْمَنَاصِبِ الْحَسَّاسَةِ",uz:"muhim lavozimlardan"}],full_uz:"Shu sababli sizni chetga surib, muhim lavozimlardan uzoqlashtirishmoqda.",note:"هَمَّشَ — «chetga surdi, ta’sirini kamaytirdi». الْمَنَاصِبُ الْحَسَّاسَةُ — katta ahamiyat va mas’uliyatga ega lavozimlar."},
{num:38,time:"00:04:16,460 --> 00:04:19,620",arabic:"وَإِنْ أَرَدْتَ رَأْيِي، هَذَا أَفْضَلُ لَكَ.",segs:[{ar:"وَإِنْ أَرَدْتَ رَأْيِي",uz:"fikrimni bilmoqchi bo‘lsangiz"},{ar:"هَذَا أَفْضَلُ لَكَ",uz:"bu siz uchun yaxshiroq"}],full_uz:"Fikrimni bilmoqchi bo‘lsangiz, bu siz uchun yaxshiroq.",note:null},
{num:39,time:"00:04:19,620 --> 00:04:21,540",arabic:"غَادِرْهُمْ قَبْلَ أَنْ يَطْرُدُوكَ.",segs:[{ar:"غَادِرْهُمْ",uz:"ularni tark eting"},{ar:"قَبْلَ أَنْ يَطْرُدُوكَ",uz:"sizni haydab yuborishlaridan oldin"}],full_uz:"Sizni haydab yuborishlaridan oldin ularni tark eting.",note:"يَطْرُدُونَ fe’li أَنْ dan keyin nunini yo‘qotadi: يَطْرُدُوكَ — «sizni haydashlari»."},
{num:40,time:"00:04:23,459 --> 00:04:32,099",arabic:"قَدْ تَكُونِينَ عَلَى حَقٍّ يَا فَوْزُ.",segs:[{ar:"قَدْ تَكُونِينَ عَلَى حَقٍّ",uz:"balki haqdirsiz"},{ar:"يَا فَوْزُ",uz:"ey Favz"}],full_uz:"Balki haqdirsiz, Favz.",note:"قَدْ muzori’ fe’l bilan bu yerda ehtimolni bildiradi. عَلَى حَقٍّ — «haq, to‘g‘ri fikrda»."},
{num:41,time:"00:04:32,099 --> 00:04:37,199",arabic:"قَدْ تَكُونِينَ عَلَى حَقٍّ.",segs:[{ar:"قَدْ تَكُونِينَ",uz:"balki siz ...dirsiz"},{ar:"عَلَى حَقٍّ",uz:"haq"}],full_uz:"Balki haqdirsiz.",note:null},
{num:42,time:"00:04:37,199 --> 00:04:42,139",arabic:"بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ.",segs:[{ar:"بِسْمِ اللَّهِ",uz:"Allohning nomi bilan"},{ar:"الرَّحْمَٰنِ الرَّحِيمِ",uz:"mehribon va rahmli"}],full_uz:"Mehribon va rahmli Allohning nomi bilan.",note:null},
{num:43,time:"00:04:42,139 --> 00:04:44,679",arabic:"مَا شَاءَ اللَّهُ، وَالْحَمْدُ لِلَّهِ.",segs:[{ar:"مَا شَاءَ اللَّهُ",uz:"Alloh xohlagan narsa"},{ar:"وَالْحَمْدُ لِلَّهِ",uz:"Allohga hamd bo‘lsin"}],full_uz:"Mashaalloh, Allohga hamd bo‘lsin.",note:"مَا شَاءَ اللَّهُ — hayrat yoki mamnunlikni ifodalashda aytiladigan ibora; so‘zma-so‘z «Alloh xohlagan narsa»."},
{num:44,time:"00:04:49,439 --> 00:04:52,919",arabic:"كَيْفَ تَجِدِينَ نَفْسَكِ الْيَوْمَ يَا عَبَّاسَةُ؟",segs:[{ar:"كَيْفَ تَجِدِينَ نَفْسَكِ",uz:"o‘zingizni qanday his qilyapsiz"},{ar:"الْيَوْمَ",uz:"bugun"},{ar:"يَا عَبَّاسَةُ",uz:"ey Abbosa"}],full_uz:"Bugun o‘zingizni qanday his qilyapsiz, Abbosa?",note:"كَيْفَ تَجِدُ نَفْسَكَ؟ — ahvol so‘rash usuli. تَجِدِينَ va نَفْسَكِ ayol kishiga qaratilgan."},
{num:45,time:"00:04:52,920 --> 00:04:57,800",arabic:"الْحَمْدُ لِلَّهِ، أَنَا بِخَيْرٍ مَا دُمْتَ أَنْتَ بِخَيْرٍ.",segs:[{ar:"الْحَمْدُ لِلَّهِ",uz:"Allohga hamd bo‘lsin"},{ar:"أَنَا بِخَيْرٍ",uz:"men yaxshiman"},{ar:"مَا دُمْتَ أَنْتَ بِخَيْرٍ",uz:"siz yaxshi ekansiz"}],full_uz:"Allohga hamd bo‘lsin. Siz yaxshi ekansiz, men ham yaxshiman.",note:"مَا دَامَ — «...ekan, ...bo‘lib turgan ekan». دُمْتَ — shu fe’lning «siz» uchun shakli."},
{num:46,time:"00:04:57,800 --> 00:05:00,920",arabic:"وَكَيْفَ حَالُ هَذَا الْفَتَى الشَّيْبَانِيِّ؟",segs:[{ar:"وَكَيْفَ حَالُ",uz:"ahvoli qanday"},{ar:"هَذَا الْفَتَى الشَّيْبَانِيِّ",uz:"bu shayboniy yigitning"}],full_uz:"Bu shayboniy yigitning ahvoli qanday?",note:"الشَّيْبَانِيُّ — Shaybon qabilasiga mansublikni bildiruvchi nisba."},
{num:47,time:"00:05:02,360 --> 00:05:06,319",arabic:"كَمَا تَرَى، إِنَّهُ بِخَيْرٍ وَالْحَمْدُ لِلَّهِ.",segs:[{ar:"كَمَا تَرَى",uz:"ko‘rib turganingizdek"},{ar:"إِنَّهُ بِخَيْرٍ",uz:"u yaxshi"},{ar:"وَالْحَمْدُ لِلَّهِ",uz:"Allohga hamd bo‘lsin"}],full_uz:"Ko‘rib turganingizdek, u yaxshi, Allohga hamd bo‘lsin.",note:null},
{num:48,time:"00:05:06,319 --> 00:05:07,259",arabic:"الْحَمْدُ لِلَّهِ.",segs:null,full_uz:"Allohga hamd bo‘lsin.",note:null},
{num:49,time:"00:05:07,259 --> 00:05:10,920",arabic:"لَمْ تَقُلْ لِي مَاذَا سَتُسَمِّيهِ؟",segs:[{ar:"لَمْ تَقُلْ لِي",uz:"menga aytmadingiz"},{ar:"مَاذَا سَتُسَمِّيهِ",uz:"unga qanday ism qo‘yasiz"}],full_uz:"Unga qanday ism qo‘yishingizni menga aytmadingiz.",note:"سَمَّى — «ism qo‘ydi»; سَتُسَمِّيهِ — «unga ism qo‘yasiz». تَقُولُ fe’li لَمْ dan keyin تَقُلْ bo‘ladi."},
{num:50,time:"00:05:15,660 --> 00:05:21,600",arabic:"اسْمُهُ صَالِحٌ، لَعَلَّهُ يَكُونُ جَدِيرًا بِهَذَا الِاسْمِ.",segs:[{ar:"اسْمُهُ صَالِحٌ",uz:"uning ismi Solih"},{ar:"لَعَلَّهُ يَكُونُ جَدِيرًا",uz:"umid qilamanki, u munosib bo‘ladi"},{ar:"بِهَذَا الِاسْمِ",uz:"bu ismga"}],full_uz:"Uning ismi Solih. Umid qilamanki, bu ismga munosib bo‘ladi.",note:"صَالِحٌ ism bo‘lishidan tashqari «yaxshi, solih» degan ma’noga ega. جَدِيرٌ بِـ — «...ga munosib»."},
{num:51,time:"00:05:21,600 --> 00:05:26,740",arabic:"صَالِحٌ، نِعْمَ مَا اخْتَرْتَ يَا أَبَا صَالِحٍ.",segs:[{ar:"صَالِحٌ",uz:"Solih"},{ar:"نِعْمَ مَا اخْتَرْتَ",uz:"qanday yaxshi tanlov qildingiz"},{ar:"يَا أَبَا صَالِحٍ",uz:"ey Solihning otasi"}],full_uz:"Solih! Qanday yaxshi tanlov qildingiz, Abu Solih.",note:"نِعْمَ — maqtov bildiruvchi fe’l. أَبُو صَالِحٍ — «Solihning otasi» ma’nosidagi kunya."},
{num:52,time:"00:05:26,740 --> 00:05:40,780",arabic:"أَلَا يَكْفِي أَنَّ أَمِيرَ الْمُؤْمِنِينَ سَمَحَ لَهُمْ أَنْ يَنْشُرُوا الْمُعْتَقَدَاتِ الْفَاسِدَةَ وَالْآرَاءَ الشَّاذَّةَ؟",segs:[{ar:"أَلَا يَكْفِي",uz:"yetarli emasmi"},{ar:"أَنَّ أَمِيرَ الْمُؤْمِنِينَ",uz:"mo‘minlar amirining"},{ar:"سَمَحَ لَهُمْ",uz:"ularga ruxsat bergani"},{ar:"أَنْ يَنْشُرُوا",uz:"tarqatishlariga"},{ar:"الْمُعْتَقَدَاتِ الْفَاسِدَةَ",uz:"buzuq e’tiqodlarni"},{ar:"وَالْآرَاءَ الشَّاذَّةَ",uz:"va umumiy qarashlardan chetga chiqqan fikrlarni"}],full_uz:"Mo‘minlar amiri ularga buzuq e’tiqodlar va umumiy qarashlardan chetga chiqqan fikrlarni tarqatishga ruxsat bergani yetarli emasmi?",note:"سَمَحَ لَهُ أَنْ — «unga ...ishga ruxsat berdi». شَاذٌّ — odatiy yoki umum qabul qilingan yo‘ldan chetga chiqqan."},
{num:53,time:"00:05:40,780 --> 00:05:49,600",arabic:"غَرِيبٌ، غَرِيبٌ أَمْرُ هَؤُلَاءِ الْقَوْمِ، لَا يَعْرِفُونَ مِنَ الدِّينِ إِلَّا الْقُشُورَ.",segs:[{ar:"غَرِيبٌ، غَرِيبٌ",uz:"g‘alati, g‘alati"},{ar:"أَمْرُ هَؤُلَاءِ الْقَوْمِ",uz:"bu qavmning ishi"},{ar:"لَا يَعْرِفُونَ مِنَ الدِّينِ",uz:"ular dindan bilishmaydi"},{ar:"إِلَّا الْقُشُورَ",uz:"faqat tashqi tomoninigina"}],full_uz:"G‘alati, bu qavmning ishi g‘alati. Ular dinning faqat tashqi tomoninigina bilishadi.",note:"قُشُورٌ — قِشْرٌ («po‘stloq»)ning ko‘pligi; bu yerda bir narsaning mohiyatiga kirmagan tashqi jihatlari nazarda tutilgan."},
{num:54,time:"00:05:49,600 --> 00:05:54,240",arabic:"وَحِينَ يَتَصَدَّى إِخْوَتُهُمْ لِلزَّنَادِقَةِ وَالْمُلْحِدِينَ...",segs:[{ar:"وَحِينَ يَتَصَدَّى إِخْوَتُهُمْ",uz:"birodarlari qarshi turganida esa"},{ar:"لِلزَّنَادِقَةِ وَالْمُلْحِدِينَ",uz:"zindiqlar va dinsizlarga"}],full_uz:"Birodarlari zindiqlar va dinsizlarga qarshi turganida esa...",note:"تَصَدَّى لِـ — «...ga qarshi turdi, ...bilan kurashishga kirishdi». زَنَادِقَةٌ — زِنْدِيقٌ so‘zining ko‘pligi."},
{num:55,time:"00:05:54,240 --> 00:05:58,800",arabic:"وَيُبَيِّنُونَ لِلنَّاسِ مَا غَابَ عَنْهُمْ مِنْ أُمُورِ الدِّينِ...",segs:[{ar:"وَيُبَيِّنُونَ لِلنَّاسِ",uz:"va odamlarga tushuntirganlarida"},{ar:"مَا غَابَ عَنْهُمْ",uz:"ularga noma’lum bo‘lgan narsalarni"},{ar:"مِنْ أُمُورِ الدِّينِ",uz:"din ishlaridan"}],full_uz:"Va odamlarga din ishlaridan ularga noma’lum bo‘lgan narsalarni tushuntirganlarida...",note:"غَابَ عَنْهُ bu yerda «unga noma’lum bo‘ldi, uning nazaridan chetda qoldi» ma’nosida."},
{num:56,time:"00:05:58,800 --> 00:06:04,540",arabic:"لَا تَجِدُ مِنْهُمْ إِلَّا اعْتِرَاضًا عَلَى مُجَاهَرَتِنَا بِالْحَقِّ.",segs:[{ar:"لَا تَجِدُ مِنْهُمْ",uz:"ulardan ko‘rmaysiz"},{ar:"إِلَّا اعْتِرَاضًا",uz:"e’tirozdan boshqa narsani"},{ar:"عَلَى مُجَاهَرَتِنَا بِالْحَقِّ",uz:"haqni oshkora aytishimizga"}],full_uz:"Ulardan haqni oshkora aytishimizga e’tirozdan boshqa narsani ko‘rmaysiz.",note:"جَاهَرَ بِالشَّيْءِ — «bir narsani oshkora aytdi yoki namoyon qildi». مُجَاهَرَةٌ — uning masdari."},
{num:57,time:"00:06:04,540 --> 00:06:07,600",arabic:"أَلَيْسَ هَذَا بِالشَّيْءِ الْعَجِيبِ؟",segs:[{ar:"أَلَيْسَ هَذَا",uz:"bu emasmi"},{ar:"بِالشَّيْءِ الْعَجِيبِ",uz:"ajablanarli narsa"}],full_uz:"Bu ajablanarli narsa emasmi?",note:"لَيْسَ ning xabariga kirgan بِـ inkorni ta’kidlaydi; tarjimada alohida «bilan» ma’nosini bermaydi."},
{num:58,time:"00:06:08,700 --> 00:06:11,600",arabic:"وَأَيُّ غَرَابَةٍ فِي ذَلِكَ يَا أَبَا عَبْدِ الرَّحْمَٰنِ؟",segs:[{ar:"وَأَيُّ غَرَابَةٍ فِي ذَلِكَ",uz:"buning nimasi g‘alati"},{ar:"يَا أَبَا عَبْدِ الرَّحْمَٰنِ",uz:"ey Abu Abdurahmon"}],full_uz:"Buning nimasi g‘alati, Abu Abdurahmon?",note:null},
{num:59,time:"00:06:12,400 --> 00:06:15,500",arabic:"قَوْمٌ عَطَّلُوا الْعَقْلَ فِي أُمُورِ الدِّينِ.",segs:[{ar:"قَوْمٌ عَطَّلُوا الْعَقْلَ",uz:"aqlni ishlatmay qo‘ygan qavm"},{ar:"فِي أُمُورِ الدِّينِ",uz:"din ishlarida"}],full_uz:"Ular din ishlarida aqlni ishlatmay qo‘ygan qavm.",note:"عَطَّلَ — «ishdan to‘xtatdi, faoliyatsiz qoldirdi». عَطَّلُوا الْعَقْلَ — «aqlni ishlatmay qo‘ydilar»."},
{num:60,time:"00:06:15,500 --> 00:06:18,480",arabic:"أَيُعْمِلُونَهُ فِي أُمُورِ الدُّنْيَا؟",segs:[{ar:"أَيُعْمِلُونَهُ",uz:"uni ishga solisharmidi"},{ar:"فِي أُمُورِ الدُّنْيَا",uz:"dunyo ishlarida"}],full_uz:"Uni dunyo ishlarida ishga solisharmidi?",note:"أَعْمَلَ عَقْلَهُ — «aqlini ishga soldi». أَ so‘roq yuklamasi يُعْمِلُونَهُ fe’liga qo‘shilgan."},
{num:61,time:"00:06:19,600 --> 00:06:22,900",arabic:"لَعَلَّكَ عَلَى حَقٍّ يَا ابْنَ الْأَشْرَسِ.",segs:[{ar:"لَعَلَّكَ عَلَى حَقٍّ",uz:"balki haqdirsiz"},{ar:"يَا ابْنَ الْأَشْرَسِ",uz:"ey Ibn Ashras"}],full_uz:"Balki haqdirsiz, Ibn Ashras.",note:null},
{num:62,time:"00:06:22,900 --> 00:06:25,240",arabic:"وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ.",segs:[{ar:"وَلَا تَبْخَسُوا النَّاسَ",uz:"odamlarning haqini kamaytirmang"},{ar:"أَشْيَاءَهُمْ",uz:"ularga tegishli narsalarda"}],full_uz:"Odamlarning o‘zlariga tegishli narsalarini kamaytirib bermang.",note:"بَخَسَ — «haqini kamaytirdi, qadrsizlantirdi». Bu suhbatda kishilarning ilmiy qadrini pastga urmaslik nazarda tutilgan."},
{num:63,time:"00:06:25,240 --> 00:06:31,040",arabic:"إِنَّ الَّذِينَ تَتَحَدَّثُونَ عَنْهُمْ هُمْ عُلَمَاءُ الْأُمَّةِ وَشُيُوخُهَا.",segs:[{ar:"إِنَّ الَّذِينَ تَتَحَدَّثُونَ عَنْهُمْ",uz:"siz gapirayotgan kishilar"},{ar:"هُمْ عُلَمَاءُ الْأُمَّةِ",uz:"ular ummatning olimlaridir"},{ar:"وَشُيُوخُهَا",uz:"va uning shayxlaridir"}],full_uz:"Siz gapirayotgan kishilar ummatning olimlari va shayxlaridir.",note:"تَحَدَّثَ عَنْ — «...haqida gapirdi». الَّذِينَ dan keyingi gap kimlar nazarda tutilganini aniqlaydi."},
{num:64,time:"00:06:31,040 --> 00:06:34,520",arabic:"وَهُمْ لَا يُعَطِّلُونَ عُقُولَهُمْ كَمَا تَزْعُمُونَ.",segs:[{ar:"وَهُمْ لَا يُعَطِّلُونَ عُقُولَهُمْ",uz:"ular aqllarini ishlatmay qo‘yishmagan"},{ar:"كَمَا تَزْعُمُونَ",uz:"siz da’vo qilayotganingizdek"}],full_uz:"Ular siz da’vo qilayotganingizdek aqllarini ishlatmay qo‘yishmagan.",note:"زَعَمَ — «da’vo qildi». Ko‘pincha aytilgan fikrga shubha yoki e’tiroz borligini anglatadi."},
{num:65,time:"00:06:34,520 --> 00:06:39,740",arabic:"وَإِنَّمَا يُقَدِّمُونَ النَّصَّ وَالنَّقْلَ عَلَى الرَّأْيِ وَالْعَقْلِ.",segs:[{ar:"وَإِنَّمَا يُقَدِّمُونَ",uz:"ular faqat ustun qo‘yishadi"},{ar:"النَّصَّ وَالنَّقْلَ",uz:"diniy matn va rivoyatni"},{ar:"عَلَى الرَّأْيِ وَالْعَقْلِ",uz:"shaxsiy fikr va aqldan"}],full_uz:"Ular faqat diniy matn va rivoyatni shaxsiy fikr va aqldan ustun qo‘yishadi.",note:"قَدَّمَ شَيْئًا عَلَى شَيْءٍ — «bir narsani boshqasidan ustun qo‘ydi». النَّقْلُ bu yerda naql qilingan diniy xabarlarni anglatadi."},
{num:66,time:"00:06:39,740 --> 00:06:47,520",arabic:"أَتَرَى فِي النَّصِّ وَالنَّقْلِ عَقْلًا يَفْهَمُ وَلِسَانًا يَشْرَحُ يَا ابْنَ أَكْثَمَ؟",segs:[{ar:"أَتَرَى",uz:"ko‘ryapsizmi"},{ar:"فِي النَّصِّ وَالنَّقْلِ",uz:"matn va rivoyatning o‘zida"},{ar:"عَقْلًا يَفْهَمُ",uz:"tushunadigan aqlni"},{ar:"وَلِسَانًا يَشْرَحُ",uz:"va sharhlaydigan tilni"},{ar:"يَا ابْنَ أَكْثَمَ",uz:"ey Ibn Aksam"}],full_uz:"Matn va rivoyatning o‘zida tushunadigan aql va sharhlaydigan tilni ko‘ryapsizmi, Ibn Aksam?",note:"يَفْهَمُ va يَشْرَحُ fe’lli gaplari o‘zlaridan oldingi noaniq otlarni sifatlaydi: «tushunadigan aql», «sharhlaydigan til»."},
{num:67,time:"00:06:47,519 --> 00:06:59,959",arabic:"إِنَّا لَمْ نَضَعْ عَلَى الْكَلَامِ شَرْطًا.",segs:[{ar:"إِنَّا لَمْ نَضَعْ",uz:"biz qo‘ymadik"},{ar:"عَلَى الْكَلَامِ شَرْطًا",uz:"gapirishga biror shart"}],full_uz:"Biz gapirishga biror shart qo‘ymadik.",note:"وَضَعَ — يَضَعُ: muzori’da boshidagi و tushadi. لَمْ نَضَعْ — «biz qo‘ymadik»."},
{num:68,time:"00:06:59,959 --> 00:07:02,939",arabic:"وَلَا عَلَى اللِّسَانِ قَيْدًا.",segs:[{ar:"وَلَا عَلَى اللِّسَانِ",uz:"tilga ham ...madik"},{ar:"قَيْدًا",uz:"biror kishan"}],full_uz:"Tilga ham biror kishan solmadik.",note:"Oldingi banddagi لَمْ نَضَعْ mazmuni davom etadi. قَيْدٌ — «kishan, bog‘lov»; ko‘chma ma’noda cheklov."},
{num:69,time:"00:07:02,939 --> 00:07:07,060",arabic:"فَمَنْ نَطَقَ بِالْحَقِّ حَمِدْنَاهُ.",segs:[{ar:"فَمَنْ نَطَقَ بِالْحَقِّ",uz:"kim haqni gapirsa"},{ar:"حَمِدْنَاهُ",uz:"uni maqtaymiz"}],full_uz:"Kim haqni gapirsa, uni maqtaymiz.",note:"مَنْ shart ma’nosida kelgan. Shaklan o‘tgan zamondagi fe’llar bu tuzilishda umumiy qoida yoki kelajakdagi natijani bildirishi mumkin."},
{num:70,time:"00:07:07,060 --> 00:07:10,859",arabic:"وَمَنْ جَهِلَ ذَلِكَ أَوْقَفْنَاهُ.",segs:[{ar:"وَمَنْ جَهِلَ ذَلِكَ",uz:"kim buni bilmasa"},{ar:"أَوْقَفْنَاهُ",uz:"uni to‘xtatamiz"}],full_uz:"Kim buni bilmasa, uni to‘xtatamiz.",note:"أَوْقَفَ — «to‘xtatdi»; وَقَفَ — «to‘xtadi, turdi»."},
{num:71,time:"00:07:10,859 --> 00:07:13,459",arabic:"وَمَنْ جَهِلَ الْأَمْرَيْنِ مَعًا...",segs:[{ar:"وَمَنْ جَهِلَ الْأَمْرَيْنِ",uz:"kim ikki ishni bilmasa"},{ar:"مَعًا",uz:"ikkalasini ham"}],full_uz:"Kim bu ikki ishning ikkalasini ham bilmasa...",note:"الْأَمْرَيْنِ — الْأَمْرُ so‘zining ikkilik tushum shakli: «ikki ishni»."},
{num:72,time:"00:07:13,459 --> 00:07:15,899",arabic:"حَكَمْنَا فِيهِ بِمَا يَجِبُ.",segs:[{ar:"حَكَمْنَا فِيهِ",uz:"uning haqida hukm chiqaramiz"},{ar:"بِمَا يَجِبُ",uz:"lozim bo‘lgan tarzda"}],full_uz:"Uning haqida lozim bo‘lgan tarzda hukm chiqaramiz.",note:null},
{num:73,time:"00:07:17,519 --> 00:07:19,500",arabic:"لَقَدْ طَفَحَ الْكَيْلُ يَا أَبَا الْعَبَّاسِ.",segs:[{ar:"لَقَدْ طَفَحَ الْكَيْلُ",uz:"sabr kosasi to‘ldi"},{ar:"يَا أَبَا الْعَبَّاسِ",uz:"ey Abu Abbos"}],full_uz:"Sabr kosasi to‘ldi, Abu Abbos.",note:"طَفَحَ الْكَيْلُ — so‘zma-so‘z «o‘lchov idishi toshdi»; «chidashning chegarasiga yetildi» ma’nosidagi ibora."},
{num:74,time:"00:07:19,500 --> 00:07:24,759",arabic:"لَمْ أَعُدْ أَحْتَمِلُ تَسَلُّطَ هَؤُلَاءِ الْعُلُوجِ عَلَى دَوَاوِينِ الْخِلَافَةِ أَكْثَرَ مِنْ ذَلِكَ.",segs:[{ar:"لَمْ أَعُدْ أَحْتَمِلُ",uz:"endi chiday olmayman"},{ar:"تَسَلُّطَ هَؤُلَاءِ الْعُلُوجِ",uz:"bu ajnabiylarning hukmronligiga"},{ar:"عَلَى دَوَاوِينِ الْخِلَافَةِ",uz:"xalifalik devonlari ustidan"},{ar:"أَكْثَرَ مِنْ ذَلِكَ",uz:"bundan ortiq"}],full_uz:"Bu ajnabiylarning xalifalik devonlari ustidan hukmronligiga bundan ortiq chiday olmayman.",note:"عُلُوجٌ — عِلْجٌ so‘zining ko‘pligi; bu nutqda ajnabiylarga nisbatan kamsituvchi atama. دَوَاوِينُ — دِيوَانٌ so‘zining ko‘pligi."},
{num:75,time:"00:07:24,759 --> 00:07:26,959",arabic:"لَا يَا أَبَا الْجَحْجَاحِ.",segs:[{ar:"لَا",uz:"yo‘q"},{ar:"يَا أَبَا الْجَحْجَاحِ",uz:"ey Abu Jahjoh"}],full_uz:"Yo‘q, Abu Jahjoh.",note:null},
{num:76,time:"00:07:26,959 --> 00:07:30,439",arabic:"لَيْسَ هَكَذَا تُسَاسُ الْأُمُورُ يَا شَفِيعُ.",segs:[{ar:"لَيْسَ هَكَذَا",uz:"bunday emas"},{ar:"تُسَاسُ الْأُمُورُ",uz:"ishlarni boshqarish"},{ar:"يَا شَفِيعُ",uz:"ey Shafi’"}],full_uz:"Ishlar bunday boshqarilmaydi, Shafi’.",note:"سَاسَ — يَسُوسُ — «boshqardi». تُسَاسُ — majhul nisbat: «boshqariladi»."},
{num:77,time:"00:07:30,439 --> 00:07:35,579",arabic:"أَيُّ عَمَلٍ يَنْتَظِرُكَ إِنْ تَرَكْتَ خِدْمَةَ أَمِيرِ الْمُؤْمِنِينَ؟",segs:[{ar:"أَيُّ عَمَلٍ يَنْتَظِرُكَ",uz:"sizni qanday ish kutmoqda"},{ar:"إِنْ تَرَكْتَ",uz:"agar tark etsangiz"},{ar:"خِدْمَةَ أَمِيرِ الْمُؤْمِنِينَ",uz:"mo‘minlar amirining xizmatini"}],full_uz:"Mo‘minlar amirining xizmatini tark etsangiz, sizni qanday ish kutmoqda?",note:null},
{num:78,time:"00:07:35,579 --> 00:07:36,479",arabic:"أَنْ أَبْقَى بِلَا عَمَلٍ...",segs:[{ar:"أَنْ أَبْقَى",uz:"qolishim"},{ar:"بِلَا عَمَلٍ",uz:"ishsiz"}],full_uz:"Ishsiz qolishim...",note:"أَنْ أَبْقَى masdar ma’nosidagi birikma bo‘lib, «qolishim» deb tarjima qilinadi. Fikr keyingi bandda tugaydi."},
{num:79,time:"00:07:36,479 --> 00:07:40,939",arabic:"خَيْرٌ لِي مِنْ عَمَلٍ يَقْطِفُ ثِمَارَهُ سِوَايَ مِمَّنْ لَا يَسْتَحِقُّونَ.",segs:[{ar:"خَيْرٌ لِي مِنْ عَمَلٍ",uz:"men uchun bir ishdan yaxshiroq"},{ar:"يَقْطِفُ ثِمَارَهُ سِوَايَ",uz:"mevasini mendan boshqalar teradigan"},{ar:"مِمَّنْ لَا يَسْتَحِقُّونَ",uz:"bunga loyiq bo‘lmaganlardan"}],full_uz:"Mevasini mendan boshqa, bunga loyiq bo‘lmaganlar teradigan ishda ishlashdan ko‘ra men uchun yaxshiroq.",note:"قَطَفَ الثِّمَارَ — «mevalarni terdi»; bu yerda «mehnatning foydasini ko‘rdi». سِوَايَ — «mendan boshqa»."},
{num:80,time:"00:07:40,939 --> 00:07:44,519",arabic:"أَلَا تَرَى كَيْفَ يَتَدَخَّلُونَ فِي كُلِّ صَغِيرَةٍ وَكَبِيرَةٍ؟",segs:[{ar:"أَلَا تَرَى",uz:"ko‘rmayapsizmi"},{ar:"كَيْفَ يَتَدَخَّلُونَ",uz:"qanday aralashayotganlarini"},{ar:"فِي كُلِّ صَغِيرَةٍ وَكَبِيرَةٍ",uz:"har bir mayda-yirik ishga"}],full_uz:"Ularning har bir mayda-yirik ishga qanday aralashayotganlarini ko‘rmayapsizmi?",note:"فِي كُلِّ صَغِيرَةٍ وَكَبِيرَةٍ — «katta-kichik barcha ishlarga». تَدَخَّلَ فِي — «...ga aralashdi»."},
{num:81,time:"00:07:44,519 --> 00:07:49,799",arabic:"وَيُوَلُّونَ الْمَنَاصِبَ الرَّفِيعَةَ فِي الدَّوْلَةِ لِأَبْنَاءِ جِلْدَتِهِمْ دَمًا وَنَسَبًا.",segs:[{ar:"وَيُوَلُّونَ الْمَنَاصِبَ الرَّفِيعَةَ",uz:"yuqori lavozimlarni berishadi"},{ar:"فِي الدَّوْلَةِ",uz:"davlatdagi"},{ar:"لِأَبْنَاءِ جِلْدَتِهِمْ",uz:"o‘z qavmlariga mansub kishilarga"},{ar:"دَمًا وَنَسَبًا",uz:"qon va nasab jihatidan"}],full_uz:"Davlatdagi yuqori lavozimlarni qon va nasab jihatidan o‘z qavmlariga mansub kishilarga berishadi.",note:"أَبْنَاءُ جِلْدَتِهِمْ — «o‘z qavmi, o‘z elatiga mansub kishilar». وَلَّى — «lavozimga tayinladi, boshqaruvni topshirdi»."},
{num:82,time:"00:07:49,799 --> 00:07:50,979",arabic:"أَوْ لِمَنْ عَلَى مَذْهَبِهِمْ.",segs:null,full_uz:"Yoki o‘z mazhablaridagi kishilarga.",note:"مَنْ عَلَى مَذْهَبِهِمْ — «ularning mazhabida bo‘lgan kishi». عَلَى bu yerda qarash yoki yo‘nalishga ergashishni bildiradi."},
{num:83,time:"00:07:50,979 --> 00:07:56,799",arabic:"وَمَاذَا أَقُولُ أَنَا إِذَنْ؟",segs:[{ar:"وَمَاذَا أَقُولُ أَنَا",uz:"men nima deyman"},{ar:"إِذَنْ",uz:"unday bo‘lsa"}],full_uz:"Unday bo‘lsa, men nima deyman?",note:"أَقُولُ fe’lining o‘zida «men» ma’nosi bor; أَنَا alohida keltirilishi uni ta’kidlaydi."},
{num:84,time:"00:07:58,459 --> 00:08:01,240",arabic:"هَا أَنَا ذَا جَالِسٌ فِي دَارِ ذُلٍّ وَامْتِهَانٍ.",segs:[{ar:"هَا أَنَا ذَا جَالِسٌ",uz:"mana men o‘tiribman"},{ar:"فِي دَارِ ذُلٍّ وَامْتِهَانٍ",uz:"xorlik va tahqir uyida"}],full_uz:"Mana men xorlik va tahqir uyida o‘tiribman.",note:"هَا أَنَا ذَا — «mana men». اِمْتِهَانٌ — tahqirlash, qadrini yerga urish."},
{num:85,time:"00:08:01,240 --> 00:08:05,799",arabic:"وَلَوْلَا أَنَّ الْمَأْمُونَ شَمِلَنِي بِعَفْوِهِ...",segs:[{ar:"وَلَوْلَا أَنَّ الْمَأْمُونَ",uz:"agar Ma’mun ...maganida"},{ar:"شَمِلَنِي بِعَفْوِهِ",uz:"meni ham afv etgan"}],full_uz:"Agar Ma’mun meni ham afv etmaganida...",note:"لَوْلَا — «agar ...bo‘lmaganida». Uning natijasi keyingi banddagi لَكُنْتُ bilan keladi."},
{num:86,time:"00:08:06,579 --> 00:08:09,759",arabic:"لَكُنْتُ قَابِعًا خَلْفَ جُدْرَانِ السُّجُونِ.",segs:[{ar:"لَكُنْتُ قَابِعًا",uz:"qamalib yotgan bo‘lardim"},{ar:"خَلْفَ جُدْرَانِ السُّجُونِ",uz:"zindon devorlari ortida"}],full_uz:"Zindon devorlari ortida qamalib yotgan bo‘lardim.",note:"قَبَعَ — bir joyda chiqmay qolib ketdi. قَابِعٌ — shu holatda qolgan kishi."},
{num:87,time:"00:08:09,759 --> 00:08:15,099",arabic:"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ.",segs:[{ar:"لَا حَوْلَ وَلَا قُوَّةَ",uz:"hech qanday qudrat ham, kuch ham yo‘q"},{ar:"إِلَّا بِاللَّهِ",uz:"faqat Allohning yordami bilangina bor"}],full_uz:"Qudrat va kuch faqat Allohning yordami bilangina bo‘ladi.",note:"Bu ibora insonning o‘z kuchi bilan emas, Allohning yordami bilan ish qila olishini ifodalaydi."},
{num:88,time:"00:08:15,099 --> 00:08:19,159",arabic:"مَنْ كَانَ يَظُنُّ أَنَّ الْأُمُورَ سَتَصِلُ بِنَا إِلَى هَذَا الْحَدِّ؟",segs:[{ar:"مَنْ كَانَ يَظُنُّ",uz:"kim o‘ylagan edi"},{ar:"أَنَّ الْأُمُورَ سَتَصِلُ بِنَا",uz:"ishlar bizni olib kelishini"},{ar:"إِلَى هَذَا الْحَدِّ",uz:"shu darajaga"}],full_uz:"Ishlar bizni shu darajaga olib kelishini kim o‘ylagan edi?",note:"وَصَلَ بِهِ إِلَى — «uni ...ga olib keldi, yetkazdi». سَـ kelasi zamonni bildiradi."},
{num:89,time:"00:08:21,800 --> 00:08:23,159",arabic:"الْأَيَّامُ دُوَلٌ بَيْنَ النَّاسِ.",segs:[{ar:"الْأَيَّامُ دُوَلٌ",uz:"kunlar almashinib turadi"},{ar:"بَيْنَ النَّاسِ",uz:"odamlar orasida"}],full_uz:"Yaxshi-yomon kunlar odamlar orasida almashinib turadi.",note:"دُوَلٌ bu iborada davlatlarni emas, baxt va ustunlikning kishilar orasida navbat bilan almashishini anglatadi."},
{num:90,time:"00:08:23,759 --> 00:08:28,159",arabic:"يَوْمٌ لَكَ وَيَوْمٌ عَلَيْكَ.",segs:[{ar:"يَوْمٌ لَكَ",uz:"bir kun sizning foydangizga"},{ar:"وَيَوْمٌ عَلَيْكَ",uz:"bir kun esa zararingizga"}],full_uz:"Bir kun sizning foydangizga, bir kun esa zararingizga.",note:"لَكَ va عَلَيْكَ bu yerda qarama-qarshi ma’noda: «sizning foydangizga» va «sizning zararingizga»."},
{num:91,time:"00:08:28,159 --> 00:08:32,159",arabic:"رَحِمَ اللَّهُ الرَّشِيدَ وَابْنَهُ الْأَمِينَ.",segs:[{ar:"رَحِمَ اللَّهُ الرَّشِيدَ",uz:"Alloh Rashidni rahmatiga olsin"},{ar:"وَابْنَهُ الْأَمِينَ",uz:"va uning o‘g‘li Aminni"}],full_uz:"Alloh Rashidni va uning o‘g‘li Aminni rahmatiga olsin.",note:null},
{num:92,time:"00:08:34,159 --> 00:08:36,580",arabic:"رَحِمَ اللَّهُ تِلْكَ الْأَيَّامَ.",segs:[{ar:"رَحِمَ اللَّهُ",uz:"Alloh rahmat qilsin"},{ar:"تِلْكَ الْأَيَّامَ",uz:"o‘sha kunlarga"}],full_uz:"Alloh o‘sha kunlarga rahmat qilsin.",note:"O‘tgan yaxshi kunlarni sog‘inib eslash ifodasi. الْأَيَّامُ g‘ayri oqil ko‘plik bo‘lgani uchun تِلْكَ birlik muannas ko‘rsatish olmoshi bilan kelgan."},
{num:93,time:"00:08:36,580 --> 00:08:42,500",arabic:"تَوَلَّتْ وَتَوَلَّى مَعَهَا الْعِزُّ وَالْكَرَمُ.",segs:[{ar:"تَوَلَّتْ",uz:"u kunlar o‘tib ketdi"},{ar:"وَتَوَلَّى مَعَهَا",uz:"ular bilan birga ketdi"},{ar:"الْعِزُّ وَالْكَرَمُ",uz:"izzat va saxovat ham"}],full_uz:"U kunlar o‘tib ketdi, ular bilan birga izzat va saxovat ham ketdi.",note:"تَوَلَّى bu yerda «ketdi, o‘tib ketdi». تَوَلَّتْ va مَعَهَا oldingi banddagi الْأَيَّامُ ga qaytadi."},
{num:94,time:"00:08:42,500 --> 00:08:47,620",arabic:"مَا عَلَيْنَا إِلَّا الصَّبْرُ يَا أَبَا الْجَحْجَاحِ.",segs:[{ar:"مَا عَلَيْنَا إِلَّا الصَّبْرُ",uz:"bizga faqat sabr qilish qoladi"},{ar:"يَا أَبَا الْجَحْجَاحِ",uz:"ey Abu Jahjoh"}],full_uz:"Bizga faqat sabr qilish qoladi, Abu Jahjoh.",note:"مَا ... إِلَّا cheklash ma’nosini bildiradi: «faqat ...». عَلَيْنَا majburiyat yoki zimma ma’nosida."},
{num:95,time:"00:08:47,620 --> 00:08:51,780",arabic:"فَلَعَلَّ اللَّهَ يَمُنُّ عَلَيْنَا بِالْخَلَاصِ.",segs:[{ar:"فَلَعَلَّ اللَّهَ",uz:"shoyad Alloh"},{ar:"يَمُنُّ عَلَيْنَا",uz:"bizga marhamat qilsa"},{ar:"بِالْخَلَاصِ",uz:"xalos bo‘lishni berib"}],full_uz:"Shoyad Alloh bizga xalos bo‘lishni nasib etsa.",note:"مَنَّ عَلَيْهِ بِـ — «unga ...ni in’om qildi». الْخَلَاصُ — qutulish, xalos bo‘lish."},
{num:96,time:"00:08:51,780 --> 00:08:54,820",arabic:"أَسْأَلُ اللَّهَ ذَلِكَ.",segs:null,full_uz:"Allohdan shuni so‘rayman.",note:null},
{num:97,time:"00:08:54,820 --> 00:08:58,920",arabic:"وَأَرْجُو مِنْهُ أَلَّا يُخَيِّبَ ظَنِّي.",segs:[{ar:"وَأَرْجُو مِنْهُ",uz:"Undan umid qilaman"},{ar:"أَلَّا يُخَيِّبَ ظَنِّي",uz:"umidimni puchga chiqarmasligini"}],full_uz:"Undan umidimni puchga chiqarmasligini umid qilaman.",note:"خَيَّبَ ظَنَّهُ — «uning umidini puchga chiqardi». أَلَّا — أَنْ va لَا ning qo‘shilgan shakli."},
{num:98,time:"00:08:58,920 --> 00:09:02,379",arabic:"فَأَنَا أَرَى الْأُمُورَ مِنْ سَيِّئٍ إِلَى أَسْوَأَ.",segs:[{ar:"فَأَنَا أَرَى الْأُمُورَ",uz:"men esa ishlarni ko‘ryapman"},{ar:"مِنْ سَيِّئٍ إِلَى أَسْوَأَ",uz:"yomondan battarga ketayotgan"}],full_uz:"Men esa ishlarning yomondan battarga ketayotganini ko‘ryapman.",note:"أَسْوَأُ — «yomonroq, battarroq». مِنْ سَيِّئٍ إِلَى أَسْوَأَ — «yomondan battarga»."},
{num:99,time:"00:09:36,580 --> 00:09:41,879",arabic:"لَا سِيَّمَا أَنَّ أَخَاكَ الْإِيَادِيَّ يَدِينُ بِمَا دَانَ بِهِ أَمِيرُ الْمُؤْمِنِينَ.",segs:[{ar:"لَا سِيَّمَا أَنَّ أَخَاكَ الْإِيَادِيَّ",uz:"ayniqsa, birodaringiz Iyodiy"},{ar:"يَدِينُ بِمَا دَانَ بِهِ",uz:"o‘sha e’tiqodga ergashadi"},{ar:"أَمِيرُ الْمُؤْمِنِينَ",uz:"mo‘minlar amiri ergashgan"}],full_uz:"Ayniqsa, birodaringiz Iyodiy mo‘minlar amiri ergashgan e’tiqodga ergashadi.",note:"دَانَ بِـ — «bir e’tiqodga ishondi, uni din deb bildi». لَا سِيَّمَا — «ayniqsa»."},
{num:100,time:"00:09:41,879 --> 00:09:45,280",arabic:"مَا أَرَاكُمْ إِلَّا مَلَأْتُمْ بَلَاطَ أَمِيرِ الْمُؤْمِنِينَ.",segs:[{ar:"مَا أَرَاكُمْ إِلَّا",uz:"ko‘rishimcha, siz ...siz"},{ar:"مَلَأْتُمْ",uz:"to‘ldirib olgansiz"},{ar:"بَلَاطَ أَمِيرِ الْمُؤْمِنِينَ",uz:"mo‘minlar amirining saroyini"}],full_uz:"Ko‘rishimcha, siz mo‘minlar amirining saroyini to‘ldirib olgansiz.",note:"بَلَاطٌ bu yerda «saroy, hukmdor atrofi» ma’nosida. مَا ... إِلَّا fikrni ta’kidlab, cheklashni bildiradi."},
{num:101,time:"00:09:45,280 --> 00:09:47,800",arabic:"وَاسْتَأْثَرْتُمْ بِهِ دُونَ النَّاسِ جَمِيعًا.",segs:[{ar:"وَاسْتَأْثَرْتُمْ بِهِ",uz:"uni faqat o‘zingizga ajratib olgansiz"},{ar:"دُونَ النَّاسِ جَمِيعًا",uz:"barcha boshqa odamlarni chetda qoldirib"}],full_uz:"Barcha boshqa odamlarni chetda qoldirib, uni faqat o‘zingizga ajratib olgansiz.",note:"اِسْتَأْثَرَ بِالشَّيْءِ — «bir narsani boshqalarga bermay, faqat o‘ziga oldi»."},
{num:102,time:"00:09:47,800 --> 00:09:50,180",arabic:"فَإِنْ كَانَ ذَلِكَ حَادِثًا بِي أَوْ دُونِي...",segs:[{ar:"فَإِنْ كَانَ ذَلِكَ حَادِثًا",uz:"agar bu baribir sodir bo‘ladigan bo‘lsa"},{ar:"بِي أَوْ دُونِي",uz:"men bilan yoki mensiz"}],full_uz:"Agar bu men bilan yoki mensiz baribir sodir bo‘ladigan bo‘lsa...",note:"دُونِي bu yerda «mensiz, mening ishtirokimsiz» ma’nosida."},
{num:103,time:"00:09:50,180 --> 00:09:54,400",arabic:"فَسَيْفٌ مَعَكَ لَا يُعْجِبُكَ خَيْرٌ مِنْ سَيْفٍ عَلَيْكَ.",segs:[{ar:"فَسَيْفٌ مَعَكَ",uz:"siz tomondagi qilich"},{ar:"لَا يُعْجِبُكَ",uz:"sizga yoqmasa ham"},{ar:"خَيْرٌ مِنْ سَيْفٍ عَلَيْكَ",uz:"sizga qarshi qilichdan yaxshiroq"}],full_uz:"Siz tomondagi qilich sizga yoqmasa ham, sizga qarshi qilichdan yaxshiroq.",note:"مَعَكَ — «siz bilan, siz tomonda»; عَلَيْكَ bu yerda «sizga qarshi». Qilich ko‘chma ma’noda kuch yoki tarafdorni bildiradi."},
{num:104,time:"00:09:54,400 --> 00:09:57,800",arabic:"أَنَا وَعَدْتُكَ وَسَأَفِي لَكَ بِوَعْدِي.",segs:[{ar:"أَنَا وَعَدْتُكَ",uz:"men sizga va’da berganman"},{ar:"وَسَأَفِي لَكَ بِوَعْدِي",uz:"va sizga bergan va’damni bajaraman"}],full_uz:"Men sizga va’da berganman va va’damni bajaraman.",note:"وَفَى بِوَعْدِهِ — «va’dasini bajardi». أَفِي — «men vafo qilaman»; سَأَفِي — «vafo qilaman, bajaraman»."},
{num:105,time:"00:09:57,800 --> 00:10:01,340",arabic:"وَلَنْ تَجِدَ نَفْسَكَ إِلَّا مَاثِلًا أَمَامَ أَمِيرِ الْمُؤْمِنِينَ.",segs:[{ar:"وَلَنْ تَجِدَ نَفْسَكَ إِلَّا",uz:"albatta, o‘zingizni ... holda ko‘rasiz"},{ar:"مَاثِلًا",uz:"hozir bo‘lib turgan"},{ar:"أَمَامَ أَمِيرِ الْمُؤْمِنِينَ",uz:"mo‘minlar amirining qarshisida"}],full_uz:"Albatta, o‘zingizni mo‘minlar amirining qarshisida hozir bo‘lib turgan holda ko‘rasiz.",note:"مَثَلَ أَمَامَهُ — «uning huzurida hozir bo‘ldi». مَاثِلًا hol bo‘lib, kishining qanday vaziyatda ekanini bildiradi."},
{num:106,time:"00:10:01,340 --> 00:10:04,040",arabic:"أَنَا أَعْرِفُ أَنَّكَ سَتَنَالُ إِعْجَابَهُ.",segs:[{ar:"أَنَا أَعْرِفُ",uz:"men bilaman"},{ar:"أَنَّكَ سَتَنَالُ إِعْجَابَهُ",uz:"uning e’tirofiga sazovor bo‘lishingizni"}],full_uz:"Uning e’tirofiga sazovor bo‘lishingizni bilaman.",note:"نَالَ إِعْجَابَهُ — «unga yoqdi, uning e’tirofiga sazovor bo‘ldi»."},
{num:107,time:"00:10:04,039 --> 00:10:09,240",arabic:"وَخَاصَّةً أَنَّكَ رَجُلٌ مُفَوَّهٌ، ذَكِيُّ الْقَلْبِ، لَا تَنْقُصُكَ الْفِطْنَةُ.",segs:[{ar:"وَخَاصَّةً أَنَّكَ",uz:"ayniqsa, siz"},{ar:"رَجُلٌ مُفَوَّهٌ",uz:"so‘zga usta kishisiz"},{ar:"ذَكِيُّ الْقَلْبِ",uz:"ziyrak zehnlisiz"},{ar:"لَا تَنْقُصُكَ الْفِطْنَةُ",uz:"sizga fahm-farosat yetishmaydi emas"}],full_uz:"Ayniqsa, siz so‘zga usta, ziyrak zehnli kishisiz, fahm-farosatingiz ham yetarli.",note:"مُفَوَّهٌ — «so‘zga usta, ravon va ta’sirli gapiradigan». الْفِطْنَةُ — fahm-farosat, tez anglash qobiliyati."},
{num:108,time:"00:10:09,240 --> 00:10:12,639",arabic:"شُكْرًا لَكَ عَلَى ثِقَتِكَ بِي يَا ابْنَ أَكْثَمَ.",segs:[{ar:"شُكْرًا لَكَ",uz:"sizga rahmat"},{ar:"عَلَى ثِقَتِكَ بِي",uz:"menga bo‘lgan ishonchingiz uchun"},{ar:"يَا ابْنَ أَكْثَمَ",uz:"ey Ibn Aksam"}],full_uz:"Menga bo‘lgan ishonchingiz uchun rahmat, Ibn Aksam.",note:"ثِقَةٌ بِـ — «...ga ishonch». وَثِقَ بِهِ — «unga ishondi»."},
{num:109,time:"00:10:12,639 --> 00:10:16,120",arabic:"وَلَنْ أَنْسَى لَكَ ذَلِكَ مَا حَيِيتُ.",segs:[{ar:"وَلَنْ أَنْسَى لَكَ ذَلِكَ",uz:"sizning bu yaxshiligingizni unutmayman"},{ar:"مَا حَيِيتُ",uz:"tirik ekanman"}],full_uz:"Tirik ekanman, sizning bu yaxshiligingizni unutmayman.",note:"مَا حَيِيتُ — «tirik ekanman, umrim davomida». مَا bu yerda davomiylikni bildiradi."},
{num:110,time:"00:11:34,039 --> 00:11:46,939",arabic:"وَعَنِ الْحَسَنِ بْنِ زَيْدِ بْنِ حَسَنٍ قَالَ...",segs:[{ar:"وَعَنِ الْحَسَنِ بْنِ زَيْدِ بْنِ حَسَنٍ",uz:"Hasan ibn Zayd ibn Hasandan rivoyat qilinishicha"},{ar:"قَالَ",uz:"u aytdi"}],full_uz:"Hasan ibn Zayd ibn Hasandan rivoyat qilinishicha, u aytdi...",note:"عَنْ rivoyat zanjirida xabar kimdan olinganini bildiradi."},
{num:111,time:"00:11:46,939 --> 00:11:52,419",arabic:"حَدَّثَنِي أَبِي عَنْ أَبِيهِ عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ...",segs:[{ar:"حَدَّثَنِي أَبِي",uz:"otam menga rivoyat qildi"},{ar:"عَنْ أَبِيهِ",uz:"o‘z otasidan"},{ar:"عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ",uz:"u esa Ali ibn Abu Tolibdan"},{ar:"رَضِيَ اللَّهُ عَنْهُ",uz:"Alloh undan rozi bo‘lsin"},{ar:"قَالَ",uz:"u aytdi"}],full_uz:"Otam menga o‘z otasidan, u esa Ali ibn Abu Tolibdan — Alloh undan rozi bo‘lsin — rivoyat qildi. U aytdi...",note:"حَدَّثَنِي — «menga rivoyat qildi». ـنِي to‘ldiruvchi olmosh bo‘lib, «menga» ma’nosini beradi."},
{num:112,time:"00:11:52,419 --> 00:11:56,159",arabic:"كُنْتُ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.",segs:[{ar:"كُنْتُ عِنْدَ النَّبِيِّ",uz:"Payg‘ambarning huzurlarida edim"},{ar:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",uz:"Alloh u zotga salovot va salom yo‘llasin"}],full_uz:"Payg‘ambar — Alloh u zotga salovot va salom yo‘llasin — huzurlarida edim.",note:"عِنْدَ kishiga nisbatan ishlatilganda «uning yonida, huzurida» ma’nosini beradi."},
{num:113,time:"00:11:58,480 --> 00:12:02,459",arabic:"فَأَقْبَلَ أَبُو بَكْرٍ وَعُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُمَا.",segs:[{ar:"فَأَقْبَلَ أَبُو بَكْرٍ",uz:"shunda Abu Bakr keldi"},{ar:"وَعُمَرُ بْنُ الْخَطَّابِ",uz:"va Umar ibn Xattob"},{ar:"رَضِيَ اللَّهُ عَنْهُمَا",uz:"Alloh ularning ikkalasidan rozi bo‘lsin"}],full_uz:"Shunda Abu Bakr va Umar ibn Xattob keldi. Alloh ularning ikkalasidan rozi bo‘lsin.",note:"عَنْهُمَا dagi ـهُمَا ikki kishiga ishora qiladi. أَقْبَلَ — «yaqinlashib keldi»."},
{num:114,time:"00:12:02,460 --> 00:12:08,320",arabic:"فَقَالَ: يَا عَلِيُّ، هَذَانِ سَيِّدَا كُهُولِ أَهْلِ الْجَنَّةِ وَشَبَابِهَا.",segs:[{ar:"فَقَالَ",uz:"shunda aytdilar"},{ar:"يَا عَلِيُّ",uz:"ey Ali"},{ar:"هَذَانِ سَيِّدَا",uz:"bu ikkisi ikki yetakchisidir"},{ar:"كُهُولِ أَهْلِ الْجَنَّةِ",uz:"jannat ahlining yetuk yoshli kishilarining"},{ar:"وَشَبَابِهَا",uz:"va yoshlarining"}],full_uz:"Shunda aytdilar: «Ey Ali, bu ikkisi jannat ahlining yetuk yoshli kishilari va yoshlarining ikki yetakchisidir».",note:"كُهُولٌ — كَهْلٌ («yetuk yoshli kishi»)ning ko‘pligi. سَيِّدَانِ izofaga kirganda nuni tushib, سَيِّدَا bo‘ladi."},
{num:115,time:"00:12:08,320 --> 00:12:10,800",arabic:"بَعْدَ النَّبِيِّينَ وَالْمُرْسَلِينَ.",segs:[{ar:"بَعْدَ النَّبِيِّينَ",uz:"nabiylardan keyin"},{ar:"وَالْمُرْسَلِينَ",uz:"va rasullardan"}],full_uz:"Nabiylar va rasullardan keyin.",note:"بَعْدَ bu yerda vaqtni emas, martaba tartibini bildiradi."},
{num:116,time:"00:12:10,800 --> 00:12:17,100",arabic:"لَوْ تَدْرِي كَمْ أَنَا سَعِيدٌ بِرُؤْيَتِكَ مَرَّةً أُخْرَى يَا أُسَامَةُ!",segs:[{ar:"لَوْ تَدْرِي",uz:"qaniydi bilsangiz"},{ar:"كَمْ أَنَا سَعِيدٌ",uz:"qanchalik xursand ekanimni"},{ar:"بِرُؤْيَتِكَ مَرَّةً أُخْرَى",uz:"sizni yana ko‘rganimdan"},{ar:"يَا أُسَامَةُ",uz:"ey Usoma"}],full_uz:"Sizni yana ko‘rganimdan qanchalik xursand ekanimni qaniydi bilsangiz, Usoma!",note:"لَوْ تَدْرِي bu yerda istak va kuchli hissiyotni bildiradi. كَمْ — miqdorning kattaligini ta’kidlamoqda."},
{num:117,time:"00:12:17,100 --> 00:12:20,980",arabic:"قَدْ حَسِبْتُ بَعْدَ اخْتِفَائِكَ أَنَّكَ فِي سِجْنِ هَارُونَ.",segs:[{ar:"قَدْ حَسِبْتُ",uz:"o‘ylagan edim"},{ar:"بَعْدَ اخْتِفَائِكَ",uz:"g‘oyib bo‘lganingizdan keyin"},{ar:"أَنَّكَ فِي سِجْنِ هَارُونَ",uz:"sizni Horunning zindonida deb"}],full_uz:"G‘oyib bo‘lganingizdan keyin sizni Horunning zindonida deb o‘ylagan edim.",note:"حَسِبَ bu yerda «deb o‘yladi». اِخْتِفَاءٌ — اِخْتَفَى («g‘oyib bo‘ldi, yashirindi») fe’lining masdari."},
{num:118,time:"00:12:20,980 --> 00:12:25,060",arabic:"أَوْ بَيْنَ الشُّهَدَاءِ مِنْ إِخْوَتِنَا عَلَى يَدَيْ هَذَا الظَّالِمِ.",segs:[{ar:"أَوْ بَيْنَ الشُّهَدَاءِ مِنْ إِخْوَتِنَا",uz:"yoki shahid bo‘lgan birodarlarimiz orasida"},{ar:"عَلَى يَدَيْ هَذَا الظَّالِمِ",uz:"bu zolimning qo‘lida"}],full_uz:"Yoki bu zolimning qo‘lida shahid bo‘lgan birodarlarimiz orasida deb o‘ylagan edim.",note:"عَلَى يَدَيْ — «...ning qo‘li bilan, ...tomonidan». يَدَيْ — يَدٌ so‘zining izofadagi ikkilik shakli."},
{num:119,time:"00:12:25,060 --> 00:12:31,019",arabic:"كَانَ لَوْ حَدَثَ ذَلِكَ أَسْهَلَ بِكَثِيرٍ مِمَّا جَرَى لِي يَا أَبَا عَبْدِ الرَّحْمَٰنِ.",segs:[{ar:"كَانَ لَوْ حَدَثَ ذَلِكَ",uz:"agar shunday bo‘lganida, bu bo‘lardi"},{ar:"أَسْهَلَ بِكَثِيرٍ",uz:"ancha yengilroq"},{ar:"مِمَّا جَرَى لِي",uz:"boshimdan kechirganimdan"},{ar:"يَا أَبَا عَبْدِ الرَّحْمَٰنِ",uz:"ey Abu Abdurahmon"}],full_uz:"Agar shunday bo‘lganida, bu boshimdan kechirganimdan ancha yengilroq bo‘lardi, Abu Abdurahmon.",note:"أَسْهَلُ بِكَثِيرٍ — «ancha yengilroq». جَرَى لَهُ — «uning boshidan kechdi, u bilan sodir bo‘ldi»."},
{num:120,time:"00:12:31,019 --> 00:12:32,439",arabic:"أَسْهَلُ بِكَثِيرٍ.",segs:null,full_uz:"Ancha yengilroq.",note:null},
{num:121,time:"00:12:32,439 --> 00:12:36,220",arabic:"لَقَدْ قَضَيْتُ السِّنِينَ الْمَاضِيَةَ مُشَرَّدًا فِي الْبِلَادِ.",segs:[{ar:"لَقَدْ قَضَيْتُ السِّنِينَ الْمَاضِيَةَ",uz:"o‘tgan yillarni o‘tkazdim"},{ar:"مُشَرَّدًا",uz:"darbadar holda"},{ar:"فِي الْبِلَادِ",uz:"turli yurtlarda"}],full_uz:"O‘tgan yillarni turli yurtlarda darbadar holda o‘tkazdim.",note:"قَضَى وَقْتًا — «vaqt o‘tkazdi». مُشَرَّدًا hol bo‘lib, vaqtni qanday ahvolda o‘tkazganini bildiradi."},
{num:122,time:"00:12:36,220 --> 00:12:39,519",arabic:"بَعْدَ أَنْ أَلْقَى جُنْدُ هَارُونَ الْقَبْضَ عَلَى إِخْوَتِنَا.",segs:[{ar:"بَعْدَ أَنْ أَلْقَى جُنْدُ هَارُونَ",uz:"Horunning askarlari ...ganidan keyin"},{ar:"الْقَبْضَ عَلَى إِخْوَتِنَا",uz:"birodarlarimizni qo‘lga olgan"}],full_uz:"Horunning askarlari birodarlarimizni qo‘lga olganidan keyin.",note:"أَلْقَى الْقَبْضَ عَلَى — «qo‘lga oldi, hibsga oldi». Bu birikma yaxlit ma’noda o‘rganiladi."},
{num:123,time:"00:12:39,519 --> 00:12:41,259",arabic:"وَحَاوَلُوا الْقَبْضَ عَلَيَّ.",segs:[{ar:"وَحَاوَلُوا",uz:"va urinishdi"},{ar:"الْقَبْضَ عَلَيَّ",uz:"meni qo‘lga olishga"}],full_uz:"Va meni qo‘lga olishga urinishdi.",note:"عَلَيَّ — عَلَى + ي: «mening ustimga, menga». الْقَبْضُ عَلَيَّ — «meni qo‘lga olish»."},
{num:124,time:"00:12:41,259 --> 00:12:44,519",arabic:"الْحَمْدُ لِلَّهِ، خَلَّصَكَ اللَّهُ مِنْ بَرَاثِنِهِمْ.",segs:[{ar:"الْحَمْدُ لِلَّهِ",uz:"Allohga hamd bo‘lsin"},{ar:"خَلَّصَكَ اللَّهُ",uz:"Alloh sizni qutqardi"},{ar:"مِنْ بَرَاثِنِهِمْ",uz:"ularning changalidan"}],full_uz:"Allohga hamd bo‘lsin, Alloh sizni ularning changalidan qutqardi.",note:"بَرَاثِنُ — بُرْثُنٌ («yirtqichning panjasi»)ning ko‘pligi. مِنْ بَرَاثِنِهِمْ — ko‘chma ma’noda «ularning changalidan»."},
{num:125,time:"00:12:44,519 --> 00:12:48,120",arabic:"وَأَيْنَ كُنْتَ طِيلَةَ هَذِهِ الْفَتْرَةِ؟",segs:[{ar:"وَأَيْنَ كُنْتَ",uz:"qayerda edingiz"},{ar:"طِيلَةَ هَذِهِ الْفَتْرَةِ",uz:"shu vaqt davomida"}],full_uz:"Shu vaqt davomida qayerda edingiz?",note:"طِيلَةَ — «butun ...davomida». Vaqt davomiyligini bildiradi."},
{num:126,time:"00:12:48,120 --> 00:12:51,319",arabic:"فِي أَرْضِ اللَّهِ الْوَاسِعَةِ.",segs:null,full_uz:"Allohning keng yerida.",note:"الْوَاسِعَةِ sifati أَرْضِ so‘ziga tegishli. أَرْضٌ arab tilida muannas ot hisoblanadi."},
{num:127,time:"00:12:51,319 --> 00:12:54,079",arabic:"أَلَمْ يَقُلْ سُبْحَانَهُ وَتَعَالَى...",segs:[{ar:"أَلَمْ يَقُلْ",uz:"aytmaganmi"},{ar:"سُبْحَانَهُ وَتَعَالَى",uz:"U pok va yuksakdir"}],full_uz:"U — pok va yuksak Zot — aytmaganmi...",note:"يَقُولُ fe’li لَمْ dan keyin يَقُلْ bo‘ladi. أَلَمْ يَقُلْ؟ — «aytmaganmi?»."},
{num:128,time:"00:12:54,079 --> 00:12:56,579",arabic:"يَا عِبَادِيَ الَّذِينَ آمَنُوا.",segs:[{ar:"يَا عِبَادِيَ",uz:"ey Mening bandalarim"},{ar:"الَّذِينَ آمَنُوا",uz:"imon keltirgan"}],full_uz:"Ey imon keltirgan bandalarim!",note:"عِبَادِيَ — «Mening bandalarim». الَّذِينَ آمَنُوا birikmasi qaysi bandalar nazarda tutilganini aniqlaydi."},
{num:129,time:"00:12:56,579 --> 00:12:59,740",arabic:"إِنَّ أَرْضِي وَاسِعَةٌ فَإِيَّايَ فَاعْبُدُونِ.",segs:[{ar:"إِنَّ أَرْضِي وَاسِعَةٌ",uz:"albatta, Mening yerim kengdir"},{ar:"فَإِيَّايَ",uz:"bas, faqat Mengagina"},{ar:"فَاعْبُدُونِ",uz:"ibodat qiling"}],full_uz:"Albatta, Mening yerim kengdir. Bas, faqat Mengagina ibodat qiling.",note:"إِيَّايَ to‘ldiruvchisi oldinga chiqarilib, ibodatning faqat Allohga qaratilishini ta’kidlaydi."},
{num:130,time:"00:12:59,740 --> 00:13:03,700",arabic:"لَقَدْ خَرَجْتُ مِنْ هَذَا الْبَلَدِ الظَّالِمِ أَهْلُهُ.",segs:[{ar:"لَقَدْ خَرَجْتُ",uz:"men chiqib ketdim"},{ar:"مِنْ هَذَا الْبَلَدِ",uz:"bu yurtdan"},{ar:"الظَّالِمِ أَهْلُهُ",uz:"aholisi zolim bo‘lgan"}],full_uz:"Men aholisi zolim bo‘lgan bu yurtdan chiqib ketdim.",note:"الظَّالِمِ أَهْلُهُ — sababiy sifat: zolimlik yurtning o‘ziga emas, uning aholisiga tegishli. أَهْلُهُ marfu’ keladi."},
{num:131,time:"00:13:03,700 --> 00:13:08,120",arabic:"فَمَا الَّذِي مَنَعَكَ مِنَ الْعَوْدَةِ إِلَى بَغْدَادَ بَعْدَ أَنْ قُتِلَ الْأَمِينُ؟",segs:[{ar:"فَمَا الَّذِي مَنَعَكَ",uz:"sizga nima to‘sqinlik qildi"},{ar:"مِنَ الْعَوْدَةِ إِلَى بَغْدَادَ",uz:"Bag‘dodga qaytishingizga"},{ar:"بَعْدَ أَنْ قُتِلَ الْأَمِينُ",uz:"Amin o‘ldirilganidan keyin"}],full_uz:"Amin o‘ldirilganidan keyin Bag‘dodga qaytishingizga nima to‘sqinlik qildi?",note:"مَنَعَهُ مِنْ — «uni ...dan to‘sdi». قُتِلَ — majhul nisbat: «o‘ldirildi»."},
{num:132,time:"00:13:08,120 --> 00:13:12,460",arabic:"وَاسْتَتَبَّ الْأَمْرُ لِأَمِيرِ الْمُؤْمِنِينَ الْمَأْمُونِ حَفِظَهُ اللَّهُ.",segs:[{ar:"وَاسْتَتَبَّ الْأَمْرُ",uz:"va hokimiyat mustahkamlangach"},{ar:"لِأَمِيرِ الْمُؤْمِنِينَ الْمَأْمُونِ",uz:"mo‘minlar amiri Ma’mun uchun"},{ar:"حَفِظَهُ اللَّهُ",uz:"Alloh uni asrasin"}],full_uz:"Va mo‘minlar amiri Ma’munning — Alloh uni asrasin — hokimiyati mustahkamlangach.",note:"اِسْتَتَبَّ الْأَمْرُ لَهُ — «uning hokimiyati qaror topdi, ishlari barqarorlashdi»."},
{num:133,time:"00:13:12,460 --> 00:13:18,039",arabic:"الْحَقُّ يَا شَيْخِي أَنِّي حَسِبْتُ أَنَّ الْمَأْمُونَ سَيَسِيرُ عَلَى خُطَى أَبِيهِ وَأَخِيهِ.",segs:[{ar:"الْحَقُّ يَا شَيْخِي",uz:"rostini aytsam, ustozim"},{ar:"أَنِّي حَسِبْتُ",uz:"men o‘ylagan edim"},{ar:"أَنَّ الْمَأْمُونَ سَيَسِيرُ",uz:"Ma’mun yuradi deb"},{ar:"عَلَى خُطَى أَبِيهِ وَأَخِيهِ",uz:"otasi va birodarining izidan"}],full_uz:"Rostini aytsam, ustozim, Ma’mun otasi va birodarining izidan yuradi deb o‘ylagan edim.",note:"سَارَ عَلَى خُطَى فُلَانٍ — «falonchining izidan bordi, yo‘lini davom ettirdi»."},
{num:134,time:"00:13:18,039 --> 00:13:25,100",arabic:"وَلَقَدْ زَادَتِ الظُّنُونُ عِنْدَمَا سَمِعْتُ أَنَّهُ لَزِمَ مَرْوَ فِي خُرَاسَانَ وَلَمْ يَقْدَمْ إِلَيْهَا.",segs:[{ar:"وَلَقَدْ زَادَتِ الظُّنُونُ",uz:"gumonlar yanada kuchaydi"},{ar:"عِنْدَمَا سَمِعْتُ",uz:"eshitganimda"},{ar:"أَنَّهُ لَزِمَ مَرْوَ",uz:"uning Marvda qolganini"},{ar:"فِي خُرَاسَانَ",uz:"Xurosondagi"},{ar:"وَلَمْ يَقْدَمْ إِلَيْهَا",uz:"va u yerga kelmaganini"}],full_uz:"Uning Xurosondagi Marvda qolib, Bag‘dodga kelmaganini eshitganimda gumonlar yanada kuchaydi.",note:"لَزِمَ الْمَكَانَ — «bir joyda qolib ketdi, undan ketmadi». إِلَيْهَا bu yerda Bag‘dodga ishora qiladi."},
{num:135,time:"00:13:25,100 --> 00:13:27,480",arabic:"غَفَرَ اللَّهُ لَكَ يَا أُسَامَةُ.",segs:[{ar:"غَفَرَ اللَّهُ لَكَ",uz:"Alloh sizni kechirsin"},{ar:"يَا أُسَامَةُ",uz:"ey Usoma"}],full_uz:"Alloh sizni kechirsin, Usoma.",note:null},
{num:136,time:"00:13:27,480 --> 00:13:30,379",arabic:"أَلَمْ تَكُنْ تَدْرِي أَنَّ أَمِيرَ الْمُؤْمِنِينَ الْمَأْمُونَ...",segs:[{ar:"أَلَمْ تَكُنْ تَدْرِي",uz:"bilmasmidingiz"},{ar:"أَنَّ أَمِيرَ الْمُؤْمِنِينَ الْمَأْمُونَ",uz:"mo‘minlar amiri Ma’munning ...ekanini"}],full_uz:"Mo‘minlar amiri Ma’munning ...ekanini bilmasmidingiz?",note:"لَمْ تَكُنْ تَدْرِي — «bilmas edingiz». كَانَ bilan muzori’ fe’l o‘tmishdagi holatni bildiradi."},
{num:137,time:"00:13:30,379 --> 00:13:33,740",arabic:"رَجُلٌ لَا يَنْخَدِعُ بِفَتَاوَى الْفُقَهَاءِ.",segs:[{ar:"رَجُلٌ لَا يَنْخَدِعُ",uz:"aldanmaydigan kishi"},{ar:"بِفَتَاوَى الْفُقَهَاءِ",uz:"faqihlarning fatvolariga"}],full_uz:"Faqihlarning fatvolariga aldanmaydigan kishi ekanini.",note:"اِنْخَدَعَ بِـ — «...ga aldandi». فَتَاوَى — فَتْوَى so‘zining ko‘pligi."},
{num:138,time:"00:13:33,740 --> 00:13:35,379",arabic:"وَلَا هَذَيَانِ أَهْلِ الْحَدِيثِ.",segs:[{ar:"وَلَا هَذَيَانِ",uz:"va alahsirashlariga ham"},{ar:"أَهْلِ الْحَدِيثِ",uz:"hadis ahlining"}],full_uz:"Va hadis ahlining alahsirashlariga ham aldanmaydigan kishi ekanini.",note:"هَذَيَانٌ — «alahsirash, bema’ni gapirish». Bu yerda so‘zlovchi boshqalarning gapini kamsitib atamoqda."},
{num:139,time:"00:13:35,379 --> 00:13:37,159",arabic:"الْحَقُّ أَنِّي لَمْ أَعْرِفْ ذَلِكَ...",segs:[{ar:"الْحَقُّ أَنِّي",uz:"rostini aytsam, men"},{ar:"لَمْ أَعْرِفْ ذَلِكَ",uz:"buni bilmagan edim"}],full_uz:"Rostini aytsam, men buni bilmagan edim...",note:null},
{num:140,time:"00:13:37,159 --> 00:13:39,779",arabic:"إِلَّا بَعْدَ عَوْدَتِي هَذِهِ السَّنَةَ إِلَى بَغْدَادَ.",segs:[{ar:"إِلَّا بَعْدَ عَوْدَتِي",uz:"faqat qaytganimdan keyin"},{ar:"هَذِهِ السَّنَةَ",uz:"bu yil"},{ar:"إِلَى بَغْدَادَ",uz:"Bag‘dodga"}],full_uz:"Faqat bu yil Bag‘dodga qaytganimdan keyin bildim.",note:"Oldingi banddagi inkor bilan birga لَمْ ... إِلَّا tuzilishi hosil bo‘ladi: «faqat ...dan keyingina bildim»."},
{num:141,time:"00:13:39,779 --> 00:13:42,600",arabic:"وَسَمَاحِهِ لِإِخْوَتِنَا بِالْجَهْرِ بِعَقِيدَتِنَا.",segs:[{ar:"وَسَمَاحِهِ لِإِخْوَتِنَا",uz:"va uning birodarlarimizga ruxsat berganini"},{ar:"بِالْجَهْرِ بِعَقِيدَتِنَا",uz:"e’tiqodimizni oshkora aytishga"}],full_uz:"Va uning birodarlarimizga e’tiqodimizni oshkora aytishga ruxsat berganini.",note:"سَمَاحٌ — «ruxsat berish». الْجَهْرُ بِـ — «bir narsani ovoz chiqarib yoki oshkora aytish»."},
{num:142,time:"00:13:42,600 --> 00:13:45,980",arabic:"فَأَرْسَلَ إِلَيَّ أَحَدُ الْإِخْوَةِ أَنْ أَقْدَمَ بَغْدَادَ.",segs:[{ar:"فَأَرْسَلَ إِلَيَّ",uz:"shunda menga xabar yubordi"},{ar:"أَحَدُ الْإِخْوَةِ",uz:"birodarlardan biri"},{ar:"أَنْ أَقْدَمَ بَغْدَادَ",uz:"Bag‘dodga kelishimni aytib"}],full_uz:"Shunda birodarlardan biri menga Bag‘dodga kelishimni aytib xabar yubordi.",note:"قَدِمَ — يَقْدَمُ — «keldi, yetib keldi». إِلَيَّ — «menga»."},
{num:143,time:"00:13:45,980 --> 00:13:48,759",arabic:"فَإِنَّ الْأُمُورَ فِيهَا عَلَى مَا نُحِبُّ.",segs:[{ar:"فَإِنَّ الْأُمُورَ فِيهَا",uz:"chunki u yerdagi ishlar"},{ar:"عَلَى مَا نُحِبُّ",uz:"biz istagandek"}],full_uz:"Chunki u yerdagi ishlar biz istagandek.",note:"عَلَى مَا نُحِبُّ — «biz yoqtirgan, istagan tarzda»."},
{num:144,time:"00:13:48,759 --> 00:13:52,420",arabic:"وَالْحَمْدُ لِلَّهِ أَنَّنِي رَأَيْتُهَا كَمَا نَشْتَهِي.",segs:[{ar:"وَالْحَمْدُ لِلَّهِ",uz:"Allohga hamd bo‘lsin"},{ar:"أَنَّنِي رَأَيْتُهَا",uz:"men uni ko‘rdim"},{ar:"كَمَا نَشْتَهِي",uz:"biz istagandek"}],full_uz:"Allohga hamd bo‘lsin, men uni biz istagandek ko‘rdim.",note:"اِشْتَهَى — «istadi, xohladi». نَشْتَهِي — «biz istaymiz»."},
{num:145,time:"00:13:52,420 --> 00:13:54,180",arabic:"وَأَوَّلُ شَيْءٍ فَعَلْتُهُ...",segs:[{ar:"وَأَوَّلُ شَيْءٍ",uz:"va birinchi ish"},{ar:"فَعَلْتُهُ",uz:"men qilgan"}],full_uz:"Va qilgan birinchi ishim...",note:"فَعَلْتُهُ fe’lli gapi شَيْءٍ so‘zini sifatlaydi: «men qilgan narsa»."},
{num:146,time:"00:13:54,179 --> 00:13:55,859",arabic:"الْبَحْثُ عَنْكَ.",segs:null,full_uz:"Sizni izlash bo‘ldi.",note:"بَحَثَ عَنْ — «...ni izladi». الْبَحْثُ عَنْكَ — «sizni izlash»."},
{num:147,time:"00:13:56,919 --> 00:14:00,139",arabic:"الْحَمْدُ لِلَّهِ أَنْ جَمَعَنَا مَرَّةً أُخْرَى يَا أُسَامَةُ.",segs:[{ar:"الْحَمْدُ لِلَّهِ",uz:"Allohga hamd bo‘lsin"},{ar:"أَنْ جَمَعَنَا مَرَّةً أُخْرَى",uz:"bizni yana birlashtirgani uchun"},{ar:"يَا أُسَامَةُ",uz:"ey Usoma"}],full_uz:"Bizni yana birlashtirgani uchun Allohga hamd bo‘lsin, Usoma.",note:"جَمَعَنَا — «bizni birlashtirdi, uchrashtirdi». ـنَا bu yerda to‘ldiruvchi olmosh."},
{num:148,time:"00:14:00,139 --> 00:14:03,479",arabic:"بَغْدَادُ لَمْ تَعُدْ بَلَدًا ظَالِمًا أَهْلُهُ.",segs:[{ar:"بَغْدَادُ لَمْ تَعُدْ",uz:"Bag‘dod endi ...emas"},{ar:"بَلَدًا ظَالِمًا أَهْلُهُ",uz:"aholisi zolim bo‘lgan yurt"}],full_uz:"Bag‘dod endi aholisi zolim bo‘lgan yurt emas.",note:"لَمْ تَعُدْ — «endi ...emas». ظَالِمًا أَهْلُهُ da sifat yurt aholisining holatini ifodalaydi."},
{num:149,time:"00:14:03,479 --> 00:14:06,639",arabic:"بَغْدَادُ عَادَتْ إِلَيْهَا أَنْوَارُ الْيَقِينِ.",segs:[{ar:"بَغْدَادُ عَادَتْ إِلَيْهَا",uz:"Bag‘dodga qaytib keldi"},{ar:"أَنْوَارُ الْيَقِينِ",uz:"qat’iy ishonch nurlari"}],full_uz:"Bag‘dodga qat’iy ishonch nurlari qaytib keldi.",note:"الْيَقِينُ — shubhasiz, qat’iy ishonch. أَنْوَارٌ — نُورٌ so‘zining ko‘pligi."},
{num:150,time:"00:14:06,639 --> 00:14:09,639",arabic:"وَهَا هُمْ إِخْوَتُكَ يَصْدَحُونَ فِي جَنَبَاتِهَا.",segs:[{ar:"وَهَا هُمْ إِخْوَتُكَ",uz:"mana, birodarlaringiz"},{ar:"يَصْدَحُونَ",uz:"ovozlarini baralla yangratishmoqda"},{ar:"فِي جَنَبَاتِهَا",uz:"uning turli tomonlarida"}],full_uz:"Mana, birodarlaringiz uning turli tomonlarida ovozlarini baralla yangratishmoqda.",note:"صَدَحَ — «ovozini baralla yangratdi». جَنَبَاتٌ — «tomonlar, tevarak-atrof»."},
{num:151,time:"00:14:09,639 --> 00:14:12,959",arabic:"دُونَ أَنْ يَجْرُؤَ أَحَدٌ عَلَى التَّعَرُّضِ لَهُمْ.",segs:[{ar:"دُونَ أَنْ يَجْرُؤَ أَحَدٌ",uz:"hech kim jur’at qilolmagan holda"},{ar:"عَلَى التَّعَرُّضِ لَهُمْ",uz:"ularga tegishga"}],full_uz:"Hech kim ularga tegishga jur’at qilolmagan holda.",note:"جَرُؤَ عَلَى — «...ga jur’at qildi». تَعَرَّضَ لَهُ bu yerda «unga tegdi, qarshilik ko‘rsatdi» ma’nosida."},
{num:152,time:"00:14:12,959 --> 00:14:15,819",arabic:"الْحَمْدُ لِلَّهِ الَّذِي مَنَّ عَلَيْنَا بِذَلِكَ.",segs:[{ar:"الْحَمْدُ لِلَّهِ",uz:"Allohga hamd bo‘lsin"},{ar:"الَّذِي مَنَّ عَلَيْنَا بِذَلِكَ",uz:"bizga buni in’om etgan"}],full_uz:"Bizga buni in’om etgan Allohga hamd bo‘lsin.",note:"مَنَّ عَلَى فُلَانٍ بِشَيْءٍ — «falonchiga bir narsani in’om qildi»."},
{num:153,time:"00:14:18,519 --> 00:14:24,579",arabic:"السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ.",segs:[{ar:"السَّلَامُ عَلَيْكُمْ",uz:"sizlarga salom bo‘lsin"},{ar:"وَرَحْمَةُ اللَّهِ",uz:"va Allohning rahmati"}],full_uz:"Sizlarga salom va Allohning rahmati bo‘lsin.",note:null},
{num:154,time:"00:14:24,579 --> 00:14:26,279",arabic:"أَيْنَ كُنْتَ يَا مُحَمَّدُ؟",segs:[{ar:"أَيْنَ كُنْتَ",uz:"qayerda edingiz"},{ar:"يَا مُحَمَّدُ",uz:"ey Muhammad"}],full_uz:"Qayerda edingiz, Muhammad?",note:null},
{num:155,time:"00:14:26,279 --> 00:14:27,579",arabic:"كَانَ هُنَاكَ مَا يَشْغَلُنِي.",segs:[{ar:"كَانَ هُنَاكَ",uz:"bor edi"},{ar:"مَا يَشْغَلُنِي",uz:"meni band qiladigan ish"}],full_uz:"Meni band qiladigan ish bor edi.",note:"كَانَ هُنَاكَ — «bor edi». مَا bu yerda «...adigan narsa» ma’nosida."},
{num:156,time:"00:14:27,579 --> 00:14:30,419",arabic:"هَيَّا بِنَا.",segs:null,full_uz:"Qani, ketdik.",note:"هَيَّا بِنَا — birga harakat qilishga undovchi ibora: «qani, ketdik»."},
{num:157,time:"00:14:30,419 --> 00:14:34,220",arabic:"كُلُّ الْأَدِلَّةِ تَقْطَعُ بِأَنَّ الْقُرْآنَ مَخْلُوقٌ.",segs:[{ar:"كُلُّ الْأَدِلَّةِ",uz:"barcha dalillar"},{ar:"تَقْطَعُ بِأَنَّ",uz:"qat’iy ko‘rsatadi"},{ar:"الْقُرْآنَ مَخْلُوقٌ",uz:"Qur’on yaratilgan ekanini"}],full_uz:"Barcha dalillar Qur’on yaratilgan ekanini qat’iy ko‘rsatadi.",note:"قَطَعَ بِأَنَّ — «...ekanini qat’iy tasdiqladi». مَخْلُوقٌ — خَلَقَ fe’lining ismi maf’uli: «yaratilgan»."},
{num:158,time:"00:14:34,220 --> 00:14:40,519",arabic:"وَكُلُّ الْأَدِلَّةِ تَقْطَعُ بِاسْتِحَالَةِ رُؤْيَةِ اللَّهِ يَوْمَ الْقِيَامَةِ.",segs:[{ar:"وَكُلُّ الْأَدِلَّةِ تَقْطَعُ",uz:"va barcha dalillar qat’iy ko‘rsatadi"},{ar:"بِاسْتِحَالَةِ رُؤْيَةِ اللَّهِ",uz:"Allohni ko‘rishning imkonsizligini"},{ar:"يَوْمَ الْقِيَامَةِ",uz:"qiyomat kuni"}],full_uz:"Va barcha dalillar qiyomat kuni Allohni ko‘rishning imkonsizligini qat’iy ko‘rsatadi.",note:"اِسْتِحَالَةٌ — «imkonsizlik». رُؤْيَةُ اللَّهِ izofasida اللَّهِ ko‘rish harakati qaratilgan zotni bildiradi."},
{num:159,time:"00:14:40,519 --> 00:14:43,259",arabic:"وَمَنْ يَقُولُ غَيْرَ ذَلِكَ فَهُوَ كَافِرٌ.",segs:[{ar:"وَمَنْ يَقُولُ غَيْرَ ذَلِكَ",uz:"kim bundan boshqacha gapirsa"},{ar:"فَهُوَ كَافِرٌ",uz:"u kofirdir"}],full_uz:"Kim bundan boshqacha gapirsa, u kofirdir.",note:"مَنْ bu tuzilishda umumiy ma’noni bildiradi: «kimki ...». فَـ undan keyingi hukmni bog‘laydi."},
{num:160,time:"00:14:43,259 --> 00:14:45,779",arabic:"كَافِرٌ كُفْرَ اعْتِقَادٍ.",segs:[{ar:"كَافِرٌ",uz:"kofir"},{ar:"كُفْرَ اعْتِقَادٍ",uz:"e’tiqod jihatidan kufr bilan"}],full_uz:"E’tiqod jihatidan kofir.",note:"كُفْرَ اعْتِقَادٍ birikmasi so‘zlovchi nazarda tutayotgan kufrning turini aniqlaydi."},
{num:161,time:"00:14:45,779 --> 00:14:48,460",arabic:"أَسَمِعْتَ يَا أَبَا عَبْدِ اللَّهِ؟",segs:[{ar:"أَسَمِعْتَ",uz:"eshitdingizmi"},{ar:"يَا أَبَا عَبْدِ اللَّهِ",uz:"ey Abu Abdulloh"}],full_uz:"Eshitdingizmi, Abu Abdulloh?",note:"أَسَمِعْتَ — so‘roq hamzasi أَ va سَمِعْتَ («eshitdingiz») birikmasi."},
{num:162,time:"00:14:48,460 --> 00:14:51,040",arabic:"كَبُرَتْ كَلِمَةً تَخْرُجُ مِنْ أَفْوَاهِهِمْ.",segs:[{ar:"كَبُرَتْ كَلِمَةً",uz:"naqadar og‘ir so‘z"},{ar:"تَخْرُجُ مِنْ أَفْوَاهِهِمْ",uz:"ularning og‘izlaridan chiqayotgan"}],full_uz:"Ularning og‘izlaridan chiqayotgan so‘z naqadar og‘ir!",note:"كَلِمَةً mansub tamyiz bo‘lib, qoralash va taajjubning nimaga qaratilganini aniqlaydi. أَفْوَاهٌ — فَمٌ so‘zining ko‘pligi."},
{num:163,time:"00:14:51,040 --> 00:14:54,300",arabic:"هَؤُلَاءِ قَوْمٌ يَقُولُونَ عَلَى اللَّهِ مَا لَا يَعْلَمُونَ.",segs:[{ar:"هَؤُلَاءِ قَوْمٌ",uz:"bular shunday qavmki"},{ar:"يَقُولُونَ عَلَى اللَّهِ",uz:"Alloh haqida gapiradilar"},{ar:"مَا لَا يَعْلَمُونَ",uz:"o‘zlari bilmagan narsalarni"}],full_uz:"Bular Alloh haqida o‘zlari bilmagan narsalarni gapiradigan qavmdir.",note:"قَالَ عَلَى اللَّهِ — «Allohga nisbat berib gapirdi». مَا لَا يَعْلَمُونَ — «ular bilmaydigan narsalar»."},
{num:164,time:"00:14:54,300 --> 00:14:58,120",arabic:"إِنْ كَانَ الْمَأْمُونُ يَدِينُ بِمَا نَدِينُ بِهِ...",segs:[{ar:"إِنْ كَانَ الْمَأْمُونُ يَدِينُ",uz:"agar Ma’mun e’tiqod qilsa"},{ar:"بِمَا نَدِينُ بِهِ",uz:"biz e’tiqod qiladigan narsaga"}],full_uz:"Agar Ma’mun biz e’tiqod qiladigan narsaga e’tiqod qilsa...",note:"إِنْ shart yuklamasi. يَدِينُ — «u e’tiqod qiladi»; نَدِينُ — «biz e’tiqod qilamiz»."},
{num:165,time:"00:14:58,120 --> 00:15:02,019",arabic:"فَيَجْدُرُ بِهِ أَنْ يَمْنَعَ عُلَمَاءَ الْعَوَامِّ...",segs:[{ar:"فَيَجْدُرُ بِهِ",uz:"unda u ...ishi lozim"},{ar:"أَنْ يَمْنَعَ",uz:"to‘xtatishi"},{ar:"عُلَمَاءَ الْعَوَامِّ",uz:"oddiy xalq olimlarini"}],full_uz:"Unda u oddiy xalq olimlarini to‘xtatishi lozim...",note:"يَجْدُرُ بِهِ أَنْ — «u ...ishi lozim, unga ...ish munosib». الْعَوَامُّ — keng xalq ommasi."},
{num:166,time:"00:15:02,019 --> 00:15:06,460",arabic:"الَّذِينَ يُسَمُّونَ أَنْفُسَهُمْ ظُلْمًا بِأَهْلِ السُّنَّةِ وَالْجَمَاعَةِ.",segs:[{ar:"الَّذِينَ يُسَمُّونَ أَنْفُسَهُمْ",uz:"o‘zlarini ataydiganlar"},{ar:"ظُلْمًا",uz:"nohaq ravishda"},{ar:"بِأَهْلِ السُّنَّةِ وَالْجَمَاعَةِ",uz:"Ahli sunna val jamoa deb"}],full_uz:"O‘zlarini nohaq ravishda Ahli sunna val jamoa deb ataydiganlarni.",note:"أَنْفُسَهُمْ — «o‘zlarini». ظُلْمًا bu yerda harakatning qanday tarzda bajarilayotganini bildiradi."},
{num:167,time:"00:15:07,500 --> 00:15:09,320",arabic:"أَنْ يَمْنَعَهُمْ مِنْ إِفْسَادِ الْعُقُولِ.",segs:[{ar:"أَنْ يَمْنَعَهُمْ",uz:"ularni to‘xtatishi"},{ar:"مِنْ إِفْسَادِ الْعُقُولِ",uz:"aqllarni buzishdan"}],full_uz:"Ularni aqllarni buzishdan to‘xtatishi lozim.",note:"أَفْسَدَ — «buzdi»; إِفْسَادٌ — «buzish». مَنَعَ مِنْ — «...dan to‘sdi»."},
{num:168,time:"00:15:09,320 --> 00:15:11,580",arabic:"يَجِبُ أَنْ يُحَاصِرَهُمْ.",segs:[{ar:"يَجِبُ",uz:"kerak"},{ar:"أَنْ يُحَاصِرَهُمْ",uz:"ularni qurshovga olishi"}],full_uz:"Ularni qurshovga olishi kerak.",note:"حَاصَرَ — «qamal qildi, qurshovga oldi». Bu yerda ularning faoliyatini cheklash nazarda tutilgan."},
{num:169,time:"00:15:11,580 --> 00:15:15,100",arabic:"وَيَمْنَعَهُمْ مِنْ بَثِّ السُّمُومِ بَيْنَ النَّاسِ.",segs:[{ar:"وَيَمْنَعَهُمْ",uz:"va ularni to‘xtatishi"},{ar:"مِنْ بَثِّ السُّمُومِ",uz:"zaharlarni tarqatishdan"},{ar:"بَيْنَ النَّاسِ",uz:"odamlar orasida"}],full_uz:"Va ularni odamlar orasida zahar tarqatishdan to‘xtatishi kerak.",note:"بَثَّ — «yoydi, tarqatdi». السُّمُومُ bu nutqda zararli deb hisoblangan fikrlarga ko‘chma ma’noda ishlatilgan."},
{num:170,time:"00:15:15,100 --> 00:15:19,100",arabic:"أَنْتَ تَتَعَجَّلُ الْأُمُورَ يَا ابْنَ أَبِي دُؤَادٍ.",segs:[{ar:"أَنْتَ تَتَعَجَّلُ الْأُمُورَ",uz:"siz ishlarda shoshilyapsiz"},{ar:"يَا ابْنَ أَبِي دُؤَادٍ",uz:"ey Ibn Abu Duod"}],full_uz:"Siz ishlarda shoshilyapsiz, Ibn Abu Duod.",note:"تَعَجَّلَ الْأَمْرَ — «ishda shoshildi, uning tezroq bo‘lishini istadi»."},
{num:171,time:"00:15:19,100 --> 00:15:22,240",arabic:"إِنَّ الْأَمْرَ لَيْسَ بِهَذِهِ السُّهُولَةِ.",segs:[{ar:"إِنَّ الْأَمْرَ",uz:"bu ish"},{ar:"لَيْسَ بِهَذِهِ السُّهُولَةِ",uz:"bunchalik oson emas"}],full_uz:"Bu ish bunchalik oson emas.",note:"بِهَذِهِ السُّهُولَةِ — «bunchalik osonlik bilan, bu darajada oson»."},
{num:172,time:"00:15:22,240 --> 00:15:25,659",arabic:"وَلَا تَحْسَبْ أَنَّنِي غَافِلٌ عَنْ أَفْعَالِهِمْ.",segs:[{ar:"وَلَا تَحْسَبْ",uz:"o‘ylamang"},{ar:"أَنَّنِي غَافِلٌ",uz:"meni bexabar deb"},{ar:"عَنْ أَفْعَالِهِمْ",uz:"ularning ishlaridan"}],full_uz:"Meni ularning ishlaridan bexabar deb o‘ylamang.",note:"غَافِلٌ عَنْ — «...dan g‘ofil, bexabar». لَا تَحْسَبْ taqiq shakli: «o‘ylamang»."},
{num:173,time:"00:15:25,659 --> 00:15:32,320",arabic:"وَإِلَى أَيْنَ وَصَلْتَ يَا ثُمَامَةُ؟",segs:[{ar:"وَإِلَى أَيْنَ وَصَلْتَ",uz:"qanday natijaga yetdingiz"},{ar:"يَا ثُمَامَةُ",uz:"ey Sumoma"}],full_uz:"Qanday natijaga yetdingiz, Sumoma?",note:"إِلَى أَيْنَ وَصَلْتَ؟ so‘zma-so‘z «qayergacha yetdingiz?»; ishning natijasi yoki rivojini so‘rash uchun ham ishlatiladi."},
{num:174,time:"00:15:32,320 --> 00:15:34,159",arabic:"الْأَمْرُ مَا أَقُولُهُ لَكَ الْآنَ.",segs:[{ar:"الْأَمْرُ",uz:"vaziyat shuki"},{ar:"مَا أَقُولُهُ لَكَ الْآنَ",uz:"hozir sizga aytayotganim"}],full_uz:"Vaziyat hozir sizga aytayotganimdek.",note:null},
{num:175,time:"00:15:34,159 --> 00:15:38,920",arabic:"الْمَأْمُونُ لَا يُرِيدُ إِثَارَةَ الْعَوَامِّ عَلَيْهِ.",segs:[{ar:"الْمَأْمُونُ لَا يُرِيدُ",uz:"Ma’mun istamaydi"},{ar:"إِثَارَةَ الْعَوَامِّ عَلَيْهِ",uz:"xalqni o‘ziga qarshi qo‘zg‘atishni"}],full_uz:"Ma’mun xalqni o‘ziga qarshi qo‘zg‘atishni istamaydi.",note:"أَثَارَ النَّاسَ عَلَيْهِ — «odamlarni unga qarshi qo‘zg‘atdi». إِثَارَةٌ — shu fe’lning masdari."},
{num:176,time:"00:15:38,920 --> 00:15:41,779",arabic:"فِي هَذَا الْوَقْتِ عَلَى الْأَقَلِّ.",segs:[{ar:"فِي هَذَا الْوَقْتِ",uz:"hozirgi vaqtda"},{ar:"عَلَى الْأَقَلِّ",uz:"hech bo‘lmaganda"}],full_uz:"Hech bo‘lmaganda hozirgi vaqtda.",note:"عَلَى الْأَقَلِّ — «hech bo‘lmaganda, kamida» ma’nosidagi turg‘un birikma."},
{num:177,time:"00:15:41,779 --> 00:15:44,560",arabic:"أَنْتَ تَعْرِفُ كُلَّ ذَلِكَ.",segs:[{ar:"أَنْتَ تَعْرِفُ",uz:"siz bilasiz"},{ar:"كُلَّ ذَلِكَ",uz:"bularning barchasini"}],full_uz:"Siz bularning barchasini bilasiz.",note:null},
{num:178,time:"00:15:44,559 --> 00:15:46,139",arabic:"فَلَا دَاعِيَ لِلشَّرْحِ.",segs:null,full_uz:"Shunday ekan, tushuntirishga hojat yo‘q.",note:"لَا دَاعِيَ لِـ — «...ga hojat yo‘q». دَاعِيَ jinsni inkor qiluvchi لَا ning ismi."},
{num:179,time:"00:15:46,139 --> 00:15:51,559",arabic:"الْحَرْبُ تَحْتَاجُ أَحْيَانًا إِلَى هُدْنَةٍ.",segs:[{ar:"الْحَرْبُ تَحْتَاجُ",uz:"urush muhtoj bo‘ladi"},{ar:"أَحْيَانًا",uz:"ba’zan"},{ar:"إِلَى هُدْنَةٍ",uz:"vaqtinchalik sulhga"}],full_uz:"Urushda ba’zan vaqtinchalik sulh kerak bo‘ladi.",note:"هُدْنَةٌ — urushni vaqtincha to‘xtatish, vaqtinchalik sulh. اِحْتَاجَ إِلَى — «...ga muhtoj bo‘ldi»."},
{num:180,time:"00:15:51,559 --> 00:15:55,559",arabic:"أَدْرِي يَا ابْنَ الْأَشْرَسِ.",segs:[{ar:"أَدْرِي",uz:"bilaman"},{ar:"يَا ابْنَ الْأَشْرَسِ",uz:"ey Ibn Ashras"}],full_uz:"Bilaman, Ibn Ashras.",note:"دَرَى — يَدْرِي — «bildi, biladi». أَدْرِي — «men bilaman»."},
{num:181,time:"00:15:55,559 --> 00:15:58,759",arabic:"إِنَّ فِي قَلْبِي...",segs:null,full_uz:"Qalbimda...",note:"إِنَّ dan keyin فِي قَلْبِي xabari oldinga chiqqan; gap tugallanmagani uchun uning ismi bu bandda aytilmagan."},
{num:182,time:"00:15:58,759 --> 00:16:00,559",arabic:"إِنَّ فِي قَلْبِكَ غَيْظًا.",segs:[{ar:"إِنَّ فِي قَلْبِكَ",uz:"albatta, qalbingizda bor"},{ar:"غَيْظًا",uz:"qattiq g‘azab"}],full_uz:"Qalbingizda qattiq g‘azab bor.",note:"غَيْظًا — إِنَّ ning keyin kelgan mansub ismi. غَيْظٌ — ichda to‘plangan kuchli g‘azab."},
{num:183,time:"00:16:01,199 --> 00:16:06,000",arabic:"يَجْعَلُكَ تَغْفُلُ عَنْ رُؤْيَةِ الْأُمُورِ بِشَكْلٍ صَحِيحٍ.",segs:[{ar:"يَجْعَلُكَ تَغْفُلُ",uz:"u sizni g‘ofil qiladi"},{ar:"عَنْ رُؤْيَةِ الْأُمُورِ",uz:"ishlarni ko‘rishdan"},{ar:"بِشَكْلٍ صَحِيحٍ",uz:"to‘g‘ri tarzda"}],full_uz:"U sizni ishlarni to‘g‘ri ko‘rishdan g‘ofil qiladi.",note:"جَعَلَهُ يَفْعَلُ — «uni biror ish qilishga olib keldi». غَفَلَ عَنْ — «...dan g‘ofil bo‘ldi, ...ga e’tibor bermadi»."},
{num:184,time:"00:16:06,000 --> 00:16:11,500",arabic:"إِنَّ إِخْوَانَنَا الْآنَ يَتَفَشَّوْنَ فِي جَسَدِ الْأُمَّةِ.",segs:[{ar:"إِنَّ إِخْوَانَنَا الْآنَ",uz:"birodarlarimiz hozir"},{ar:"يَتَفَشَّوْنَ",uz:"yoyilib bormoqda"},{ar:"فِي جَسَدِ الْأُمَّةِ",uz:"ummat tanasida"}],full_uz:"Birodarlarimiz hozir ummat tanasida yoyilib bormoqda.",note:"تَفَشَّى — «yoyildi, keng tarqaldi». جَسَدُ الْأُمَّةِ — ummatni bir tana sifatida tasvirlovchi ko‘chma ifoda."},
{num:185,time:"00:16:11,500 --> 00:16:14,399",arabic:"وَيُمْسِكُونَ بِجَمِيعِ مَفَاصِلِهَا.",segs:[{ar:"وَيُمْسِكُونَ",uz:"va nazoratga olmoqdalar"},{ar:"بِجَمِيعِ مَفَاصِلِهَا",uz:"uning barcha bo‘g‘inlarini"}],full_uz:"Va uning barcha bo‘g‘inlarini nazoratga olmoqdalar.",note:"مَفَاصِلُ — مَفْصِلٌ («bo‘g‘in»)ning ko‘pligi. Bu yerda jamiyatning muhim boshqaruv qismlari nazarda tutilgan."},
{num:186,time:"00:16:14,399 --> 00:16:17,019",arabic:"وَإِلَى أَنْ يَتِمَّ لَنَا التَّمْكِينُ...",segs:[{ar:"وَإِلَى أَنْ يَتِمَّ",uz:"to amalga oshguniga qadar"},{ar:"لَنَا التَّمْكِينُ",uz:"bizning hokimiyatimiz mustahkamlanishi"}],full_uz:"Bizning hokimiyatimiz mustahkamlanguniga qadar...",note:"التَّمْكِينُ — mavqe va hokimiyatni mustahkamlash. يَتِمُّ fe’li أَنْ dan keyin يَتِمَّ bo‘ladi."},
{num:187,time:"00:16:17,019 --> 00:16:22,100",arabic:"عِنْدَهَا فَقَطْ سَنَرُدُّ عَلَى هَؤُلَاءِ الْعَوَامِّ ظُلْمَهُمْ.",segs:[{ar:"عِنْدَهَا فَقَطْ",uz:"faqat o‘shandagina"},{ar:"سَنَرُدُّ عَلَى هَؤُلَاءِ الْعَوَامِّ",uz:"bu avomga qaytaramiz"},{ar:"ظُلْمَهُمْ",uz:"ularning zulmini"}],full_uz:"Faqat o‘shandagina bu avomning zulmini o‘zlariga qaytaramiz.",note:"رَدَّ عَلَيْهِ ظُلْمَهُ — «uning zulmiga javob qaytardi». الْعَوَامُّ bu nutqda oddiy xalqni past nazar bilan atash uchun ishlatilgan."},
{num:188,time:"00:16:22,100 --> 00:16:27,319",arabic:"إِنَّ الْأَمْرَ بِحَاجَةٍ إِلَى الْكَثِيرِ مِنَ التَّأَنِّي يَا ابْنَ أَبِي دُؤَادٍ.",segs:[{ar:"إِنَّ الْأَمْرَ بِحَاجَةٍ",uz:"bu ish muhtoj"},{ar:"إِلَى الْكَثِيرِ مِنَ التَّأَنِّي",uz:"katta vazminlikka"},{ar:"يَا ابْنَ أَبِي دُؤَادٍ",uz:"ey Ibn Abu Duod"}],full_uz:"Bu ish katta vazminlikni talab qiladi, Ibn Abu Duod.",note:"التَّأَنِّي — shoshilmasdan, o‘ylab ish tutish. بِحَاجَةٍ إِلَى — «...ga muhtoj»."},
{num:189,time:"00:16:27,319 --> 00:16:31,959",arabic:"وَإِلَّا خَسِرْنَا صَبْرَ كُلِّ هَذِهِ السَّنَوَاتِ.",segs:[{ar:"وَإِلَّا خَسِرْنَا",uz:"aks holda, boy beramiz"},{ar:"صَبْرَ كُلِّ هَذِهِ السَّنَوَاتِ",uz:"shu yillarning barchasidagi sabrimizni"}],full_uz:"Aks holda, shu yillar davomida qilgan sabrimizni boy beramiz.",note:"وَإِلَّا — «aks holda». O‘tgan zamon shaklidagi خَسِرْنَا bu yerda shartning kelajakdagi natijasini bildiradi."},
{num:190,time:"00:16:31,959 --> 00:16:39,799",arabic:"إِنَّمَا أَقُولُ ذَلِكَ غَيْرَةً عَلَى دِينِي وَاعْتِقَادِي كَمَا تَعْلَمُ.",segs:[{ar:"إِنَّمَا أَقُولُ ذَلِكَ",uz:"buni faqat aytyapman"},{ar:"غَيْرَةً عَلَى دِينِي وَاعْتِقَادِي",uz:"dinim va e’tiqodimni himoya qilish hissi bilan"},{ar:"كَمَا تَعْلَمُ",uz:"o‘zingiz bilganingizdek"}],full_uz:"O‘zingiz bilganingizdek, buni faqat dinim va e’tiqodimni himoya qilish hissi bilan aytyapman.",note:"غَيْرَةً harakatning sababini bildiruvchi maf’ul li-ajlih. غَيْرَةٌ عَلَى bu yerda qadrlagan narsasini qizg‘anib himoya qilish hissidir."},
{num:191,time:"00:16:39,799 --> 00:16:47,039",arabic:"أَعْرِفُ، وَأَعْرِفُ أَيْضًا أَنَّ أَيَّ خَطَإٍ سَنَدْفَعُ نَحْنُ ثَمَنَهُ.",segs:[{ar:"أَعْرِفُ",uz:"bilaman"},{ar:"وَأَعْرِفُ أَيْضًا",uz:"yana shuni ham bilaman"},{ar:"أَنَّ أَيَّ خَطَإٍ",uz:"har qanday xatoning"},{ar:"سَنَدْفَعُ نَحْنُ ثَمَنَهُ",uz:"badalini aynan biz to‘laymiz"}],full_uz:"Bilaman. Har qanday xatoning badalini aynan biz to‘lashimizni ham bilaman.",note:"دَفَعَ ثَمَنَ خَطَئِهِ — «xatosining badalini to‘ladi». نَحْنُ olmoshi ishni aynan kim bajarishini ta’kidlaydi."},
{num:192,time:"00:16:47,039 --> 00:16:48,539",arabic:"الصَّبْرَ!",segs:null,full_uz:"Sabr qiling!",note:"الصَّبْرَ undash ma’nosida mansub kelgan: yashirin ma’no «sabrni mahkam tuting»."},
{num:193,time:"00:16:48,539 --> 00:16:52,079",arabic:"الصَّبْرَ يَا ابْنَ أَبِي دُؤَادٍ.",segs:[{ar:"الصَّبْرَ",uz:"sabr qiling"},{ar:"يَا ابْنَ أَبِي دُؤَادٍ",uz:"ey Ibn Abu Duod"}],full_uz:"Sabr qiling, Ibn Abu Duod.",note:null},
{num:194,time:"00:16:52,080 --> 00:17:09,880",arabic:"أَضْحَتْ بَغْدَادُ مَكَانًا لَا يُطَاقُ.",segs:[{ar:"أَضْحَتْ بَغْدَادُ",uz:"Bag‘dod aylanib qoldi"},{ar:"مَكَانًا لَا يُطَاقُ",uz:"chidab bo‘lmaydigan joyga"}],full_uz:"Bag‘dod chidab bo‘lmaydigan joyga aylanib qoldi.",note:"أَضْحَى bu yerda «bo‘lib qoldi, aylandi» ma’nosida. يُطَاقُ — majhul nisbat: «chidash mumkin bo‘ladi»."},
{num:195,time:"00:17:09,880 --> 00:17:13,259",arabic:"صِرْنَا نَرَى الْجَهْمِيَّةَ وَالْمُعْتَزِلَةَ بَيْنَنَا فِي كُلِّ مَكَانٍ.",segs:[{ar:"صِرْنَا نَرَى",uz:"ko‘radigan bo‘lib qoldik"},{ar:"الْجَهْمِيَّةَ وَالْمُعْتَزِلَةَ",uz:"jahmiylar va mu’taziliylarni"},{ar:"بَيْنَنَا",uz:"oramizda"},{ar:"فِي كُلِّ مَكَانٍ",uz:"har bir joyda"}],full_uz:"Jahmiylar va mu’taziliylarni oramizda, har bir joyda ko‘radigan bo‘lib qoldik.",note:"صَارَ + muzori’ fe’l yangi holatga o‘tishni bildiradi: صِرْنَا نَرَى — «ko‘radigan bo‘lib qoldik»."},
{num:196,time:"00:17:13,259 --> 00:17:15,720",arabic:"فِي الْمَسْجِدِ وَالسُّوقِ وَالْأَزِقَّةِ.",segs:[{ar:"فِي الْمَسْجِدِ",uz:"masjidda"},{ar:"وَالسُّوقِ وَالْأَزِقَّةِ",uz:"bozorda va tor ko‘chalarda"}],full_uz:"Masjidda, bozorda va tor ko‘chalarda.",note:"أَزِقَّةٌ — زُقَاقٌ («tor ko‘cha»)ning ko‘pligi."},
{num:197,time:"00:17:15,720 --> 00:17:18,880",arabic:"يُوشِكُونَ أَنْ يَدْخُلُوا عَلَيْنَا بُيُوتَنَا.",segs:[{ar:"يُوشِكُونَ أَنْ يَدْخُلُوا",uz:"kirib kelishlariga oz qoldi"},{ar:"عَلَيْنَا بُيُوتَنَا",uz:"bizning uylarimizga ham"}],full_uz:"Bizning uylarimizga ham kirib kelishlariga oz qoldi.",note:"أَوْشَكَ أَنْ — «...ishiga oz qoldi». يُوشِكُونَ ko‘plik shakli."},
{num:198,time:"00:17:18,880 --> 00:17:21,519",arabic:"وَلَا نَجْرُؤُ عَلَى أَنْ نَمْنَعَهُمْ.",segs:[{ar:"وَلَا نَجْرُؤُ",uz:"biz esa jur’at qilolmaymiz"},{ar:"عَلَى أَنْ نَمْنَعَهُمْ",uz:"ularni to‘xtatishga"}],full_uz:"Biz esa ularni to‘xtatishga jur’at qilolmaymiz.",note:"جَرُؤَ عَلَى — «...ga jur’at qildi». أَنْ نَمْنَعَهُمْ — «ularni to‘xtatishimiz»."},
{num:199,time:"00:17:21,519 --> 00:17:24,119",arabic:"فَقَدْ أَحَاطَهُمُ الْمَأْمُونُ بِعِنَايَتِهِ.",segs:[{ar:"فَقَدْ أَحَاطَهُمُ الْمَأْمُونُ",uz:"chunki Ma’mun ularni o‘rab olgan"},{ar:"بِعِنَايَتِهِ",uz:"o‘z e’tibori bilan"}],full_uz:"Chunki Ma’mun ularni o‘z e’tibori va g‘amxo‘rligi bilan o‘rab olgan.",note:"أَحَاطَهُ بِعِنَايَتِهِ — «unga katta e’tibor va g‘amxo‘rlik ko‘rsatdi»."},
{num:200,time:"00:17:24,119 --> 00:17:28,460",arabic:"غَفَرَ اللَّهُ لِأَمِيرِ الْمُؤْمِنِينَ.",segs:[{ar:"غَفَرَ اللَّهُ",uz:"Alloh kechirsin"},{ar:"لِأَمِيرِ الْمُؤْمِنِينَ",uz:"mo‘minlar amirini"}],full_uz:"Alloh mo‘minlar amirini kechirsin.",note:null},
{num:201,time:"00:17:28,460 --> 00:17:32,359",arabic:"لَوْلَا أَنَّهُ سَمَحَ لَهُمْ بِنَشْرِ بِدَعِهِمْ بَيْنَنَا...",segs:[{ar:"لَوْلَا أَنَّهُ سَمَحَ لَهُمْ",uz:"agar u ularga ruxsat bermaganida"},{ar:"بِنَشْرِ بِدَعِهِمْ",uz:"bid’atlarini tarqatishga"},{ar:"بَيْنَنَا",uz:"oramizda"}],full_uz:"Agar u ularga oramizda bid’atlarini tarqatishga ruxsat bermaganida...",note:"بِدَعٌ — بِدْعَةٌ so‘zining ko‘pligi. لَوْلَا dan keyingi shartning natijasi navbatdagi bandda keladi."},
{num:202,time:"00:17:32,359 --> 00:17:34,599",arabic:"لَمَا كَانَ لَنَا أَنْ نَرَاهُمْ.",segs:[{ar:"لَمَا كَانَ لَنَا",uz:"bizga ...bo‘lmagan bo‘lardi"},{ar:"أَنْ نَرَاهُمْ",uz:"ularni ko‘rish"}],full_uz:"Biz ularni ko‘rmagan bo‘lardik.",note:"لَمَا bu yerda لَـ javob yuklamasi va مَا inkor yuklamasidan tuzilgan; «hali ...madi» ma’nosidagi لَمَّا bilan bir xil emas."},
{num:203,time:"00:17:34,599 --> 00:17:37,960",arabic:"فَقَدْ كَانُوا فِي عَهْدِ الرَّشِيدِ وَالْأَمِينِ، رَحِمَهُمَا اللَّهُ...",segs:[{ar:"فَقَدْ كَانُوا",uz:"axir ular ...edilar"},{ar:"فِي عَهْدِ الرَّشِيدِ وَالْأَمِينِ",uz:"Rashid va Amin davrida"},{ar:"رَحِمَهُمَا اللَّهُ",uz:"Alloh ikkalasini rahmatiga olsin"}],full_uz:"Axir ular Rashid va Amin davrida — Alloh ikkalasini rahmatiga olsin — ...edilar.",note:"عَهْدٌ bu yerda hukmronlik davrini bildiradi. ـهُمَا ikki kishiga qaytuvchi olmosh."},
{num:204,time:"00:17:37,960 --> 00:17:40,379",arabic:"لَا يَجْرُؤُونَ عَلَى إِظْهَارِ بِدَعِهِمْ.",segs:[{ar:"لَا يَجْرُؤُونَ",uz:"jur’at qilolmas edilar"},{ar:"عَلَى إِظْهَارِ بِدَعِهِمْ",uz:"bid’atlarini oshkor qilishga"}],full_uz:"Bid’atlarini oshkor qilishga jur’at qilolmas edilar.",note:"إِظْهَارٌ — أَظْهَرَ («oshkor qildi») fe’lining masdari."},
{num:205,time:"00:17:40,379 --> 00:17:43,160",arabic:"فَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ.",segs:[{ar:"فَلَا حَوْلَ وَلَا قُوَّةَ",uz:"bas, hech qanday qudrat ham, kuch ham yo‘q"},{ar:"إِلَّا بِاللَّهِ",uz:"faqat Allohning yordami bilangina bor"}],full_uz:"Bas, qudrat va kuch faqat Allohning yordami bilangina bo‘ladi.",note:null},
{num:206,time:"00:17:43,160 --> 00:17:45,639",arabic:"أَلَا يَجْدُرُ بِنَا أَنْ نُوَاجِهَهُمْ يَا إِمَامُ؟",segs:[{ar:"أَلَا يَجْدُرُ بِنَا",uz:"bizga lozim emasmi"},{ar:"أَنْ نُوَاجِهَهُمْ",uz:"ularga qarshi turish"},{ar:"يَا إِمَامُ",uz:"ey imom"}],full_uz:"Ularga qarshi turishimiz lozim emasmi, imom?",note:"وَاجَهَ — «yuzma-yuz keldi, qarshi turdi». يَجْدُرُ بِنَا أَنْ — «biz ...ishimiz lozim»."},
{num:207,time:"00:17:45,639 --> 00:17:48,920",arabic:"لَا يَا أَبَا بَكْرٍ.",segs:[{ar:"لَا",uz:"yo‘q"},{ar:"يَا أَبَا بَكْرٍ",uz:"ey Abu Bakr"}],full_uz:"Yo‘q, Abu Bakr.",note:null},
{num:208,time:"00:17:48,920 --> 00:17:53,820",arabic:"إِنْ فَعَلْنَا فَقَدْ أَهْدَيْنَاهُمْ مَا يَنْتَظِرُونَ وَمَا يَتَرَقَّبُونَ.",segs:[{ar:"إِنْ فَعَلْنَا",uz:"agar shunday qilsak"},{ar:"فَقَدْ أَهْدَيْنَاهُمْ",uz:"ularga hadya qilgan bo‘lamiz"},{ar:"مَا يَنْتَظِرُونَ",uz:"ular kutayotgan narsani"},{ar:"وَمَا يَتَرَقَّبُونَ",uz:"va ko‘z tutayotgan narsani"}],full_uz:"Agar shunday qilsak, ular kutayotgan va ko‘z tutayotgan narsani ularga hadya qilgan bo‘lamiz.",note:"أَهْدَى — «hadya qildi». تَرَقَّبَ — diqqat bilan kutdi, bir narsaning yuz berishini kuzatib turdi."},
{num:209,time:"00:17:53,820 --> 00:17:58,019",arabic:"وَلَكِنَّ كَثْرَةً مِنَ الْعَوَامِّ يَسْتَمِعُونَ إِلَيْهِمْ.",segs:[{ar:"وَلَكِنَّ كَثْرَةً مِنَ الْعَوَامِّ",uz:"lekin oddiy xalqning ko‘pchiligi"},{ar:"يَسْتَمِعُونَ إِلَيْهِمْ",uz:"ularni tinglayapti"}],full_uz:"Lekin oddiy xalqning ko‘pchiligi ularni tinglayapti.",note:"اِسْتَمَعَ إِلَى — «...ni tingladi». كَثْرَةً bu yerda kishilarning katta qismini bildiradi."},
{num:210,time:"00:17:58,019 --> 00:18:00,539",arabic:"فَهَلْ نَظَلُّ هَكَذَا مَكْتُوفِي الْأَيْدِي؟",segs:[{ar:"فَهَلْ نَظَلُّ هَكَذَا",uz:"shunday qolaveramizmi"},{ar:"مَكْتُوفِي الْأَيْدِي",uz:"qo‘l qovushtirib"}],full_uz:"Shunday qo‘l qovushtirib qolaveramizmi?",note:"مَكْتُوفُ الْيَدَيْنِ so‘zma-so‘z «qo‘llari bog‘langan»; ko‘chma ma’noda harakatsiz turish. مَكْتُوفِي shaklida izofa sababli ko‘plik nuni tushgan."},
{num:211,time:"00:18:01,960 --> 00:18:03,640",arabic:"وَلَا ذَلِكَ يَا فَوْرَانُ.",segs:[{ar:"وَلَا ذَلِكَ",uz:"unday ham emas"},{ar:"يَا فَوْرَانُ",uz:"ey Favron"}],full_uz:"Unday ham emas, Favron.",note:null},
{num:212,time:"00:18:03,640 --> 00:18:07,039",arabic:"يَجِبُ عَلَيْنَا أَلَّا نُخَالِطَهُمْ أَوْ نُجَالِسَهُمْ.",segs:[{ar:"يَجِبُ عَلَيْنَا",uz:"biz ...ishimiz kerak"},{ar:"أَلَّا نُخَالِطَهُمْ",uz:"ular bilan aralashmasligimiz"},{ar:"أَوْ نُجَالِسَهُمْ",uz:"yoki birga o‘tirmasligimiz"}],full_uz:"Biz ular bilan aralashmasligimiz yoki birga o‘tirmasligimiz kerak.",note:"خَالَطَ — «aralashdi, yaqin muomalada bo‘ldi». جَالَسَ — «birga o‘tirdi, suhbatdosh bo‘ldi»."},
{num:213,time:"00:18:07,039 --> 00:18:12,539",arabic:"وَفِي الْوَقْتِ نَفْسِهِ يَجِبُ أَلَّا نَتْرُكَ طَرِيقًا لِتَعْلِيمِ النَّاسِ الْعَقِيدَةَ الصَّحِيحَةَ إِلَّا سَلَكْنَاهُ.",segs:[{ar:"وَفِي الْوَقْتِ نَفْسِهِ",uz:"ayni paytda esa"},{ar:"يَجِبُ أَلَّا نَتْرُكَ طَرِيقًا",uz:"biror yo‘lni qoldirmasligimiz kerak"},{ar:"لِتَعْلِيمِ النَّاسِ",uz:"odamlarga o‘rgatish uchun"},{ar:"الْعَقِيدَةَ الصَّحِيحَةَ",uz:"to‘g‘ri aqidani"},{ar:"إِلَّا سَلَكْنَاهُ",uz:"undan yurib o‘tmasdan"}],full_uz:"Ayni paytda odamlarga to‘g‘ri aqidani o‘rgatish uchun biror yo‘lni ham foydalanmay qoldirmasligimiz kerak.",note:"سَلَكَ طَرِيقًا — «bir yo‘ldan yurdi». لَا نَتْرُكَ ... إِلَّا سَلَكْنَاهُ barcha imkoniyatdan foydalanish ma’nosini beradi."},
{num:214,time:"00:18:13,120 --> 00:18:16,140",arabic:"وَلَكِنَّهُمْ هُمْ مَنْ يَتَعَرَّضُونَ لَنَا يَا إِمَامُ.",segs:[{ar:"وَلَكِنَّهُمْ هُمْ",uz:"lekin aynan ularning o‘zi"},{ar:"مَنْ يَتَعَرَّضُونَ لَنَا",uz:"bizga tegayotganlar"},{ar:"يَا إِمَامُ",uz:"ey imom"}],full_uz:"Lekin bizga tegayotgan aynan ularning o‘zi-ku, imom.",note:"هُمْ ning takror kelishi ta’kid uchun: «aynan ularning o‘zi». تَعَرَّضَ لِـ bu yerda «tegdi, bezovta qildi»."},
{num:215,time:"00:18:16,140 --> 00:18:18,539",arabic:"تَحَاشَوْهُمْ مَا اسْتَطَعْتُمْ.",segs:[{ar:"تَحَاشَوْهُمْ",uz:"ulardan chetlaning"},{ar:"مَا اسْتَطَعْتُمْ",uz:"qo‘lingizdan kelganicha"}],full_uz:"Qo‘lingizdan kelganicha ulardan chetlaning.",note:"تَحَاشَى — «o‘zini chetga oldi, chetlandi». تَحَاشَوْا — ko‘plik buyruq shakli."},
{num:216,time:"00:18:18,920 --> 00:18:28,900",arabic:"وَدِدْتُ لَوْ أَنَّ أُمِّي، رَحِمَهَا اللَّهُ...",segs:[{ar:"وَدِدْتُ لَوْ أَنَّ أُمِّي",uz:"qaniydi onam ...ganlarida edi"},{ar:"رَحِمَهَا اللَّهُ",uz:"Alloh u kishini rahmatiga olsin"}],full_uz:"Qaniydi onam — Alloh u kishini rahmatiga olsin — ...ganlarida edi.",note:"وَدِدْتُ لَوْ — «qaniydi ...bo‘lganida edi». Amalga oshmagan istakni ham ifodalashi mumkin."},
{num:217,time:"00:18:28,900 --> 00:18:30,779",arabic:"رَأَتْ حَفِيدَهَا صَالِحًا.",segs:[{ar:"رَأَتْ",uz:"ko‘rganlarida edi"},{ar:"حَفِيدَهَا صَالِحًا",uz:"nabiralari Solihni"}],full_uz:"Nabiralari Solihni ko‘rganlarida edi.",note:"حَفِيدٌ — «nabira». صَالِحًا bu yerda nabiraning ismi bo‘lib, حَفِيدَهَا kabi mansub kelgan."},
{num:218,time:"00:18:30,779 --> 00:18:33,500",arabic:"رَحِمَهَا اللَّهُ.",segs:null,full_uz:"Alloh u kishini rahmatiga olsin.",note:null},
{num:219,time:"00:18:33,500 --> 00:18:38,720",arabic:"قَدْ تَرَكَتْ خَيْرَ رَجُلٍ وَخَيْرَ زَوْجٍ وَخَيْرَ أَبٍ.",segs:[{ar:"قَدْ تَرَكَتْ",uz:"u kishi qoldirganlar"},{ar:"خَيْرَ رَجُلٍ",uz:"eng yaxshi insonni"},{ar:"وَخَيْرَ زَوْجٍ",uz:"eng yaxshi erni"},{ar:"وَخَيْرَ أَبٍ",uz:"va eng yaxshi otani"}],full_uz:"U kishi eng yaxshi insonni, eng yaxshi erni va eng yaxshi otani qoldirganlar.",note:"خَيْرُ bu yerda «eng yaxshi» ma’nosida. Uchta ta’rif bir kishiga tegishli."},
{num:220,time:"00:18:38,720 --> 00:18:42,060",arabic:"كَانَ أَشَدَّ رَغْبَتِهَا أَنْ تَرَى أَحْفَادَهَا.",segs:[{ar:"كَانَ أَشَدَّ رَغْبَتِهَا",uz:"eng kuchli istaklari edi"},{ar:"أَنْ تَرَى أَحْفَادَهَا",uz:"nabiralarini ko‘rish"}],full_uz:"Nabiralarini ko‘rish u kishining eng kuchli istaklari edi.",note:"أَحْفَادٌ — حَفِيدٌ so‘zining ko‘pligi. أَنْ تَرَى birikmasi «ko‘rish» degan masdar ma’nosini beradi."},
{num:221,time:"00:18:42,060 --> 00:18:47,800",arabic:"وَلَكِنِ الْحَمْدُ لِلَّهِ، قَدَّرَ اللَّهُ وَمَا شَاءَ فَعَلَ.",segs:[{ar:"وَلَكِنِ الْحَمْدُ لِلَّهِ",uz:"lekin Allohga hamd bo‘lsin"},{ar:"قَدَّرَ اللَّهُ",uz:"Alloh taqdir qildi"},{ar:"وَمَا شَاءَ فَعَلَ",uz:"va xohlaganini qildi"}],full_uz:"Lekin Allohga hamd bo‘lsin. Alloh taqdir qildi va xohlaganini qildi.",note:"مَا شَاءَ فَعَلَ — «xohlagan narsasini qildi». مَا bu yerda «...gan narsa» ma’nosida."},
{num:222,time:"00:18:47,799 --> 00:18:50,180",arabic:"كَمْ كَانَتْ تَطْلُبُ مِنِّي ذَلِكَ!",segs:[{ar:"كَمْ كَانَتْ تَطْلُبُ مِنِّي",uz:"mendan qanchalar ko‘p so‘rardilar"},{ar:"ذَلِكَ",uz:"shuni"}],full_uz:"Mendan shuni qanchalar ko‘p so‘rardilar!",note:"كَمْ bu yerda savol emas, ko‘plik va taajjubni bildiradi. كَانَتْ تَطْلُبُ — o‘tmishda takrorlangan ish."},
{num:223,time:"00:18:50,180 --> 00:18:53,619",arabic:"وَلَكِنَّنِي لَمْ أُجِبْهَا إِلَى مَا أَرَادَتْ.",segs:[{ar:"وَلَكِنَّنِي لَمْ أُجِبْهَا",uz:"lekin men u kishining istagini qondirmadim"},{ar:"إِلَى مَا أَرَادَتْ",uz:"xohlagan narsalarida"}],full_uz:"Lekin men u kishining xohlaganlarini amalga oshirmadim.",note:"أَجَابَهُ إِلَى طَلَبِهِ — «uning iltimosini qabul qildi, istagini bajardi». أُجِيبُ fe’li لَمْ dan keyin أُجِبْ bo‘ladi."},
{num:224,time:"00:18:53,619 --> 00:18:57,799",arabic:"مَا الَّذِي مَنَعَكَ مِنْ أَنْ تُحَقِّقَ رَغْبَتَهَا؟",segs:[{ar:"مَا الَّذِي مَنَعَكَ",uz:"sizga nima to‘sqinlik qildi"},{ar:"مِنْ أَنْ تُحَقِّقَ رَغْبَتَهَا",uz:"u kishining istagini amalga oshirishga"}],full_uz:"U kishining istagini amalga oshirishingizga nima to‘sqinlik qildi?",note:"حَقَّقَ رَغْبَتَهُ — «uning istagini amalga oshirdi»."},
{num:225,time:"00:18:59,220 --> 00:18:59,639",arabic:"الْعِلْمُ.",segs:null,full_uz:"Ilm.",note:null},
{num:226,time:"00:18:59,639 --> 00:19:02,379",arabic:"الْعِلْمُ يَا أُمَّ صَالِحٍ.",segs:[{ar:"الْعِلْمُ",uz:"ilm"},{ar:"يَا أُمَّ صَالِحٍ",uz:"ey Solihning onasi"}],full_uz:"Ilm, Ummu Solih.",note:"أُمُّ صَالِحٍ — «Solihning onasi» ma’nosidagi kunya. Izofali munodo bo‘lgani uchun يَا أُمَّ shaklida keladi."},
{num:227,time:"00:19:02,379 --> 00:19:04,799",arabic:"أَخَذَنِي حَتَّى مِنْ نَفْسِي.",segs:[{ar:"أَخَذَنِي",uz:"meni olib qo‘ydi"},{ar:"حَتَّى مِنْ نَفْسِي",uz:"hatto o‘zimdan ham"}],full_uz:"Meni hatto o‘zimdan ham olib qo‘ydi.",note:"Bu ko‘chma ifoda ilm bilan shu qadar band bo‘lishni anglatadiki, kishi o‘ziga ham vaqt ajratmay qoladi."},
{num:228,time:"00:19:05,519 --> 00:19:07,079",arabic:"فَقَدْ ضَرَبْتُ الْآفَاقَ.",segs:null,full_uz:"Men uzoq yurtlarni kezdim.",note:"ضَرَبَ الْآفَاقَ — «uzoq yurtlarga safar qildi, dunyo kezdi». ضَرَبَ bu iborada «urdi» ma’nosida emas."},
{num:229,time:"00:19:07,079 --> 00:19:09,779",arabic:"وَلَمْ أَتْرُكْ شَيْخًا إِلَّا وَرَحَلْتُ إِلَيْهِ.",segs:[{ar:"وَلَمْ أَتْرُكْ شَيْخًا",uz:"biror shayxni qoldirmadim"},{ar:"إِلَّا وَرَحَلْتُ إِلَيْهِ",uz:"uning huzuriga safar qilmasdan"}],full_uz:"Huzuriga safar qilmagan biror shayxni qoldirmadim.",note:"لَمْ ... إِلَّا tuzilishi barcha tegishli kishilarni qamrab olishni bildiradi. رَحَلَ إِلَى — «...tomon safar qildi»."},
{num:230,time:"00:19:09,779 --> 00:19:14,180",arabic:"فَأَيُّ زَوْجَةٍ كَانَتْ لِتَرْضَى بِرِفْقَةِ زَوْجٍ مِثْلِي؟",segs:[{ar:"فَأَيُّ زَوْجَةٍ",uz:"qaysi ayol"},{ar:"كَانَتْ لِتَرْضَى",uz:"rozi bo‘lardi"},{ar:"بِرِفْقَةِ زَوْجٍ مِثْلِي",uz:"mendek er bilan umr kechirishga"}],full_uz:"Qaysi ayol mendek er bilan umr kechirishga rozi bo‘lardi?",note:"رَضِيَ بِـ — «...ga rozi bo‘ldi». رِفْقَةٌ — hamrohlik, birga bo‘lish."},
{num:231,time:"00:19:14,180 --> 00:19:15,259",arabic:"حَسَنًا فَعَلْتَ.",segs:null,full_uz:"Yaxshi qilgansiz.",note:"حَسَنًا فَعَلْتَ — «yaxshi ish qildingiz» ma’nosidagi baholash iborasi."},
{num:232,time:"00:19:15,259 --> 00:19:20,140",arabic:"تَعْرِفُ، لَوْ أَنَّكَ طَلَبْتَنِي لِلزَّوَاجِ وَأَنْتَ فِي حَالِكَ تِلْكَ...",segs:[{ar:"تَعْرِفُ",uz:"bilasizmi"},{ar:"لَوْ أَنَّكَ طَلَبْتَنِي لِلزَّوَاجِ",uz:"agar meni nikohingizga so‘raganingizda"},{ar:"وَأَنْتَ فِي حَالِكَ تِلْكَ",uz:"o‘sha holatingizda bo‘lib"}],full_uz:"Bilasizmi, agar o‘sha holatingizda meni nikohingizga so‘raganingizda...",note:"وَأَنْتَ فِي حَالِكَ تِلْكَ — hol gapi: taklif paytidagi vaziyatni bildiradi."},
{num:233,time:"00:19:20,140 --> 00:19:25,900",arabic:"لَمَا كُنْتُ أَرْضَى بِكَ زَوْجًا حَتَّى تَنْفُضَ رَاحَتَيْكَ مِنَ التَّرْحَالِ.",segs:[{ar:"لَمَا كُنْتُ أَرْضَى بِكَ زَوْجًا",uz:"sizni er sifatida qabul qilishga rozi bo‘lmasdim"},{ar:"حَتَّى تَنْفُضَ رَاحَتَيْكَ",uz:"ikki kaftingizni qoqmaguningizcha"},{ar:"مِنَ التَّرْحَالِ",uz:"safar qilishdan"}],full_uz:"Safar qilishni yig‘ishtirmaguningizcha, sizni er sifatida qabul qilishga rozi bo‘lmasdim.",note:"نَفَضَ رَاحَتَيْهِ مِنْ — so‘zma-so‘z «ikki kaftini ...dan qoqdi»; ko‘chma ma’noda bir ishni yig‘ishtirish. التَّرْحَالُ — ko‘p safar qilish."},
{num:234,time:"00:19:25,900 --> 00:19:32,539",arabic:"فَكَيْفَ لِي أَنْ أَصْبِرَ عَلَى فِرَاقِ زَوْجٍ فِي مِثْلِ دِينِكَ وَخُلُقِكَ؟",segs:[{ar:"فَكَيْفَ لِي أَنْ أَصْبِرَ",uz:"qanday qilib sabr qila olaman"},{ar:"عَلَى فِرَاقِ زَوْجٍ",uz:"bir erning ayrilig‘iga"},{ar:"فِي مِثْلِ دِينِكَ وَخُلُقِكَ",uz:"dindorligi va xulqi siznikidek bo‘lgan"}],full_uz:"Dindorligi va xulqi siznikidek bo‘lgan erning ayrilig‘iga qanday sabr qila olaman?",note:"كَيْفَ لِي أَنْ — «qanday qilib ...qila olaman?». خُلُقٌ — xulq-atvor; خَلْقٌ esa yaratilish yoki tashqi tuzilishni anglatadi."},
{num:235,time:"00:19:32,539 --> 00:19:36,579",arabic:"أَكْرَمَنِيَ اللَّهُ بِكِ يَا زَوْجِي، وَرَحِمَ اللَّهُ أُمِّي.",segs:[{ar:"أَكْرَمَنِيَ اللَّهُ بِكِ",uz:"Alloh sizni menga berib, meni siyladi"},{ar:"يَا زَوْجِي",uz:"ey jufti halolim"},{ar:"وَرَحِمَ اللَّهُ أُمِّي",uz:"Alloh onamni rahmatiga olsin"}],full_uz:"Alloh sizni menga berib, meni siyladi, jufti halolim. Alloh onamni rahmatiga olsin.",note:"زَوْجٌ erkak yoki ayol turmush o‘rtog‘iga nisbatan ishlatilishi mumkin. بِكِ ayolga murojaatni bildiradi."},
{num:236,time:"00:19:36,579 --> 00:19:38,879",arabic:"كُنْتُ أَقُولُ لَهَا ذَلِكَ وَلَا تَقْتَنِعُ.",segs:[{ar:"كُنْتُ أَقُولُ لَهَا ذَلِكَ",uz:"u kishiga shuni aytardim"},{ar:"وَلَا تَقْتَنِعُ",uz:"ammo ko‘nmasdilar"}],full_uz:"U kishiga shuni aytardim, ammo ko‘nmasdilar.",note:"اِقْتَنَعَ — «ishondi, fikrga qo‘shildi, qanoat hosil qildi»."},
{num:237,time:"00:19:38,879 --> 00:19:42,339",arabic:"حَدِّثْنِي عَنْ أُمِّكَ يَا أَبَا عَبْدِ اللَّهِ.",segs:[{ar:"حَدِّثْنِي عَنْ أُمِّكَ",uz:"onangiz haqida menga gapirib bering"},{ar:"يَا أَبَا عَبْدِ اللَّهِ",uz:"ey Abu Abdulloh"}],full_uz:"Onangiz haqida menga gapirib bering, Abu Abdulloh.",note:"حَدَّثَ فُلَانًا عَنْ شَيْءٍ — «bir kishiga bir narsa haqida gapirib berdi»."},
{num:238,time:"00:19:42,339 --> 00:19:44,900",arabic:"كَيْفَ كَانَ حَالُهَا مَعَكَ؟",segs:[{ar:"كَيْفَ كَانَ حَالُهَا",uz:"u kishining munosabati qanday edi"},{ar:"مَعَكَ",uz:"siz bilan"}],full_uz:"U kishining siz bilan munosabati qanday edi?",note:null},
{num:239,time:"00:19:44,900 --> 00:19:51,400",arabic:"كَيْفَ رَبَّتْكَ؟ أُرِيدُ أَنْ أَعْرِفَ مَنْ هِيَ الَّتِي أَنْجَبَتْ رَجُلًا كَأَحْمَدَ بْنِ حَنْبَلٍ.",segs:[{ar:"كَيْفَ رَبَّتْكَ",uz:"sizni qanday tarbiyalaganlar"},{ar:"أُرِيدُ أَنْ أَعْرِفَ",uz:"bilishni istayman"},{ar:"مَنْ هِيَ الَّتِي أَنْجَبَتْ",uz:"kim ekan u dunyoga keltirgan ayol"},{ar:"رَجُلًا كَأَحْمَدَ بْنِ حَنْبَلٍ",uz:"Ahmad ibn Hanbaldek kishini"}],full_uz:"Sizni qanday tarbiyalaganlar? Ahmad ibn Hanbaldek kishini dunyoga keltirgan ayol kim ekanini bilishni istayman.",note:"رَبَّى — «tarbiyaladi»; رَبَّتْكَ — «u ayol sizni tarbiyaladi». أَنْجَبَتْ — «dunyoga keltirdi»."},
{num:240,time:"00:19:51,400 --> 00:19:53,540",arabic:"وَأَنَا ابْنُ عَشْرِ سِنِينَ...",segs:null,full_uz:"Men o‘n yoshda ekanimda...",note:"أَنَا ابْنُ عَشْرِ سِنِينَ so‘zma-so‘z «men o‘n yilning o‘g‘liman»; yoshni aytish usuli."},
{num:241,time:"00:19:53,540 --> 00:19:59,480",arabic:"كَانَتْ أُمِّي، رَحِمَهَا اللَّهُ، تُوقِظُنِي قَبْلَ الْفَجْرِ بِقَلِيلٍ لِأَسْتَعِدَّ لِلصَّلَاةِ.",segs:[{ar:"كَانَتْ أُمِّي",uz:"onam ...qilar edilar"},{ar:"رَحِمَهَا اللَّهُ",uz:"Alloh u kishini rahmatiga olsin"},{ar:"تُوقِظُنِي",uz:"meni uyg‘otardilar"},{ar:"قَبْلَ الْفَجْرِ بِقَلِيلٍ",uz:"bomdoddan biroz oldin"},{ar:"لِأَسْتَعِدَّ لِلصَّلَاةِ",uz:"namozga tayyorlanishim uchun"}],full_uz:"Onam — Alloh u kishini rahmatiga olsin — namozga tayyorlanishim uchun meni bomdoddan biroz oldin uyg‘otardilar.",note:"أَيْقَظَ — يُوقِظُ — «uyg‘otdi, uyg‘otadi». لِأَسْتَعِدَّ dagi لِـ maqsadni bildiradi."},
{num:242,time:"00:19:59,480 --> 00:20:02,259",arabic:"ثُمَّ تَذْهَبُ بِي إِلَى الْمَسْجِدِ.",segs:[{ar:"ثُمَّ تَذْهَبُ بِي",uz:"keyin meni olib borardilar"},{ar:"إِلَى الْمَسْجِدِ",uz:"masjidga"}],full_uz:"Keyin meni masjidga olib borardilar.",note:"ذَهَبَ بِهِ — «uni olib ketdi, olib bordi». بِـ fe’lga olib borish ma’nosini qo‘shadi."},
{num:243,time:"00:20:02,259 --> 00:20:04,320",arabic:"فِي ظُلْمَةِ الطَّرِيقِ.",segs:null,full_uz:"Yo‘l qorong‘iligida.",note:null},
{num:244,time:"00:20:04,320 --> 00:20:07,960",arabic:"غَيْرَ آبِهَةٍ بِحَرِّ الصَّيْفِ أَوْ بَرْدِ الشِّتَاءِ.",segs:[{ar:"غَيْرَ آبِهَةٍ",uz:"parvo qilmay"},{ar:"بِحَرِّ الصَّيْفِ",uz:"yozning issig‘iga"},{ar:"أَوْ بَرْدِ الشِّتَاءِ",uz:"yoki qishning sovug‘iga"}],full_uz:"Yozning issig‘i yoki qishning sovug‘iga parvo qilmay.",note:"آبِهٌ بِـ — «...ga e’tibor beruvchi». غَيْرَ آبِهَةٍ onaning holatini bildiradi va muannas shaklda kelgan."},
{num:245,time:"00:20:07,960 --> 00:20:12,900",arabic:"تَنْتَظِرُنِي خَارِجًا ثُمَّ تَعُودُ بِي إِلَى الْبَيْتِ.",segs:[{ar:"تَنْتَظِرُنِي خَارِجًا",uz:"meni tashqarida kutardilar"},{ar:"ثُمَّ تَعُودُ بِي",uz:"keyin meni qaytarib olib borardilar"},{ar:"إِلَى الْبَيْتِ",uz:"uyga"}],full_uz:"Meni tashqarida kutardilar, keyin uyga qaytarib olib borardilar.",note:"عَادَ بِهِ — «uni qaytarib olib keldi». خَارِجًا — «tashqarida»."},
{num:246,time:"00:20:12,900 --> 00:20:15,820",arabic:"آهِ عَلَى أُمِّي!",segs:null,full_uz:"Eh, onajonim-a!",note:"آهِ عَلَى bu yerda sog‘inch va ichki iztirobni ifodalaydi."},
{num:247,time:"00:20:15,820 --> 00:20:20,540",arabic:"وَدِدْتُ لَوْ أَنَّ اللَّهَ مَدَّ بِعُمْرِهَا لِتَرَانَا وَصَالِحًا.",segs:[{ar:"وَدِدْتُ لَوْ أَنَّ اللَّهَ",uz:"qaniydi Alloh"},{ar:"مَدَّ بِعُمْرِهَا",uz:"u kishining umrini uzaytirganida"},{ar:"لِتَرَانَا وَصَالِحًا",uz:"bizni va Solihni ko‘rishlari uchun"}],full_uz:"Qaniydi Alloh bizni va Solihni ko‘rishlari uchun u kishining umrini uzaytirganida edi.",note:"مَدَّ بِعُمْرِهِ — «umrini uzaytirdi». لِتَرَانَا — «bizni ko‘rishi uchun»."},
{num:248,time:"00:20:20,540 --> 00:20:24,880",arabic:"أُمِّي كَانَتْ أَجْمَلَ الْأُمَّهَاتِ قَلْبًا.",segs:[{ar:"أُمِّي كَانَتْ",uz:"onam edilar"},{ar:"أَجْمَلَ الْأُمَّهَاتِ قَلْبًا",uz:"qalbi eng go‘zal ona"}],full_uz:"Onam qalbi eng go‘zal ona edilar.",note:"قَلْبًا tamyiz bo‘lib, go‘zallik qaysi jihatdan ekanini bildiradi: «qalb jihatidan»."},
{num:249,time:"00:20:24,880 --> 00:20:27,660",arabic:"وَأَحَنَّ الْأُمَّهَاتِ.",segs:null,full_uz:"Va onalarning eng mehriboni edilar.",note:"أَحَنُّ — «mehribonroq, eng mehribon». Oldingi كَانَتْ ga bog‘langani uchun أَحَنَّ shaklida mansub kelgan."},
{num:250,time:"00:20:35,580 --> 00:20:39,740",arabic:"وَدِدْتُ لَوْ أَنِّي رَأَيْتُهَا وَتَعَلَّمْتُ مِنْهَا.",segs:[{ar:"وَدِدْتُ لَوْ أَنِّي رَأَيْتُهَا",uz:"qaniydi men u kishini ko‘rganimda"},{ar:"وَتَعَلَّمْتُ مِنْهَا",uz:"va u kishidan o‘rganganimda edi"}],full_uz:"Qaniydi u kishini ko‘rib, u kishidan o‘rganganimda edi.",note:null},
{num:251,time:"00:20:39,740 --> 00:20:44,859",arabic:"لَوْ رَأَيْتِهَا يَا عَبَّاسَةُ...",segs:[{ar:"لَوْ رَأَيْتِهَا",uz:"agar u kishini ko‘rganingizda"},{ar:"يَا عَبَّاسَةُ",uz:"ey Abbosa"}],full_uz:"Agar u kishini ko‘rganingizda, Abbosa...",note:"رَأَيْتِهَا dagi ـتِ ayol kishiga murojaatni, ـهَا esa ko‘rilgan ayolni bildiradi."},
{num:252,time:"00:20:44,859 --> 00:20:46,620",arabic:"لَأَحْبَبْتِهَا.",segs:null,full_uz:"U kishini yaxshi ko‘rib qolardingiz.",note:"لَـ oldingi لَوْ shartining javobini bildiradi. أَحْبَبْتِ — ayolga qaratilgan «siz yaxshi ko‘rdingiz» shakli."},
{num:253,time:"00:20:46,620 --> 00:20:53,120",arabic:"وَمَنْ يَجْرُؤُ عَلَى أَنْ يَقِفَ فِي وَجْهِ الْمُعْتَزِلَةِ يَا أَبَا نَصْرٍ؟",segs:[{ar:"وَمَنْ يَجْرُؤُ",uz:"kim jur’at qiladi"},{ar:"عَلَى أَنْ يَقِفَ",uz:"turishga"},{ar:"فِي وَجْهِ الْمُعْتَزِلَةِ",uz:"mu’taziliylarning qarshisida"},{ar:"يَا أَبَا نَصْرٍ",uz:"ey Abu Nasr"}],full_uz:"Mu’taziliylarga qarshi turishga kim jur’at qiladi, Abu Nasr?",note:"وَقَفَ فِي وَجْهِهِ — «unga qarshi turdi». So‘zma-so‘z «uning yuzi oldida turdi»."},
{num:254,time:"00:20:53,120 --> 00:20:58,240",arabic:"وَمِنْ خَلْفِهِمْ أَمِيرُ الْمُؤْمِنِينَ يَنْصُرُهُمْ وَيَبْسُطُ لَهُمُ الطَّرِيقَ.",segs:[{ar:"وَمِنْ خَلْفِهِمْ أَمِيرُ الْمُؤْمِنِينَ",uz:"ularning ortida mo‘minlar amiri turibdi"},{ar:"يَنْصُرُهُمْ",uz:"ularni qo‘llab-quvvatlaydi"},{ar:"وَيَبْسُطُ لَهُمُ الطَّرِيقَ",uz:"va ularga yo‘l ochib beradi"}],full_uz:"Ularning ortida mo‘minlar amiri turib, ularni qo‘llab-quvvatlayapti va ularga yo‘l ochib beryapti.",note:"بَسَطَ لَهُ الطَّرِيقَ — «unga yo‘lni ochdi, imkoniyat yaratdi»."},
{num:255,time:"00:20:58,240 --> 00:21:03,380",arabic:"غَفَرَ اللَّهُ لَكَ يَا أَبَا زَكَرِيَّا.",segs:[{ar:"غَفَرَ اللَّهُ لَكَ",uz:"Alloh sizni kechirsin"},{ar:"يَا أَبَا زَكَرِيَّا",uz:"ey Abu Zakariyo"}],full_uz:"Alloh sizni kechirsin, Abu Zakariyo.",note:null},
{num:256,time:"00:21:03,380 --> 00:21:05,680",arabic:"نَحْنُ مَنْ يَقِفُ لَهُمْ.",segs:[{ar:"نَحْنُ",uz:"biz"},{ar:"مَنْ يَقِفُ لَهُمْ",uz:"ularga qarshi turadiganlarmiz"}],full_uz:"Ularga qarshi turadiganlar bizmiz.",note:"مَنْ ko‘plikdagi kishilarni bildirsa ham, unga bog‘langan fe’l birlikda kelishi mumkin: يَقِفُ."},
{num:257,time:"00:21:05,680 --> 00:21:09,120",arabic:"وَنَحْنُ مَنْ يَتَصَدَّى لِبِدَعِهِمْ وَضَلَالَاتِهِمْ.",segs:[{ar:"وَنَحْنُ مَنْ يَتَصَدَّى",uz:"qarshi turadiganlar ham bizmiz"},{ar:"لِبِدَعِهِمْ وَضَلَالَاتِهِمْ",uz:"ularning bid’atlari va adashishlariga"}],full_uz:"Ularning bid’atlari va adashishlariga qarshi turadiganlar ham bizmiz.",note:"تَصَدَّى لِـ — «...ga qarshi turdi, qarshilik ko‘rsatishga kirishdi»."},
{num:258,time:"00:21:09,740 --> 00:21:16,299",arabic:"الْمُسْلِمُونَ الْآنَ أَنْظَارُهُمْ نَحْوَ الْعُلَمَاءِ مَشْدُودَةٌ.",segs:[{ar:"الْمُسْلِمُونَ الْآنَ",uz:"musulmonlar hozir"},{ar:"أَنْظَارُهُمْ",uz:"ularning nigohlari"},{ar:"نَحْوَ الْعُلَمَاءِ مَشْدُودَةٌ",uz:"olimlarga qaratilgan"}],full_uz:"Hozir musulmonlarning nigohlari olimlarga qaratilgan.",note:"مَشْدُودَةٌ — «tortilgan, mahkam qaratilgan». أَنْظَارٌ g‘ayri oqil ko‘plik bo‘lgani uchun xabari birlik muannasda kelgan."},
{num:259,time:"00:21:16,299 --> 00:21:20,039",arabic:"يَنْتَظِرُونَ مِنْهُمْ هَبَّةً فِي وَجْهِ الْبَاطِلِ.",segs:[{ar:"يَنْتَظِرُونَ مِنْهُمْ",uz:"ulardan kutishmoqda"},{ar:"هَبَّةً",uz:"qat’iy turib chiqishni"},{ar:"فِي وَجْهِ الْبَاطِلِ",uz:"botilga qarshi"}],full_uz:"Ulardan botilga qarshi qat’iy turib chiqishni kutishmoqda.",note:"هَبَّةٌ — birdan harakatga kelish, qarshi turib chiqish. هَبَّ — «qo‘zg‘aldi, shiddat bilan turdi»."},
{num:260,time:"00:21:20,039 --> 00:21:25,519",arabic:"الَّذِي عَمِلَ فِي جَسَدِ الْأُمَّةِ بَعْدَ أَنْ نَخَرَ عِظَامَهَا.",segs:[{ar:"الَّذِي عَمِلَ فِي جَسَدِ الْأُمَّةِ",uz:"ummat tanasida ta’sir ko‘rsatgan"},{ar:"بَعْدَ أَنْ نَخَرَ عِظَامَهَا",uz:"uning suyaklarini yemirganidan keyin"}],full_uz:"Ummatning suyaklarini yemirib, so‘ng tanasida ta’sir ko‘rsatgan botilga qarshi.",note:"نَخَرَ — «ichidan yemirdi, o‘ydi». الَّذِي oldingi banddagi الْبَاطِلِ so‘zini izohlaydi."},
{num:261,time:"00:21:25,519 --> 00:21:28,120",arabic:"كَانَ اللَّهُ فِي عَوْنِ الْعُلَمَاءِ يَا ابْنَ هَانِئٍ.",segs:[{ar:"كَانَ اللَّهُ فِي عَوْنِ الْعُلَمَاءِ",uz:"Alloh olimlarga yordam bersin"},{ar:"يَا ابْنَ هَانِئٍ",uz:"ey Ibn Honi’"}],full_uz:"Alloh olimlarga yordam bersin, Ibn Honi’.",note:"كَانَ اللَّهُ فِي عَوْنِهِ — shaklan o‘tgan zamonda bo‘lsa-da, «Alloh unga yordam bersin» ma’nosidagi duo."},
{num:262,time:"00:21:28,120 --> 00:21:31,539",arabic:"يَقِفُونَ فِي وَجْهِ أَهْلِ الْفِسْقِ وَالضَّلَالِ.",segs:[{ar:"يَقِفُونَ فِي وَجْهِ",uz:"qarshi turadilar"},{ar:"أَهْلِ الْفِسْقِ وَالضَّلَالِ",uz:"fisq va adashish ahliga"}],full_uz:"Fisq va adashish ahliga qarshi turadilar.",note:"وَقَفَ فِي وَجْهِ — «qarshi turdi». الْفِسْقُ — itoatdan chiqish, gunohkorlik."},
{num:263,time:"00:21:31,539 --> 00:21:35,099",arabic:"فَيَدْخُلُونَ سِجَالًا لَا مَنْجَى مِنْهُ مَعَ الْمَأْمُونِ.",segs:[{ar:"فَيَدْخُلُونَ سِجَالًا",uz:"natijada tortishuvga kirishadilar"},{ar:"لَا مَنْجَى مِنْهُ",uz:"undan qutulish yo‘li yo‘q"},{ar:"مَعَ الْمَأْمُونِ",uz:"Ma’mun bilan"}],full_uz:"Natijada Ma’mun bilan qutulish yo‘li bo‘lmagan tortishuvga kirishadilar.",note:"سِجَالٌ — o‘zaro tortishuv, bahs. مَنْجًى — qutulish joyi yoki yo‘li."},
{num:264,time:"00:21:35,099 --> 00:21:38,779",arabic:"فَتَقَعُ الْفِتْنَةُ بَيْنَ الرَّعِيَّةِ وَالرَّاعِي.",segs:[{ar:"فَتَقَعُ الْفِتْنَةُ",uz:"shunda fitna yuz beradi"},{ar:"بَيْنَ الرَّعِيَّةِ وَالرَّاعِي",uz:"xalq bilan hukmdor o‘rtasida"}],full_uz:"Shunda xalq bilan hukmdor o‘rtasida fitna yuz beradi.",note:"الرَّعِيَّةُ — boshqaruv ostidagi xalq. الرَّاعِي aslida «cho‘pon»; bu yerda xalqni boshqaruvchi hukmdor."},
{num:265,time:"00:21:38,779 --> 00:21:43,039",arabic:"هَدَى اللَّهُ الْخَلِيفَةَ الْمَأْمُونَ.",segs:[{ar:"هَدَى اللَّهُ",uz:"Alloh hidoyat qilsin"},{ar:"الْخَلِيفَةَ الْمَأْمُونَ",uz:"xalifa Ma’munni"}],full_uz:"Alloh xalifa Ma’munni hidoyat qilsin.",note:"هَدَى — يَهْدِي — «to‘g‘ri yo‘lga boshladi, boshlaydi». Bu gap duo ma’nosida."},
{num:266,time:"00:21:43,039 --> 00:21:47,680",arabic:"لَمْ يَسَعْهُ مَا وَسِعَ أَخَاهُ وَأَبَاهُ مِنْ قَبْلُ.",segs:[{ar:"لَمْ يَسَعْهُ",uz:"unga kifoya qilmadi"},{ar:"مَا وَسِعَ أَخَاهُ وَأَبَاهُ",uz:"birodari va otasiga kifoya qilgan narsa"},{ar:"مِنْ قَبْلُ",uz:"ilgari"}],full_uz:"Ilgari birodari va otasiga kifoya qilgan narsa unga kifoya qilmadi.",note:"وَسِعَ bu yerda «yetarli bo‘ldi, kifoya qildi». يَسَعُ fe’li لَمْ dan keyin يَسَعْ bo‘ladi."},
{num:267,time:"00:21:47,680 --> 00:21:51,379",arabic:"مَا انْقَطَعَ رَأْسُ أَخِيهِ...",segs:[{ar:"مَا انْقَطَعَ",uz:"kesilib ulgurmasidanoq"},{ar:"رَأْسُ أَخِيهِ",uz:"birodarining boshi"}],full_uz:"Birodarining boshi kesilib ulgurmasidanoq...",note:"Keyingi banddagi حَتَّى bilan birga voqealarning ketma-ket va juda tez yuz berganini ifodalaydi."},
{num:268,time:"00:21:51,379 --> 00:21:53,740",arabic:"حَتَّى شَمَّرَ سَاعِدَيْهِ.",segs:[{ar:"حَتَّى شَمَّرَ",uz:"darhol shimarib oldi"},{ar:"سَاعِدَيْهِ",uz:"ikki bilagini"}],full_uz:"Darhol yeng shimarib ishga kirishdi.",note:"شَمَّرَ سَاعِدَيْهِ — bilaklarini ochib, ishga hozirlanish; ko‘chma ma’noda «yeng shimarib kirishdi»."},
{num:269,time:"00:21:53,740 --> 00:21:57,180",arabic:"وَمَدَّ لِأَهْلِ الْبِدَعِ وَالضَّلَالِ يَدَيْهِ.",segs:[{ar:"وَمَدَّ",uz:"va uzatdi"},{ar:"لِأَهْلِ الْبِدَعِ وَالضَّلَالِ",uz:"bid’at va adashish ahliga"},{ar:"يَدَيْهِ",uz:"ikki qo‘lini"}],full_uz:"Va bid’at hamda adashish ahliga ikki qo‘lini uzatdi.",note:"مَدَّ لَهُ يَدَهُ — «unga qo‘l uzatdi»; bu yerda yordam va qo‘llab-quvvatlash ma’nosida."},
{num:270,time:"00:21:59,599 --> 00:22:01,639",arabic:"يَجِبُ أَنْ تَحْذَرَ.",segs:[{ar:"يَجِبُ",uz:"kerak"},{ar:"أَنْ تَحْذَرَ",uz:"ehtiyot bo‘lishingiz"}],full_uz:"Ehtiyot bo‘lishingiz kerak.",note:"حَذِرَ — «ehtiyot bo‘ldi, xavfdan saqlandi». أَنْ dan keyin تَحْذَرَ mansub kelgan."},
{num:271,time:"00:22:01,639 --> 00:22:03,519",arabic:"فَالْعُيُونُ عَلَيْكَ.",segs:null,full_uz:"Axir sizni kuzatishmoqda.",note:"الْعُيُونُ so‘zma-so‘z «ko‘zlar»; bu yerda kuzatuvchilar yoki xufiyalar nazarda tutilgan."},
{num:272,time:"00:22:03,519 --> 00:22:05,319",arabic:"لَا فَجَعَنَا اللَّهُ بِكَ.",segs:null,full_uz:"Alloh bizni sizdan ayrilish musibatiga duchor qilmasin.",note:"فَجَعَهُ بِفُلَانٍ — «uni falonchidan ayrilish qayg‘usiga soldi». لَا bilan o‘tgan zamon fe’li bu yerda duo bildiradi."},
{num:273,time:"00:22:05,319 --> 00:22:09,720",arabic:"فَجِيعَتُنَا فِي دِينِنَا وَسُنَّةِ نَبِيِّنَا يَا أَبَا زَكَرِيَّا.",segs:[{ar:"فَجِيعَتُنَا",uz:"bizning musibatimiz"},{ar:"فِي دِينِنَا وَسُنَّةِ نَبِيِّنَا",uz:"dinimiz va payg‘ambarimiz sunnatidadir"},{ar:"يَا أَبَا زَكَرِيَّا",uz:"ey Abu Zakariyo"}],full_uz:"Bizning musibatimiz dinimiz va payg‘ambarimiz sunnatiga yetgan musibatdir, Abu Zakariyo.",note:"فَجِيعَةٌ — og‘ir musibat, qattiq qayg‘u. Keyingi band bu musibatning sababini ochib beradi."},
{num:274,time:"00:22:09,720 --> 00:22:14,539",arabic:"حِينَ يُصْبِحَانِ مَرْمًى لِأَهْلِ الْبِدَعِ وَالضَّلَالَةِ.",segs:[{ar:"حِينَ يُصْبِحَانِ مَرْمًى",uz:"ikkalasi nishonga aylanganida"},{ar:"لِأَهْلِ الْبِدَعِ وَالضَّلَالَةِ",uz:"bid’at va adashish ahli uchun"}],full_uz:"Ikkalasi bid’at va adashish ahlining nishoniga aylanganida.",note:"يُصْبِحَانِ ikkilik shakli bo‘lib, din va sunnatga qaytadi. مَرْمًى — nishon, biror ta’sir qaratilgan joy."},
{num:275,time:"00:22:14,539 --> 00:22:19,439",arabic:"فِدَاهُمَا أَبِي وَأُمِّي وَكُلُّ آلِ نَصْرٍ الْخُزَاعِيِّ.",segs:[{ar:"فِدَاهُمَا",uz:"ikkalasiga fido bo‘lsin"},{ar:"أَبِي وَأُمِّي",uz:"otam va onam"},{ar:"وَكُلُّ آلِ نَصْرٍ الْخُزَاعِيِّ",uz:"va Nasr Xuzo’iyning butun xonadoni"}],full_uz:"Ikkalasiga otam, onam va Nasr Xuzo’iyning butun xonadoni fido bo‘lsin.",note:"فِدَاهُمَا dagi ـهُمَا din va sunnatga ishora qiladi. آلُ — oila, xonadon."},
{num:276,time:"00:22:19,439 --> 00:22:20,879",arabic:"لِذَا...",segs:null,full_uz:"Shu sababli...",note:null},
{num:277,time:"00:22:20,879 --> 00:22:26,359",arabic:"لَا بُدَّ مِنَ الْأَمْرِ بِالْمَعْرُوفِ وَالنَّهْيِ عَنِ الْمُنْكَرِ.",segs:[{ar:"لَا بُدَّ مِنَ",uz:"albatta kerak"},{ar:"الْأَمْرِ بِالْمَعْرُوفِ",uz:"yaxshilikka buyurish"},{ar:"وَالنَّهْيِ عَنِ الْمُنْكَرِ",uz:"va yomonlikdan qaytarish"}],full_uz:"Yaxshilikka buyurish va yomonlikdan qaytarish albatta kerak.",note:"أَمَرَ بِـ — «...ga buyurdi»; نَهَى عَنْ — «...dan qaytardi». لَا بُدَّ مِنْ zaruratni bildiradi."},
{num:278,time:"00:22:26,359 --> 00:22:39,319",arabic:"وَذُكِرَ أَنَّ سَارِقًا رُفِعَ إِلَى أَمِيرِ الْمُؤْمِنِينَ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ.",segs:[{ar:"وَذُكِرَ أَنَّ سَارِقًا",uz:"bir o‘g‘ri haqida rivoyat qilinishicha"},{ar:"رُفِعَ إِلَى أَمِيرِ الْمُؤْمِنِينَ",uz:"u mo‘minlar amirining huzuriga olib kelingan"},{ar:"عُمَرَ بْنِ الْخَطَّابِ",uz:"Umar ibn Xattobning"},{ar:"رَضِيَ اللَّهُ عَنْهُ",uz:"Alloh undan rozi bo‘lsin"}],full_uz:"Rivoyat qilinishicha, bir o‘g‘ri mo‘minlar amiri Umar ibn Xattobning huzuriga olib kelingan. Alloh undan rozi bo‘lsin.",note:"ذُكِرَ va رُفِعَ majhul nisbatda: «zikr qilindi», «olib kelindi». رُفِعَ إِلَى الْحَاكِمِ — hukm chiqarish uchun hokimga topshirildi."},
{num:279,time:"00:22:39,319 --> 00:22:40,979",arabic:"فَأَمَرَ بِقَطْعِ يَدِهِ.",segs:[{ar:"فَأَمَرَ",uz:"shunda buyurdi"},{ar:"بِقَطْعِ يَدِهِ",uz:"uning qo‘lini kesishni"}],full_uz:"Shunda uning qo‘lini kesishni buyurdi.",note:"أَمَرَ بِـ dan keyin masdar kelgan: قَطْعٌ — «kesish»."},
{num:280,time:"00:22:40,979 --> 00:22:44,339",arabic:"فَقَالَ السَّارِقُ: مَهْلًا يَا أَمِيرَ الْمُؤْمِنِينَ.",segs:[{ar:"فَقَالَ السَّارِقُ",uz:"shunda o‘g‘ri dedi"},{ar:"مَهْلًا",uz:"shoshmang"},{ar:"يَا أَمِيرَ الْمُؤْمِنِينَ",uz:"ey mo‘minlar amiri"}],full_uz:"Shunda o‘g‘ri: «Shoshmang, ey mo‘minlar amiri», dedi.",note:"مَهْلًا — «shoshmang, biroz to‘xtang» ma’nosida buyruq o‘rnida ishlatiladigan masdar."},
{num:281,time:"00:22:44,339 --> 00:22:46,799",arabic:"وَاللَّهِ مَا سَرَقْتُ إِلَّا بِقَدَرِ اللَّهِ.",segs:[{ar:"وَاللَّهِ",uz:"Allohga qasam"},{ar:"مَا سَرَقْتُ إِلَّا",uz:"men faqat ...bilan o‘g‘rilik qildim"},{ar:"بِقَدَرِ اللَّهِ",uz:"Allohning taqdiri bilan"}],full_uz:"Allohga qasam, men faqat Allohning taqdiri bilan o‘g‘rilik qildim.",note:"وَاللَّهِ dagi وَ qasam yuklamasi. قَدَرٌ — taqdir."},
{num:282,time:"00:22:46,799 --> 00:22:48,779",arabic:"وَهَذَا جَوَابٌ صَحِيحٌ.",segs:null,full_uz:"Bu esa to‘g‘ri javob.",note:null},
{num:283,time:"00:22:48,779 --> 00:22:53,299",arabic:"فَقَالَ عُمَرُ: وَنَحْنُ لَا نَقْطَعُ يَدَكَ إِلَّا بِقَدَرِ اللَّهِ.",segs:[{ar:"فَقَالَ عُمَرُ",uz:"shunda Umar dedi"},{ar:"وَنَحْنُ لَا نَقْطَعُ يَدَكَ إِلَّا",uz:"biz ham qo‘lingizni faqat ...bilan kesamiz"},{ar:"بِقَدَرِ اللَّهِ",uz:"Allohning taqdiri bilan"}],full_uz:"Shunda Umar: «Biz ham qo‘lingizni faqat Allohning taqdiri bilan kesamiz», dedi.",note:"نَحْنُ — «biz». لَا ... إِلَّا tuzilishi «faqat ...» ma’nosini beradi."},
{num:284,time:"00:22:53,299 --> 00:22:55,779",arabic:"فَغَلَبَهُ عُمَرُ رَضِيَ اللَّهُ عَنْهُ.",segs:[{ar:"فَغَلَبَهُ عُمَرُ",uz:"shu tariqa Umar uni yengdi"},{ar:"رَضِيَ اللَّهُ عَنْهُ",uz:"Alloh undan rozi bo‘lsin"}],full_uz:"Shu tariqa Umar uni bahsda yengdi. Alloh undan rozi bo‘lsin.",note:"غَلَبَهُ bu yerda jismoniy emas, dalil bilan bahsda yengishni anglatadi."},
{num:285,time:"00:22:56,359 --> 00:22:58,219",arabic:"فَالسَّارِقُ سَرَقَ بِقَدَرِ اللَّهِ.",segs:[{ar:"فَالسَّارِقُ سَرَقَ",uz:"demak, o‘g‘ri o‘g‘rilik qildi"},{ar:"بِقَدَرِ اللَّهِ",uz:"Allohning taqdiri bilan"}],full_uz:"Demak, o‘g‘ri Allohning taqdiri bilan o‘g‘rilik qildi.",note:null},
{num:286,time:"00:22:58,219 --> 00:23:00,379",arabic:"لَكِنْ لَمْ يَسْرِقْ بِشَرْعِ اللَّهِ.",segs:[{ar:"لَكِنْ لَمْ يَسْرِقْ",uz:"lekin o‘g‘rilik qilmadi"},{ar:"بِشَرْعِ اللَّهِ",uz:"Allohning shariatiga muvofiq"}],full_uz:"Lekin u Allohning shariatiga muvofiq o‘g‘rilik qilgani yo‘q.",note:"شَرْعٌ — shariat, diniy hukmlar. Gapda taqdirda yuz berish bilan shariatda ruxsat etilish farqlanmoqda."},
{num:287,time:"00:23:00,379 --> 00:23:04,279",arabic:"فَتَبَيَّنَ أَنَّ الِاحْتِجَاجَ بِالْقَدَرِ عَلَى الْمَعَاصِي بَاطِلٌ.",segs:[{ar:"فَتَبَيَّنَ أَنَّ",uz:"shunday qilib, aniq bo‘ldiki"},{ar:"الِاحْتِجَاجَ بِالْقَدَرِ",uz:"taqdirni dalil qilish"},{ar:"عَلَى الْمَعَاصِي",uz:"gunohlarni oqlash uchun"},{ar:"بَاطِلٌ",uz:"asossizdir"}],full_uz:"Shunday qilib, gunohlarni oqlash uchun taqdirni dalil qilish asossiz ekanligi aniq bo‘ldi.",note:"اِحْتَجَّ بِـ — «...ni dalil qilib keltirdi». مَعَاصٍ — مَعْصِيَةٌ («gunoh, itoatsizlik»)ning ko‘pligi."},
{num:288,time:"00:23:04,279 --> 00:23:08,779",arabic:"وَالِاحْتِجَاجُ عَلَى فَوَاتِ الْمَطْلُوبِ بَاطِلٌ أَيْضًا.",segs:[{ar:"وَالِاحْتِجَاجُ",uz:"va dalil keltirish"},{ar:"عَلَى فَوَاتِ الْمَطْلُوبِ",uz:"ko‘zlangan narsani boy berishga"},{ar:"بَاطِلٌ أَيْضًا",uz:"ham asossizdir"}],full_uz:"Ko‘zlangan narsani boy berishga buni dalil qilish ham asossizdir.",note:"فَوَاتٌ — qo‘ldan chiqish, erisholmay qolish. الْمَطْلُوبُ — talab qilingan yoki ko‘zlangan narsa."},
{num:289,time:"00:23:08,779 --> 00:23:12,259",arabic:"اِقْرَؤُوا الْقُرْآنَ الْكَرِيمَ جَيِّدًا.",segs:[{ar:"اِقْرَؤُوا الْقُرْآنَ الْكَرِيمَ",uz:"Qur’oni karimni o‘qing"},{ar:"جَيِّدًا",uz:"yaxshilab"}],full_uz:"Qur’oni karimni yaxshilab o‘qing.",note:"اِقْرَؤُوا — ko‘plik buyruq shakli. جَيِّدًا o‘qishning qanday bajarilishini bildiradi."},
{num:290,time:"00:23:12,259 --> 00:23:15,740",arabic:"اِفْهَمُوا مَقَاصِدَ آيَاتِهِ.",segs:[{ar:"اِفْهَمُوا",uz:"tushuning"},{ar:"مَقَاصِدَ آيَاتِهِ",uz:"uning oyatlaridagi maqsadlarni"}],full_uz:"Uning oyatlaridagi maqsadlarni tushuning.",note:"مَقَاصِدُ — مَقْصِدٌ («maqsad, ko‘zlangan ma’no»)ning ko‘pligi."},
{num:291,time:"00:23:15,740 --> 00:23:21,619",arabic:"اِفْهَمُوا مَرَامِيَ جُمَلِهِ وَكَلِمَاتِهِ.",segs:[{ar:"اِفْهَمُوا مَرَامِيَ",uz:"ko‘zlangan ma’nolarni tushuning"},{ar:"جُمَلِهِ وَكَلِمَاتِهِ",uz:"uning jumlalari va so‘zlarining"}],full_uz:"Uning jumlalari va so‘zlaridan ko‘zlangan ma’nolarni tushuning.",note:"مَرَامٍ — مَرْمًى so‘zining ko‘pligi; bu yerda «ko‘zlangan maqsadlar, ma’nolar». جُمَلٌ — جُمْلَةٌ ning ko‘pligi."},
{num:292,time:"00:23:21,619 --> 00:23:26,339",arabic:"حَتَّى تَتَبَيَّنُوا صِدْقَ قَوْلِنَا فِي خَلْقِ الْقُرْآنِ.",segs:[{ar:"حَتَّى تَتَبَيَّنُوا",uz:"shunda aniq bilib olishingiz uchun"},{ar:"صِدْقَ قَوْلِنَا",uz:"gapimizning to‘g‘riligini"},{ar:"فِي خَلْقِ الْقُرْآنِ",uz:"Qur’onning yaratilganligi haqida"}],full_uz:"Shunda Qur’onning yaratilganligi haqidagi gapimizning to‘g‘riligini aniq bilib olasiz.",note:"تَبَيَّنَ الشَّيْءَ — «bir narsani aniqlab bildi». حَتَّى dan keyin تَتَبَيَّنُونَ fe’lining nuni tushadi."},
{num:293,time:"00:23:26,339 --> 00:23:30,039",arabic:"وَكَلَامُنَا هَذَا أَيُّهَا الْإِخْوَةُ...",segs:[{ar:"وَكَلَامُنَا هَذَا",uz:"bizning bu gapimiz"},{ar:"أَيُّهَا الْإِخْوَةُ",uz:"ey birodarlar"}],full_uz:"Bizning bu gapimiz, ey birodarlar...",note:null},
{num:294,time:"00:23:30,039 --> 00:23:34,319",arabic:"مُؤَيَّدٌ مِنَ الْقُرْآنِ ذَاتِهِ.",segs:[{ar:"مُؤَيَّدٌ",uz:"tasdiqlangan"},{ar:"مِنَ الْقُرْآنِ ذَاتِهِ",uz:"Qur’onning o‘zi bilan"}],full_uz:"Qur’onning o‘zi bilan tasdiqlangan.",note:"مُؤَيَّدٌ — أَيَّدَ («qo‘llab-quvvatladi, tasdiqladi») fe’lining ismi maf’uli. ذَاتِهِ — «uning o‘zi»."},
{num:295,time:"00:23:34,319 --> 00:23:37,519",arabic:"وَمِنْ سُنَّةِ النَّبِيِّ نَفْسِهَا.",segs:[{ar:"وَمِنْ سُنَّةِ النَّبِيِّ",uz:"va Payg‘ambar sunnati bilan"},{ar:"نَفْسِهَا",uz:"uning o‘zi bilan"}],full_uz:"Va Payg‘ambar sunnatining o‘zi bilan.",note:"نَفْسِهَا ta’kid bo‘lib, سُنَّةِ so‘ziga qaytadi; shu sababli ـهَا muannas olmoshi ishlatilgan."},
{num:296,time:"00:23:37,519 --> 00:23:42,659",arabic:"فَنَحْنُ لَا نَأْتِي بِالْكَلَامِ مِنْ عِنْدِ أَنْفُسِنَا.",segs:[{ar:"فَنَحْنُ لَا نَأْتِي بِالْكَلَامِ",uz:"biz gapni keltirmaymiz"},{ar:"مِنْ عِنْدِ أَنْفُسِنَا",uz:"o‘zimizdan chiqarib"}],full_uz:"Biz gapni o‘zimizdan chiqarib aytmaymiz.",note:"أَتَى بِـ — «olib keldi, keltirdi». مِنْ عِنْدِ أَنْفُسِنَا — «o‘zimizdan, o‘zimiz to‘qib»."},
{num:297,time:"00:23:42,659 --> 00:23:45,639",arabic:"كَمَا يَفْعَلُ أَهْلُ الضَّلَالِ وَالْبِدَعِ.",segs:[{ar:"كَمَا يَفْعَلُ",uz:"qilganidek"},{ar:"أَهْلُ الضَّلَالِ وَالْبِدَعِ",uz:"adashish va bid’at ahli"}],full_uz:"Adashish va bid’at ahli qilganidek.",note:null},
{num:298,time:"00:23:45,639 --> 00:23:50,059",arabic:"وَلَا نَأْتِي بِالْكَلَامِ جُزَافًا كَمَنْ فَقَدَ عَقْلَهُ.",segs:[{ar:"وَلَا نَأْتِي بِالْكَلَامِ جُزَافًا",uz:"gapni o‘ylamay-netmay aytmaymiz"},{ar:"كَمَنْ فَقَدَ عَقْلَهُ",uz:"aqlini yo‘qotgan kishidek"}],full_uz:"Aqlini yo‘qotgan kishidek o‘ylamay-netmay gapirmaymiz.",note:"جُزَافًا — hisob-kitobsiz, tekshirmasdan, tavakkaliga. فَقَدَ عَقْلَهُ — «aqlini yo‘qotdi»."},
{num:299,time:"00:23:50,059 --> 00:23:57,679",arabic:"وَكَذَلِكَ قَوْلُنَا فِي الْقَدَرِ.",segs:[{ar:"وَكَذَلِكَ قَوْلُنَا",uz:"bizning gapimiz ham shunday"},{ar:"فِي الْقَدَرِ",uz:"taqdir haqida"}],full_uz:"Taqdir haqidagi gapimiz ham shunday.",note:null},
{num:300,time:"00:23:57,679 --> 00:24:04,339",arabic:"وَاعْتِقَادُنَا فِي أَنَّ أَفْعَالَ النَّاسِ لَمْ يَخْلُقْهَا اللَّهُ.",segs:[{ar:"وَاعْتِقَادُنَا فِي أَنَّ",uz:"va ...ekaniga bo‘lgan e’tiqodimiz"},{ar:"أَفْعَالَ النَّاسِ",uz:"odamlarning amallarini"},{ar:"لَمْ يَخْلُقْهَا اللَّهُ",uz:"Alloh yaratmagan"}],full_uz:"Va odamlarning amallarini Alloh yaratmagan degan e’tiqodimiz.",note:"أَفْعَالٌ — فِعْلٌ ning ko‘pligi. لَمْ يَخْلُقْهَا dagi ـهَا g‘ayri oqil ko‘plik bo‘lgan أَفْعَالَ ga qaytadi."},
{num:301,time:"00:24:04,339 --> 00:24:08,339",arabic:"بَلْ هِيَ مِنْ خَلْقِ الْإِنْسَانِ نَفْسِهِ.",segs:[{ar:"بَلْ هِيَ",uz:"balki ular"},{ar:"مِنْ خَلْقِ الْإِنْسَانِ نَفْسِهِ",uz:"insonning o‘zi yaratgan narsalardir"}],full_uz:"Balki ularni insonning o‘zi yaratgan.",note:"نَفْسِهِ so‘zi الْإِنْسَانِ ni ta’kidlaydi: «insonning aynan o‘zi»."},
{num:302,time:"00:24:08,339 --> 00:24:13,519",arabic:"هَذِهِ الِاعْتِقَادَاتُ هِيَ اعْتِقَادَاتُ حَقٍّ.",segs:[{ar:"هَذِهِ الِاعْتِقَادَاتُ",uz:"bu e’tiqodlar"},{ar:"هِيَ اعْتِقَادَاتُ حَقٍّ",uz:"haq e’tiqodlardir"}],full_uz:"Bu e’tiqodlar haq e’tiqodlardir.",note:"هِـيَ ta’kidlovchi ajratuvchi olmosh sifatida kelgan. هَذِهِ g‘ayri oqil ko‘plikka ishora qiladi."},
{num:303,time:"00:24:13,519 --> 00:24:17,119",arabic:"دَلَّ عَلَيْهَا الْعَقْلُ السَّلِيمُ.",segs:[{ar:"دَلَّ عَلَيْهَا",uz:"ularga dalolat qildi"},{ar:"الْعَقْلُ السَّلِيمُ",uz:"sog‘lom aql"}],full_uz:"Ularga sog‘lom aql dalolat qildi.",note:"دَلَّ عَلَى — «...ga dalolat qildi, ...ni ko‘rsatdi». الْعَقْلُ السَّلِيمُ — «sog‘lom aql»."},
{num:304,time:"00:24:17,119 --> 00:24:20,199",arabic:"وَأَيَّدْنَاهَا بِالذِّكْرِ الْحَكِيمِ.",segs:[{ar:"وَأَيَّدْنَاهَا",uz:"va ularni tasdiqladik"},{ar:"بِالذِّكْرِ الْحَكِيمِ",uz:"hikmatli Zikr bilan"}],full_uz:"Va ularni hikmatli Zikr bilan tasdiqladik.",note:"الذِّكْرُ الْحَكِيمُ bu yerda Qur’onni anglatadi. أَيَّدَ بِـ — «...bilan quvvatladi, tasdiqladi»."},
{num:305,time:"00:24:20,199 --> 00:24:25,759",arabic:"فَلَا يَغُرَّنَّكُمْ حَدِيثُ الْجَهَلَةِ وَمَزَاعِمُ الْفَسَقَةِ.",segs:[{ar:"فَلَا يَغُرَّنَّكُمْ",uz:"sizni aslo aldamasin"},{ar:"حَدِيثُ الْجَهَلَةِ",uz:"johillarning gaplari"},{ar:"وَمَزَاعِمُ الْفَسَقَةِ",uz:"va fosiqlarning da’volari"}],full_uz:"Johillarning gaplari va fosiqlarning da’volari sizni aslo aldamasin.",note:"يَغُرَّنَّكُمْ dagi نَّ og‘ir ta’kid nuni bo‘lib, taqiqni kuchaytiradi. مَزَاعِمُ — ko‘pincha ishonchsiz yoki asossiz deb qaralgan da’volar."},
{num:306,time:"00:24:25,759 --> 00:24:36,559",arabic:"مَاذَا تَفْعَلُونَ هُنَا؟",segs:[{ar:"مَاذَا تَفْعَلُونَ",uz:"nima qilyapsizlar"},{ar:"هُنَا",uz:"bu yerda"}],full_uz:"Bu yerda nima qilyapsizlar?",note:null},
{num:307,time:"00:24:36,559 --> 00:24:38,299",arabic:"فِي الْحَقِيقَةِ يَا إِمَامُ...",segs:[{ar:"فِي الْحَقِيقَةِ",uz:"aslida"},{ar:"يَا إِمَامُ",uz:"ey imom"}],full_uz:"Aslida, imom...",note:null},
{num:308,time:"00:24:42,799 --> 00:24:46,099",arabic:"مَا وُقُوفُكُمْ هُنَاكَ؟",segs:[{ar:"مَا وُقُوفُكُمْ",uz:"turishingizning sababi nima"},{ar:"هُنَاكَ",uz:"u yerda"}],full_uz:"Nega u yerda turibsizlar?",note:"وُقُوفٌ — وَقَفَ fe’lining masdari: «turish». Savol bu yerda turishning sababini so‘ramoqda."},
{num:309,time:"00:24:46,099 --> 00:24:48,399",arabic:"أَلَمْ أَنْهَكُمْ أَنْ تَقْتَرِبُوا مِنْ هَؤُلَاءِ الْقَوْمِ؟",segs:[{ar:"أَلَمْ أَنْهَكُمْ",uz:"sizlarni qaytarmaganmidim"},{ar:"أَنْ تَقْتَرِبُوا",uz:"yaqinlashishdan"},{ar:"مِنْ هَؤُلَاءِ الْقَوْمِ",uz:"bu qavmga"}],full_uz:"Sizlarni bu qavmga yaqinlashishdan qaytarmaganmidim?",note:"أَنْهَى fe’li لَمْ dan keyin oxirgi alifini yo‘qotadi: أَنْهَ. ـكُمْ qo‘shilganda أَنْهَكُمْ bo‘ladi."},
{num:310,time:"00:24:48,399 --> 00:24:50,119",arabic:"كَانَ وُقُوفُنَا عَرَضًا يَا شَيْخُ.",segs:[{ar:"كَانَ وُقُوفُنَا عَرَضًا",uz:"to‘xtab qolishimiz tasodifan bo‘ldi"},{ar:"يَا شَيْخُ",uz:"ey ustoz"}],full_uz:"Tasodifan to‘xtab qoldik, ustoz.",note:"عَرَضًا — «tasodifan, ataylab emas»."},
{num:311,time:"00:24:50,119 --> 00:24:52,480",arabic:"عَرَضًا؟ بَلْ مَرَضًا!",segs:[{ar:"عَرَضًا",uz:"tasodifanmi"},{ar:"بَلْ مَرَضًا",uz:"yo‘q, kasallikdan"}],full_uz:"Tasodifanmi? Yo‘q, kasallikdan!",note:"عَرَضًا va مَرَضًا tovush jihatidan o‘xshashligi bilan so‘z o‘yini hosil qilgan. Javob ularning qiziqishini qoralamoqda."},
{num:312,time:"00:24:53,559 --> 00:24:54,199",arabic:"سَامِحْنَا.",segs:null,full_uz:"Bizni kechiring.",note:"سَامِحْ buyruq fe’li va ـنَا («bizni») to‘ldiruvchi olmoshidan tuzilgan."},
{num:313,time:"00:24:54,199 --> 00:24:59,439",arabic:"أَعْرِضُ عَلَيْكَ أَنْ تَتَوَلَّى الْوِزَارَةَ لِأَمِيرِ الْمُؤْمِنِينَ يَا أَبَا مَعْنٍ.",segs:[{ar:"أَعْرِضُ عَلَيْكَ",uz:"sizga taklif qilaman"},{ar:"أَنْ تَتَوَلَّى الْوِزَارَةَ",uz:"vazirlikni zimmangizga olishni"},{ar:"لِأَمِيرِ الْمُؤْمِنِينَ",uz:"mo‘minlar amiri uchun"},{ar:"يَا أَبَا مَعْنٍ",uz:"ey Abu Ma’n"}],full_uz:"Sizga mo‘minlar amirining vazirligini zimmangizga olishni taklif qilaman, Abu Ma’n.",note:"عَرَضَ عَلَيْهِ — «unga taklif qildi». تَوَلَّى الْوِزَارَةَ — «vazirlik lavozimini egalladi»."},
{num:314,time:"00:24:59,439 --> 00:25:04,099",arabic:"فَلَيْسَ هُنَاكَ أَفْضَلُ وَلَا أَعْقَلُ مِنْكَ لِمَنْصِبٍ كَهَذَا.",segs:[{ar:"فَلَيْسَ هُنَاكَ",uz:"chunki yo‘q"},{ar:"أَفْضَلُ وَلَا أَعْقَلُ مِنْكَ",uz:"sizdan yaxshiroq yoki aqlliroq kishi"},{ar:"لِمَنْصِبٍ كَهَذَا",uz:"bunday lavozim uchun"}],full_uz:"Chunki bunday lavozim uchun sizdan yaxshiroq yoki aqlliroq kishi yo‘q.",note:"أَفْضَلُ va أَعْقَلُ qiyosiy orttirma sifatlar. كَهَذَا — «bunday, shu kabi»."},
{num:315,time:"00:25:04,779 --> 00:25:11,439",arabic:"أَشْكُرُ لِأَمِيرِ الْمُؤْمِنِينَ ثِقَتَهُ وَحُسْنَ رَأْيِهِ بِخَادِمِهِ ثُمَامَةَ بْنِ الْأَشْرَسِ.",segs:[{ar:"أَشْكُرُ لِأَمِيرِ الْمُؤْمِنِينَ",uz:"mo‘minlar amiriga minnatdorlik bildiraman"},{ar:"ثِقَتَهُ وَحُسْنَ رَأْيِهِ",uz:"ishonchi va yaxshi fikri uchun"},{ar:"بِخَادِمِهِ",uz:"o‘z xizmatkori haqidagi"},{ar:"ثُمَامَةَ بْنِ الْأَشْرَسِ",uz:"Sumoma ibn Ashras"}],full_uz:"Mo‘minlar amiriga xizmatkori Sumoma ibn Ashrasga bo‘lgan ishonchi va u haqdagi yaxshi fikri uchun minnatdorlik bildiraman.",note:"حُسْنُ الرَّأْيِ بِفُلَانٍ — «falonchi haqida yaxshi fikrda bo‘lish». So‘zlovchi o‘zini uchinchi shaxsda kamtarlik bilan atamoqda."},
{num:316,time:"00:25:11,440 --> 00:25:16,759",arabic:"وَلَكِنْ إِنْ رَأَى أَمِيرُ الْمُؤْمِنِينَ أَنْ يُعْفِيَنِي مِنْ ذَلِكَ...",segs:[{ar:"وَلَكِنْ إِنْ رَأَى أَمِيرُ الْمُؤْمِنِينَ",uz:"lekin mo‘minlar amiri ma’qul ko‘rsalar"},{ar:"أَنْ يُعْفِيَنِي مِنْ ذَلِكَ",uz:"meni bundan ozod qilishni"}],full_uz:"Lekin mo‘minlar amiri meni bundan ozod qilishni ma’qul ko‘rsalar...",note:"أَعْفَى فُلَانًا مِنْ — «falonchini ...dan ozod qildi». رَأَى bu yerda «ma’qul ko‘rdi» ma’nosida."},
{num:317,time:"00:25:16,759 --> 00:25:20,440",arabic:"لِمَاذَا؟",segs:null,full_uz:"Nega?",note:null},
{num:318,time:"00:25:20,440 --> 00:25:22,440",arabic:"لِمَاذَا يَا أَبَا مَعْنٍ؟",segs:[{ar:"لِمَاذَا",uz:"nega"},{ar:"يَا أَبَا مَعْنٍ",uz:"ey Abu Ma’n"}],full_uz:"Nega, Abu Ma’n?",note:null},
{num:319,time:"00:25:23,039 --> 00:25:26,440",arabic:"أَيَرْفُضُ أَحَدٌ وِزَارَةَ أَمِيرِ الْمُؤْمِنِينَ؟",segs:[{ar:"أَيَرْفُضُ أَحَدٌ",uz:"biror kishi rad etadimi"},{ar:"وِزَارَةَ أَمِيرِ الْمُؤْمِنِينَ",uz:"mo‘minlar amirining vazirligini"}],full_uz:"Mo‘minlar amirining vazirligini biror kishi rad etadimi?",note:"أَ so‘roq yuklamasi bu yerda ajablanish ma’nosini ham bildiradi."},
{num:320,time:"00:25:27,200 --> 00:25:30,279",arabic:"إِنَّ الْأُمَرَاءَ يَتَسَابَقُونَ عَلَى مَنْصِبٍ كَهَذَا.",segs:[{ar:"إِنَّ الْأُمَرَاءَ يَتَسَابَقُونَ",uz:"amirlar o‘zaro bellashadilar"},{ar:"عَلَى مَنْصِبٍ كَهَذَا",uz:"bunday lavozim uchun"}],full_uz:"Amirlar bunday lavozim uchun o‘zaro bellashadilar.",note:"تَسَابَقَ — «bir-biridan o‘zishga intildi, bellashdi». أُمَرَاءُ — أَمِيرٌ ning ko‘pligi."},
{num:321,time:"00:25:30,279 --> 00:25:32,440",arabic:"فَلِمَ الرَّفْضُ إِذَنْ؟",segs:[{ar:"فَلِمَ الرَّفْضُ",uz:"nega rad etish"},{ar:"إِذَنْ",uz:"unday bo‘lsa"}],full_uz:"Unday bo‘lsa, nega rad etyapsiz?",note:"لِمَ — لِـ va so‘roq مَا birikmasi. Oldidan ko‘makchi kelgani uchun مَا ning alifi tushgan."},
{num:322,time:"00:25:33,180 --> 00:25:37,019",arabic:"إِنْ رَأَى أَمِيرُ الْمُؤْمِنِينَ أَنْ يُعْفِيَنِي مِنْ ذَلِكَ...",segs:[{ar:"إِنْ رَأَى أَمِيرُ الْمُؤْمِنِينَ",uz:"mo‘minlar amiri ma’qul ko‘rsalar"},{ar:"أَنْ يُعْفِيَنِي مِنْ ذَلِكَ",uz:"meni bundan ozod qilishni"}],full_uz:"Mo‘minlar amiri meni bundan ozod qilishni ma’qul ko‘rsalar...",note:null},
{num:323,time:"00:25:37,019 --> 00:25:40,740",arabic:"شَرَحْتُ لَهُ أَسْبَابِي وَبَيَّنْتُ لَهُ حُجَّتِي.",segs:[{ar:"شَرَحْتُ لَهُ أَسْبَابِي",uz:"u kishiga sabablarimni tushuntiraman"},{ar:"وَبَيَّنْتُ لَهُ حُجَّتِي",uz:"va dalilimni bayon qilaman"}],full_uz:"U kishiga sabablarimni tushuntiraman va dalilimni bayon qilaman.",note:"O‘tgan zamon shaklidagi fe’llar oldingi shartga javob bo‘lgani uchun bu yerda kelajak ma’nosida tarjima qilinadi."},
{num:324,time:"00:25:40,740 --> 00:25:45,480",arabic:"إِنِّي أَسْمَعُكَ يَا أَبَا مَعْنٍ.",segs:[{ar:"إِنِّي أَسْمَعُكَ",uz:"sizni tinglayapman"},{ar:"يَا أَبَا مَعْنٍ",uz:"ey Abu Ma’n"}],full_uz:"Sizni tinglayapman, Abu Ma’n.",note:null},
{num:325,time:"00:25:45,480 --> 00:25:50,339",arabic:"ذَلِكَ أَنِّي رَأَيْتُ أَنَّ كُلَّ مَنْ تَوَلَّى الْوِزَارَةَ يَا مَوْلَايَ...",segs:[{ar:"ذَلِكَ أَنِّي رَأَيْتُ",uz:"sababi shuki, men ko‘rdim"},{ar:"أَنَّ كُلَّ مَنْ تَوَلَّى الْوِزَارَةَ",uz:"vazirlikni egallagan har bir kishini"},{ar:"يَا مَوْلَايَ",uz:"ey hukmdorim"}],full_uz:"Sababi shuki, hukmdorim, vazirlikni egallagan har bir kishini...",note:"ذَلِكَ أَنَّ — «buning sababi shuki». تَوَلَّى vazifa yoki lavozim bilan kelganda uni zimmasiga olishni bildiradi."},
{num:326,time:"00:25:50,339 --> 00:25:52,620",arabic:"أَفْضَتْ بِهِ إِلَى الْهَلَاكِ.",segs:[{ar:"أَفْضَتْ بِهِ",uz:"uni olib borgan"},{ar:"إِلَى الْهَلَاكِ",uz:"halokatga"}],full_uz:"Vazirlik halokatga olib borganini ko‘rdim.",note:"أَفْضَى بِهِ إِلَى — «uni ...ga olib bordi, ...ga sabab bo‘ldi». Fe’lning muannas shakli الْوِزَارَةُ ga qaytadi."},
{num:327,time:"00:26:06,579 --> 00:26:08,180",arabic:"إِلَى الْهَلَاكِ؟",segs:null,full_uz:"Halokatgami?",note:null},
{num:328,time:"00:26:08,180 --> 00:26:12,259",arabic:"كَيْفَ؟",segs:null,full_uz:"Qanday qilib?",note:null},
{num:329,time:"00:26:12,259 --> 00:26:15,340",arabic:"الْعَاقِلُ مَنِ اتَّعَظَ بِغَيْرِهِ يَا أَمِيرَ الْمُؤْمِنِينَ.",segs:[{ar:"الْعَاقِلُ",uz:"oqil kishi"},{ar:"مَنِ اتَّعَظَ بِغَيْرِهِ",uz:"boshqalardan ibrat olgan kishidir"},{ar:"يَا أَمِيرَ الْمُؤْمِنِينَ",uz:"ey mo‘minlar amiri"}],full_uz:"Oqil kishi boshqalardan ibrat olgan kishidir, ey mo‘minlar amiri.",note:"اِتَّعَظَ بِـ — «...dan ibrat oldi». مَنِ dagi kasra keyingi so‘zga ulab o‘qishda ikki sukun yonma-yon kelmasligi uchun qo‘yilgan."},
{num:330,time:"00:26:15,340 --> 00:26:18,480",arabic:"وَالْأَحْمَقُ مَنِ اتَّعَظَ بِنَفْسِهِ.",segs:[{ar:"وَالْأَحْمَقُ",uz:"ahmoq esa"},{ar:"مَنِ اتَّعَظَ بِنَفْسِهِ",uz:"o‘z boshiga tushgandan ibrat olgan kishidir"}],full_uz:"Ahmoq esa o‘z boshiga tushgandan ibrat olgan kishidir.",note:"بِنَفْسِهِ — «o‘zidan»; bu yerda o‘z boshidan kechirgan oqibat orqali saboq olish nazarda tutilgan."},
{num:331,time:"00:26:18,480 --> 00:26:23,400",arabic:"ذَلِكَ أَنِّي رَأَيْتُ نِهَايَةَ وُزَرَاءِ أَبِيكَ وَأَخِيكَ رَحِمَهُمُ اللَّهُ.",segs:[{ar:"ذَلِكَ أَنِّي رَأَيْتُ",uz:"chunki men ko‘rdim"},{ar:"نِهَايَةَ وُزَرَاءِ أَبِيكَ وَأَخِيكَ",uz:"otangiz va birodaringiz vazirlarining oqibatini"},{ar:"رَحِمَهُمُ اللَّهُ",uz:"Alloh ularni rahmatiga olsin"}],full_uz:"Chunki otangiz va birodaringiz vazirlarining oqibatini ko‘rdim. Alloh ularni rahmatiga olsin.",note:"وُزَرَاءُ — وَزِيرٌ («vazir»)ning ko‘pligi. نِهَايَةٌ bu yerda umr yoki faoliyatning yakuniy oqibatini bildiradi."},
{num:332,time:"00:26:25,600 --> 00:26:29,680",arabic:"إِنِّي أُفَضِّلُ أَنْ أَعِيشَ عَلَى وَجْهِ الْأَرْضِ خَادِمًا...",segs:[{ar:"إِنِّي أُفَضِّلُ",uz:"men afzal ko‘raman"},{ar:"أَنْ أَعِيشَ",uz:"yashashni"},{ar:"عَلَى وَجْهِ الْأَرْضِ",uz:"yer yuzida"},{ar:"خَادِمًا",uz:"xizmatkor bo‘lib"}],full_uz:"Men yer yuzida xizmatkor bo‘lib yashashni afzal ko‘raman...",note:"خَادِمًا hol bo‘lib, qanday maqomda yashashni bildiradi. عَلَى وَجْهِ الْأَرْضِ — «yer yuzida»."},
{num:333,time:"00:26:29,680 --> 00:26:33,000",arabic:"مِنْ أَنْ أَسْكُنَ بَاطِنَهَا مَلِكًا.",segs:[{ar:"مِنْ أَنْ أَسْكُنَ بَاطِنَهَا",uz:"uning bag‘rida yashashdan ko‘ra"},{ar:"مَلِكًا",uz:"podshoh bo‘lib"}],full_uz:"Yer bag‘rida podshoh bo‘lib yashashdan ko‘ra.",note:"بَاطِنُ الْأَرْضِ — yerning ichi; bu yerda qabrga ishora. مَلِكٌ — «podshoh», مَلَكٌ esa «farishta»."},
{num:334,time:"00:27:03,000 --> 00:27:07,500",arabic:"قَالَ: فَكَانَ أَحَبُّهُمَا إِلَيْهِ عُمَرَ بْنَ الْخَطَّابِ.",segs:[{ar:"قَالَ",uz:"u aytdi"},{ar:"فَكَانَ أَحَبُّهُمَا إِلَيْهِ",uz:"ikkalasidan unga sevimlirog‘i edi"},{ar:"عُمَرَ بْنَ الْخَطَّابِ",uz:"Umar ibn Xattob"}],full_uz:"U aytdi: «Ikkalasidan unga sevimlirog‘i Umar ibn Xattob edi».",note:"أَحَبُّهُمَا — «ikkalasidan sevimlirog‘i». Bu tuzilishda أَحَبُّهُمَا — كَانَ ning ismi, عُمَرَ esa uning mansub xabari."},
{num:335,time:"00:27:07,500 --> 00:27:12,839",arabic:"أَحَقًّا فَعَلْتَ ذَلِكَ يَا أَبَا عَبْدِ الرَّحْمَٰنِ؟",segs:[{ar:"أَحَقًّا فَعَلْتَ ذَلِكَ",uz:"buni chindan ham qildingizmi"},{ar:"يَا أَبَا عَبْدِ الرَّحْمَٰنِ",uz:"ey Abu Abdurahmon"}],full_uz:"Buni chindan ham qildingizmi, Abu Abdurahmon?",note:"أَحَقًّا — «rostdanmi, haqiqatanmi?»; so‘roq hamzasi va حَقًّا so‘zidan tuzilgan."},
{num:336,time:"00:27:12,839 --> 00:27:20,039",arabic:"أَجَلْ، أَمْ تَظُنُّ أَنِّي سَأَتْرُكُ أَحَدَ أَبْنَائِنَا يُعَانِي الْفَاقَةَ وَالْعَوَزَ وَأَنَا أَسْتَطِيعُ نَفْعَهُ؟",segs:[{ar:"أَجَلْ",uz:"ha"},{ar:"أَمْ تَظُنُّ",uz:"yoki o‘ylaysizmi"},{ar:"أَنِّي سَأَتْرُكُ أَحَدَ أَبْنَائِنَا",uz:"safdoshlarimizdan birini tashlab qo‘yaman deb"},{ar:"يُعَانِي الْفَاقَةَ وَالْعَوَزَ",uz:"kambag‘allik va muhtojlikdan qiynalgan holda"},{ar:"وَأَنَا أَسْتَطِيعُ نَفْعَهُ",uz:"unga foyda yetkaza olishimga qaramay"}],full_uz:"Ha. Yoki unga foyda yetkaza olaturib, safdoshlarimizdan birini kambag‘allik va muhtojlikda qiynalishga tashlab qo‘yaman deb o‘ylaysizmi?",note:"الْفَاقَةُ va الْعَوَزُ — kambag‘allik, ehtiyojmandlik. أَبْنَائِنَا so‘zma-so‘z «farzandlarimiz»; bu suhbatda o‘z tarafidagi kishilar nazarda tutilgan."},
{num:337,time:"00:27:20,039 --> 00:27:23,720",arabic:"إِنَّ إِعَانَتَكَ وَمُوَاسَاتَكَ فَرْضٌ عَلَيَّ.",segs:[{ar:"إِنَّ إِعَانَتَكَ وَمُوَاسَاتَكَ",uz:"sizga yordam berish va ko‘maklashish"},{ar:"فَرْضٌ عَلَيَّ",uz:"mening zimmamdagi burchdir"}],full_uz:"Sizga yordam berish va ko‘maklashish mening zimmamdagi burchdir.",note:"مُوَاسَاةٌ — kishiga hamdard bo‘lib, moddiy yoki ma’naviy ko‘mak berish. عَلَيَّ — «mening zimmamda»."},
{num:338,time:"00:27:23,720 --> 00:27:26,140",arabic:"وَمَتَى تَرَى أَنْ أُقَابِلَ أَمِيرَ الْمُؤْمِنِينَ؟",segs:[{ar:"وَمَتَى تَرَى",uz:"qachon ma’qul deb bilasiz"},{ar:"أَنْ أُقَابِلَ أَمِيرَ الْمُؤْمِنِينَ",uz:"mo‘minlar amiri bilan uchrashishimni"}],full_uz:"Mo‘minlar amiri bilan qachon uchrashishimni ma’qul deb bilasiz?",note:"رَأَى bu yerda «fikr bildirdi, ma’qul deb bildi». قَابَلَ — «uchrashdi»."},
{num:339,time:"00:27:26,140 --> 00:27:29,880",arabic:"فِي أَيِّ وَقْتٍ تَشَاءُ، فَقَطْ قُلْ لِلْحَاجِبِ إِنَّكَ مِنْ قِبَلِي.",segs:[{ar:"فِي أَيِّ وَقْتٍ تَشَاءُ",uz:"xohlagan vaqtingizda"},{ar:"فَقَطْ قُلْ لِلْحَاجِبِ",uz:"faqat hojibga ayting"},{ar:"إِنَّكَ مِنْ قِبَلِي",uz:"men tomondan kelganingizni"}],full_uz:"Xohlagan vaqtingizda. Faqat hojibga men tomondan kelganingizni ayting.",note:"الْحَاجِبُ — hukmdor huzuriga kirishni tartibga soluvchi saroy xizmatchisi. مِنْ قِبَلِي — «men tomondan»."},
{num:340,time:"00:27:29,880 --> 00:27:33,400",arabic:"وَسَتَرَى الْحَفَاوَةَ الَّتِي سَيَلْقَاكَ بِهَا.",segs:[{ar:"وَسَتَرَى الْحَفَاوَةَ",uz:"samimiy ehtiromni ko‘rasiz"},{ar:"الَّتِي سَيَلْقَاكَ بِهَا",uz:"u sizni kutib oladigan"}],full_uz:"U sizni qanday samimiy ehtirom bilan kutib olishini ko‘rasiz.",note:"الْحَفَاوَةُ — iliq kutib olish, ehtirom ko‘rsatish. لَقِيَهُ بِحَفَاوَةٍ — «uni iliq kutib oldi»."},
{num:341,time:"00:27:33,400 --> 00:27:35,340",arabic:"جَزَاكَ اللَّهُ خَيْرًا يَا شَيْخَنَا.",segs:[{ar:"جَزَاكَ اللَّهُ خَيْرًا",uz:"Alloh sizni yaxshilik bilan mukofotlasin"},{ar:"يَا شَيْخَنَا",uz:"ey ustozimiz"}],full_uz:"Alloh sizni yaxshilik bilan mukofotlasin, ustozimiz.",note:"جَزَى — يَجْزِي — «mukofotladi, mukofotlaydi». Bu yerda duo ma’nosida."},
{num:342,time:"00:27:35,340 --> 00:27:36,680",arabic:"جَزَاكَ اللَّهُ خَيْرًا.",segs:null,full_uz:"Alloh sizni yaxshilik bilan mukofotlasin.",note:null},
{num:343,time:"00:27:36,680 --> 00:27:40,520",arabic:"وَاحْرِصْ إِنْ عَرَضَ عَلَيْكَ أَمِيرُ الْمُؤْمِنِينَ عَمَلًا...",segs:[{ar:"وَاحْرِصْ",uz:"e’tibor bering"},{ar:"إِنْ عَرَضَ عَلَيْكَ أَمِيرُ الْمُؤْمِنِينَ عَمَلًا",uz:"agar mo‘minlar amiri sizga biror ish taklif qilsa"}],full_uz:"Agar mo‘minlar amiri sizga biror ish taklif qilsa, e’tibor bering...",note:"اِحْرِصْ — «astoydil intiling, alohida e’tibor bering». Nimaga e’tibor berish keyingi bandda aytiladi."},
{num:344,time:"00:27:40,520 --> 00:27:43,420",arabic:"أَنْ يَكُونَ عَمَلًا قَرِيبًا مِنْهُ.",segs:[{ar:"أَنْ يَكُونَ عَمَلًا",uz:"u ish bo‘lishiga"},{ar:"قَرِيبًا مِنْهُ",uz:"unga yaqin"}],full_uz:"U ish amirga yaqin bo‘ladigan ish bo‘lishiga.",note:"قَرِيبًا مِنْهُ bu yerda lavozimning hukmdor bilan bevosita aloqada ishlash imkonini berishini anglatadi."},
{num:345,time:"00:27:43,420 --> 00:27:47,520",arabic:"نُرِيدُ أَنْ يَكُونَ كُلُّ مَنْ حَوْلَهُ مِنْ أَبْنَائِنَا.",segs:[{ar:"نُرِيدُ أَنْ يَكُونَ",uz:"bo‘lishini istaymiz"},{ar:"كُلُّ مَنْ حَوْلَهُ",uz:"uning atrofidagi har bir kishi"},{ar:"مِنْ أَبْنَائِنَا",uz:"safdoshlarimizdan"}],full_uz:"Uning atrofidagi har bir kishi safdoshlarimizdan bo‘lishini istaymiz.",note:"كُلُّ مَنْ — «har bir kishi, kim bo‘lsa barchasi». حَوْلَهُ — «uning atrofida»."},
{num:346,time:"00:27:47,520 --> 00:27:51,720",arabic:"لَا نُرِيدُ لِأُذُنِهِ أَنْ تَسْمَعَ مِنْ غَيْرِنَا.",segs:[{ar:"لَا نُرِيدُ لِأُذُنِهِ",uz:"uning qulog‘i uchun istamaymiz"},{ar:"أَنْ تَسْمَعَ مِنْ غَيْرِنَا",uz:"bizdan boshqalarni eshitishni"}],full_uz:"Uning qulog‘i bizdan boshqalarni eshitishini istamaymiz.",note:"أُذُنٌ muannas ot bo‘lgani uchun تَسْمَعَ fe’li muannasda kelgan. مِنْ غَيْرِنَا — «bizdan boshqalardan»."},
{num:347,time:"00:27:51,720 --> 00:27:56,020",arabic:"كَمَا لَا نُرِيدُ لِأُذُنِ غَيْرِنَا أَنْ تَسْمَعَ مِنْهُ.",segs:[{ar:"كَمَا لَا نُرِيدُ",uz:"shuningdek, istamaymiz"},{ar:"لِأُذُنِ غَيْرِنَا",uz:"bizdan boshqalarning qulog‘i"},{ar:"أَنْ تَسْمَعَ مِنْهُ",uz:"undan eshitishini"}],full_uz:"Shuningdek, bizdan boshqalarning qulog‘i undan eshitishini ham istamaymiz.",note:"كَمَا bu yerda o‘xshash yana bir fikrni qo‘shadi: «shuningdek»."},
{num:348,time:"00:27:56,020 --> 00:27:57,160",arabic:"فَهِمْتُ ذَلِكَ.",segs:null,full_uz:"Buni tushundim.",note:null},
{num:349,time:"00:27:57,160 --> 00:28:04,340",arabic:"أَمِيرُ الْمُؤْمِنِينَ، حَفِظَهُ اللَّهُ...",segs:[{ar:"أَمِيرُ الْمُؤْمِنِينَ",uz:"mo‘minlar amiri"},{ar:"حَفِظَهُ اللَّهُ",uz:"Alloh uni asrasin"}],full_uz:"Mo‘minlar amiri — Alloh uni asrasin...",note:null},
{num:350,time:"00:28:04,340 --> 00:28:06,820",arabic:"وَإِنْ كَانَ يَقِفُ إِلَى صَفِّنَا...",segs:[{ar:"وَإِنْ كَانَ يَقِفُ",uz:"garchi turgan bo‘lsa ham"},{ar:"إِلَى صَفِّنَا",uz:"bizning safimizda"}],full_uz:"Garchi bizning safimizda turgan bo‘lsa ham...",note:"وَإِنْ كَانَ bu yerda yon berish ma’nosida: «garchi ...bo‘lsa ham»."},
{num:351,time:"00:28:06,820 --> 00:28:11,860",arabic:"إِلَّا أَنَّ قُلُوبَ السَّلَاطِينِ كَسَمَاءِ الْخَرِيفِ.",segs:[{ar:"إِلَّا أَنَّ قُلُوبَ السَّلَاطِينِ",uz:"biroq sultonlarning qalblari"},{ar:"كَسَمَاءِ الْخَرِيفِ",uz:"kuz osmoniga o‘xshaydi"}],full_uz:"Biroq sultonlarning qalblari kuz osmoniga o‘xshaydi.",note:"إِلَّا أَنَّ — «biroq, ammo». كَـ o‘xshatish yuklamasi. سَلَاطِينُ — سُلْطَانٌ ning ko‘pligi."},
{num:352,time:"00:28:11,860 --> 00:28:15,820",arabic:"لَا يُعْرَفُ مَتَى تَتَلَبَّدُ بِالْغُيُومِ.",segs:[{ar:"لَا يُعْرَفُ",uz:"ma’lum emas"},{ar:"مَتَى تَتَلَبَّدُ بِالْغُيُومِ",uz:"qachon bulut bilan qoplanishi"}],full_uz:"Qachon bulut bilan qoplanishi ma’lum emas.",note:"تَلَبَّدَتِ السَّمَاءُ بِالْغُيُومِ — «osmonni quyuq bulut qopladi». يُعْرَفُ majhul nisbatda: «bilinadi»."},
{num:353,time:"00:28:15,820 --> 00:28:19,880",arabic:"سَيَرَى أَمِيرُ الْمُؤْمِنِينَ مَا يُرْضِيهِ.",segs:[{ar:"سَيَرَى أَمِيرُ الْمُؤْمِنِينَ",uz:"mo‘minlar amiri ko‘radi"},{ar:"مَا يُرْضِيهِ",uz:"uni rozi qiladigan narsani"}],full_uz:"Mo‘minlar amiri uni rozi qiladigan narsani ko‘radi.",note:"أَرْضَى — يُرْضِي — «rozi qildi, rozi qiladi». مَا يُرْضِيهِ — «uni rozi qiladigan narsa»."},
{num:354,time:"00:28:19,880 --> 00:28:23,740",arabic:"وَمَا يُرْضِيكَ يَا شَيْخُ.",segs:[{ar:"وَمَا يُرْضِيكَ",uz:"va sizni rozi qiladigan narsani"},{ar:"يَا شَيْخُ",uz:"ey ustoz"}],full_uz:"Va sizni ham rozi qiladigan narsani, ustoz.",note:null},
{num:355,time:"00:28:23,740 --> 00:28:30,420",arabic:"كَيْفَ حَالُكَ يَا حَنْبَلُ؟",segs:[{ar:"كَيْفَ حَالُكَ",uz:"ahvolingiz qanday"},{ar:"يَا حَنْبَلُ",uz:"ey Hanbal"}],full_uz:"Ahvolingiz qanday, Hanbal?",note:null},
{num:356,time:"00:28:30,420 --> 00:28:31,440",arabic:"بِخَيْرٍ يَا عَمُّ.",segs:[{ar:"بِخَيْرٍ",uz:"yaxshiman"},{ar:"يَا عَمُّ",uz:"ey amaki"}],full_uz:"Yaxshiman, amaki.",note:"يَا عَمُّ — «ey amaki». Ba’zan katta yoshli erkakka hurmat bilan murojaat qilish uchun ham ishlatiladi."},
{num:357,time:"00:28:31,440 --> 00:28:35,019",arabic:"يَا عَمُّ؟ حَنْبَلُ، قُلْ: يَا إِمَامُ.",segs:[{ar:"يَا عَمُّ",uz:"amakimi"},{ar:"حَنْبَلُ",uz:"Hanbal"},{ar:"قُلْ: يَا إِمَامُ",uz:"«ey imom» deb ayting"}],full_uz:"Amakimi? Hanbal, «ey imom» deb ayting.",note:"قُلْ — قَالَ fe’lining buyruq shakli: «ayting»."},
{num:358,time:"00:28:35,019 --> 00:28:37,500",arabic:"بَارَكَ اللَّهُ فِيكَ، وَبُورِكَ لَكَ بِهِ.",segs:[{ar:"بَارَكَ اللَّهُ فِيكَ",uz:"Alloh sizga baraka bersin"},{ar:"وَبُورِكَ لَكَ بِهِ",uz:"u siz uchun barakali bo‘lsin"}],full_uz:"Alloh sizga baraka bersin. U siz uchun barakali bo‘lsin.",note:"بُورِكَ — بَارَكَ fe’lining majhul shakli; bu yerda duo ma’nosida."},
{num:359,time:"00:28:37,500 --> 00:28:41,180",arabic:"أَعْلَمُ أَنِّي مُقَصِّرٌ فِي حَقِّكَ.",segs:[{ar:"أَعْلَمُ أَنِّي مُقَصِّرٌ",uz:"bilaman, men kamchilik qilyapman"},{ar:"فِي حَقِّكَ",uz:"sizning haqqingizni ado etishda"}],full_uz:"Sizning haqqingizni ado etishda kamchilik qilayotganimni bilaman.",note:"قَصَّرَ فِي حَقِّ فُلَانٍ — «falonchining haqqini yetarli ado etmadi». مُقَصِّرٌ — shu ishda sustlik qilgan kishi."},
{num:360,time:"00:28:41,180 --> 00:28:45,240",arabic:"وَمَعَ ذَلِكَ جِئْتُكَ بِحَنْبَلٍ، أُرِيدُهُ أَنْ يَطْلُبَ الْعِلْمَ عَلَى يَدَيْكَ.",segs:[{ar:"وَمَعَ ذَلِكَ",uz:"shunga qaramay"},{ar:"جِئْتُكَ بِحَنْبَلٍ",uz:"huzuringizga Hanbalni olib keldim"},{ar:"أُرِيدُهُ أَنْ يَطْلُبَ الْعِلْمَ",uz:"uning ilm o‘rganishini istayman"},{ar:"عَلَى يَدَيْكَ",uz:"sizning qo‘lingizda"}],full_uz:"Shunga qaramay, huzuringizga Hanbalni olib keldim. Uning sizning qo‘lingizda ilm o‘rganishini istayman.",note:"طَلَبَ الْعِلْمَ عَلَى يَدَيْ فُلَانٍ — «falonchidan ta’lim oldi». جَاءَ بِهِ — «uni olib keldi»."},
{num:361,time:"00:28:45,240 --> 00:28:47,180",arabic:"وَهُوَ رَاغِبٌ فِي ذَلِكَ أَيْضًا.",segs:[{ar:"وَهُوَ رَاغِبٌ فِي ذَلِكَ",uz:"uning o‘zi ham bunga istakmand"},{ar:"أَيْضًا",uz:"ham"}],full_uz:"Uning o‘zi ham buni istaydi.",note:"رَغِبَ فِي — «...ni istadi, ...ga qiziqdi». رَاغِبٌ — istakmand kishi."},
{num:362,time:"00:28:48,299 --> 00:28:49,660",arabic:"أَهْلًا بِابْنِ عَمِّي حَنْبَلٍ.",segs:[{ar:"أَهْلًا",uz:"xush kelibsiz"},{ar:"بِابْنِ عَمِّي حَنْبَلٍ",uz:"amakivachcham Hanbal"}],full_uz:"Xush kelibsiz, amakivachcham Hanbal.",note:"ابْنُ عَمِّي — «amakimning o‘g‘li, amakivachcham»."},
{num:363,time:"00:28:49,660 --> 00:28:52,120",arabic:"يَجِبُ أَنْ أَرُدَّ بَعْضَ جَمِيلِكَ.",segs:[{ar:"يَجِبُ أَنْ أَرُدَّ",uz:"qaytarishim kerak"},{ar:"بَعْضَ جَمِيلِكَ",uz:"yaxshiligingizning bir qismini"}],full_uz:"Yaxshiligingizning bir qismini qaytarishim kerak.",note:"رَدَّ الْجَمِيلَ — «yaxshilikni qaytardi». جَمِيلٌ bu yerda sifat emas, «yaxshilik, ezgulik» ma’nosidagi ot."},
{num:364,time:"00:28:52,120 --> 00:28:53,559",arabic:"فَلَنْ أَنْسَى فَضْلَكَ عَلَيَّ.",segs:[{ar:"فَلَنْ أَنْسَى",uz:"aslo unutmayman"},{ar:"فَضْلَكَ عَلَيَّ",uz:"menga qilgan yaxshiligingizni"}],full_uz:"Menga qilgan yaxshiligingizni aslo unutmayman.",note:"فَضْلُكَ عَلَيَّ — «menga qilgan yaxshiligingiz, mening ustimdagi haqqingiz»."},
{num:365,time:"00:28:53,559 --> 00:28:57,720",arabic:"وَأَدْعُو اللَّهَ أَنْ يَكُونَ ذُخْرًا لَكَ فِي الْأُولَى وَالْآخِرَةِ.",segs:[{ar:"وَأَدْعُو اللَّهَ",uz:"Allohdan so‘rayman"},{ar:"أَنْ يَكُونَ ذُخْرًا لَكَ",uz:"uning sizga tayanch bo‘lishini"},{ar:"فِي الْأُولَى وَالْآخِرَةِ",uz:"dunyo va oxiratda"}],full_uz:"Allohdan uning sizga dunyo va oxiratda tayanch bo‘lishini so‘rayman.",note:"ذُخْرٌ — kelajakda foydasi tegadigan boylik yoki tayanch. الْأُولَى bu yerda dunyo hayotini bildiradi."},
{num:366,time:"00:28:57,720 --> 00:28:59,700",arabic:"بَارَكَ اللَّهُ فِيكَ يَا إِمَامُ.",segs:[{ar:"بَارَكَ اللَّهُ فِيكَ",uz:"Alloh sizga baraka bersin"},{ar:"يَا إِمَامُ",uz:"ey imom"}],full_uz:"Alloh sizga baraka bersin, imom.",note:null},
{num:367,time:"00:28:59,700 --> 00:29:03,159",arabic:"كَمْ تَعِبْتَ يَا أَحْمَدُ فِي هَذِهِ السَّبِيلِ!",segs:[{ar:"كَمْ تَعِبْتَ",uz:"qanchalar mehnat chekdingiz"},{ar:"يَا أَحْمَدُ",uz:"ey Ahmad"},{ar:"فِي هَذِهِ السَّبِيلِ",uz:"bu yo‘lda"}],full_uz:"Bu yo‘lda qanchalar mehnat chekdingiz, Ahmad!",note:"كَمْ bu yerda savol emas, ko‘p mehnat qilinganini ta’kidlaydi. سَبِيلٌ muzakkar ham, muannas ham qo‘llanishi mumkin."},
{num:368,time:"00:29:03,159 --> 00:29:04,559",arabic:"سَبِيلِ الْعِلْمِ.",segs:null,full_uz:"Ilm yo‘lida.",note:"Oldingi banddagi السَّبِيلِ so‘zini izohlaydi: qanday yo‘l ekanini aniqlaydi."},
{num:369,time:"00:29:04,559 --> 00:29:08,279",arabic:"حَتَّى مَنَّ اللَّهُ عَلَيْكَ بِمَا تُرِيدُ.",segs:[{ar:"حَتَّى مَنَّ اللَّهُ عَلَيْكَ",uz:"nihoyat, Alloh sizga in’om etdi"},{ar:"بِمَا تُرِيدُ",uz:"istagan narsangizni"}],full_uz:"Nihoyat, Alloh sizga istagan narsangizni in’om etdi.",note:"مَنَّ عَلَيْهِ بِـ — «unga ...ni in’om etdi». حَتَّى bu yerda oldingi mehnatning natijasini bildiradi."},
{num:370,time:"00:29:08,279 --> 00:29:10,899",arabic:"وَمَا أَرَادَتْ لَكَ أُمُّكَ رَحِمَهَا اللَّهُ.",segs:[{ar:"وَمَا أَرَادَتْ لَكَ أُمُّكَ",uz:"va onangiz siz uchun istagan narsani"},{ar:"رَحِمَهَا اللَّهُ",uz:"Alloh u kishini rahmatiga olsin"}],full_uz:"Va onangiz siz uchun istagan narsani. Alloh u kishini rahmatiga olsin.",note:null},
{num:371,time:"00:29:15,720 --> 00:29:21,119",arabic:"وَيَبْدُو أَنَّ ابْنَ عَمِّكَ حَنْبَلًا يَقْتَفِي أَثَرَكَ.",segs:[{ar:"وَيَبْدُو أَنَّ",uz:"aftidan"},{ar:"ابْنَ عَمِّكَ حَنْبَلًا",uz:"amakivachchangiz Hanbal"},{ar:"يَقْتَفِي أَثَرَكَ",uz:"sizning izingizdan bormoqda"}],full_uz:"Aftidan, amakivachchangiz Hanbal sizning izingizdan bormoqda.",note:"اِقْتَفَى أَثَرَهُ — «uning izidan bordi, yo‘liga ergashdi»."},
{num:372,time:"00:29:21,119 --> 00:29:23,319",arabic:"وَيَتَّخِذُ مِنْكَ مَثَلًا وَقُدْوَةً.",segs:[{ar:"وَيَتَّخِذُ مِنْكَ",uz:"sizni o‘ziga olmoqda"},{ar:"مَثَلًا وَقُدْوَةً",uz:"namuna va o‘rnak qilib"}],full_uz:"Va sizni o‘ziga namuna va o‘rnak qilmoqda.",note:"اِتَّخَذَ مِنْهُ قُدْوَةً — «uni o‘ziga o‘rnak qildi». قُدْوَةٌ — ergashiladigan namuna."},
{num:373,time:"00:29:23,319 --> 00:29:27,359",arabic:"قُدْوَتُنَا جَمِيعًا فِي هَذَا الْعِلْمِ وَالْفِقْهِ...",segs:[{ar:"قُدْوَتُنَا جَمِيعًا",uz:"barchamizning o‘rnak oladigan zotimiz"},{ar:"فِي هَذَا الْعِلْمِ وَالْفِقْهِ",uz:"bu ilm va fiqhda"}],full_uz:"Bu ilm va fiqhda barchamizning o‘rnak oladigan zotimiz...",note:null},
{num:374,time:"00:29:27,359 --> 00:29:30,639",arabic:"مُحَمَّدُ بْنُ عَبْدِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.",segs:[{ar:"مُحَمَّدُ بْنُ عَبْدِ اللَّهِ",uz:"Muhammad ibn Abdullohdir"},{ar:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",uz:"Alloh u zotga salovot va salom yo‘llasin"}],full_uz:"Muhammad ibn Abdullohdir. Alloh u zotga salovot va salom yo‘llasin.",note:"Bu band oldingi banddagi قُدْوَتُنَا ning xabarini beradi."},
{num:375,time:"00:29:30,639 --> 00:29:32,399",arabic:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ.",segs:null,full_uz:"Alloh u zotga salovot va salom yo‘llasin.",note:null},
{num:376,time:"00:29:32,399 --> 00:29:35,839",arabic:"رَأَيْتُ فِي ابْنِ عَمِّكَ وَلَعًا بِالْعِلْمِ.",segs:[{ar:"رَأَيْتُ فِي ابْنِ عَمِّكَ",uz:"amakivachchangizda ko‘rdim"},{ar:"وَلَعًا بِالْعِلْمِ",uz:"ilmga kuchli qiziqishni"}],full_uz:"Amakivachchangizda ilmga kuchli qiziqishni ko‘rdim.",note:"وَلَعٌ بِـ — «...ga kuchli qiziqish, berilish»."},
{num:377,time:"00:29:35,839 --> 00:29:38,599",arabic:"فَقُلْتُ فِي نَفْسِي: مَا دَامَتْ هَذِهِ رَغْبَتَهُ...",segs:[{ar:"فَقُلْتُ فِي نَفْسِي",uz:"shunda ichimda dedim"},{ar:"مَا دَامَتْ هَذِهِ رَغْبَتَهُ",uz:"uning istagi shu ekan"}],full_uz:"Shunda ichimda: «Uning istagi shu ekan...» dedim.",note:"قَالَ فِي نَفْسِهِ — «ichida aytdi, o‘yladi». مَا دَامَ — «...ekan, ...bo‘lib turgan ekan»."},
{num:378,time:"00:29:38,599 --> 00:29:42,599",arabic:"وَشَيْخُ بَغْدَادَ ابْنُ عَمِّهِ، فَقَدْ كُفِينَا الْمَؤُونَةَ.",segs:[{ar:"وَشَيْخُ بَغْدَادَ ابْنُ عَمِّهِ",uz:"Bag‘dod shayxi esa uning amakivachchasi"},{ar:"فَقَدْ كُفِينَا الْمَؤُونَةَ",uz:"demak, tashvishimiz yengillashdi"}],full_uz:"Bag‘dod shayxi esa uning amakivachchasi, demak, tashvishimiz yengillashdi.",note:"كُفِينَا majhul nisbatda: «bizdan tashvish aritildi». الْمَؤُونَةُ — sarf-xarajat, yumush yoki tashvish."},
{num:379,time:"00:29:42,599 --> 00:29:46,599",arabic:"عَلَى الرَّحْبِ وَالسَّعَةِ بِآلِ حَنْبَلٍ جَمِيعًا.",segs:[{ar:"عَلَى الرَّحْبِ وَالسَّعَةِ",uz:"jon-u dil bilan kutib olamiz"},{ar:"بِآلِ حَنْبَلٍ جَمِيعًا",uz:"Hanbal xonadonining barchasini"}],full_uz:"Hanbal xonadonining barchasini jon-u dil bilan kutib olamiz.",note:"عَلَى الرَّحْبِ وَالسَّعَةِ — mamnuniyat bilan qabul qilishni bildiruvchi turg‘un ibora."},
{num:380,time:"00:29:46,599 --> 00:29:47,759",arabic:"وَلَكِنْ أَخْبِرْنِي يَا عَمُّ.",segs:[{ar:"وَلَكِنْ أَخْبِرْنِي",uz:"lekin menga ayting"},{ar:"يَا عَمُّ",uz:"ey amaki"}],full_uz:"Lekin menga ayting, amaki.",note:null},
{num:381,time:"00:29:47,759 --> 00:29:50,519",arabic:"هَلْ أَتَمَّ حَنْبَلٌ حِفْظَ الْقُرْآنِ الْكَرِيمِ؟",segs:[{ar:"هَلْ أَتَمَّ حَنْبَلٌ",uz:"Hanbal tugatdimi"},{ar:"حِفْظَ الْقُرْآنِ الْكَرِيمِ",uz:"Qur’oni karimni yodlashni"}],full_uz:"Hanbal Qur’oni karimni yodlashni tugatdimi?",note:"أَتَمَّ — «to‘liq yakunladi». حِفْظٌ — «yodlash, yodda saqlash»."},
{num:382,time:"00:29:50,519 --> 00:29:54,139",arabic:"فِي الْحَقِيقَةِ لَمْ يَنْتَهِ بَعْدُ حَنْبَلٌ مِنْ حِفْظِ الْقُرْآنِ.",segs:[{ar:"فِي الْحَقِيقَةِ",uz:"aslida"},{ar:"لَمْ يَنْتَهِ بَعْدُ حَنْبَلٌ",uz:"Hanbal hali tugatmagan"},{ar:"مِنْ حِفْظِ الْقُرْآنِ",uz:"Qur’onni yodlashni"}],full_uz:"Aslida, Hanbal Qur’onni yodlashni hali tugatmagan.",note:"يَنْتَهِي fe’li لَمْ dan keyin oxirgi ي ni yo‘qotadi: يَنْتَهِ. لَمْ ... بَعْدُ — «hali ...madi»."},
{num:383,time:"00:29:54,139 --> 00:29:56,019",arabic:"لَكِنَّهُ يُوشِكُ عَلَى ذَلِكَ.",segs:[{ar:"لَكِنَّهُ يُوشِكُ",uz:"lekin u yaqin turibdi"},{ar:"عَلَى ذَلِكَ",uz:"buni tugatishga"}],full_uz:"Lekin tugatishiga oz qoldi.",note:"يُوشِكُ — bir ishning sodir bo‘lishi yaqinligini bildiradi."},
{num:384,time:"00:29:56,019 --> 00:29:59,400",arabic:"أَحْسَبُ أَنَّهُ حَفِظَ عِشْرِينَ جُزْءًا مِنْهُ.",segs:[{ar:"أَحْسَبُ أَنَّهُ حَفِظَ",uz:"menimcha, u yodlagan"},{ar:"عِشْرِينَ جُزْءًا مِنْهُ",uz:"uning yigirma juzini"}],full_uz:"Menimcha, u uning yigirma juzini yodlagan.",note:"عِشْرِينَ dan keyin sanalgan narsa birlik va mansub shaklda keladi: جُزْءًا."},
{num:385,time:"00:29:59,400 --> 00:30:01,420",arabic:"بَلِ اثْنَيْنِ وَعِشْرِينَ.",segs:null,full_uz:"Yo‘q, yigirma ikkitasini.",note:"بَلْ oldingi raqamni tuzatadi. اثْنَيْنِ وَعِشْرِينَ — «yigirma ikki»ning tushum shakli; جُزْءًا mazmunan tushuniladi."},
{num:386,time:"00:30:01,420 --> 00:30:03,879",arabic:"وَدَقِيقٌ أَيْضًا.",segs:null,full_uz:"Yana aniqlikka ham e’tiborli ekan.",note:"دَقِيقٌ bu yerda ma’lumotni aniq aytadigan, tafsilotga e’tiborli kishini bildiradi."},
{num:387,time:"00:30:03,879 --> 00:30:05,480",arabic:"بَارَكَ اللَّهُ فِيكَ يَا حَنْبَلُ.",segs:[{ar:"بَارَكَ اللَّهُ فِيكَ",uz:"Alloh sizga baraka bersin"},{ar:"يَا حَنْبَلُ",uz:"ey Hanbal"}],full_uz:"Alloh sizga baraka bersin, Hanbal.",note:null},
{num:388,time:"00:30:05,480 --> 00:30:07,480",arabic:"اِسْمَعْ يَا أَخِي.",segs:[{ar:"اِسْمَعْ",uz:"eshiting"},{ar:"يَا أَخِي",uz:"ey birodarim"}],full_uz:"Eshiting, birodarim.",note:null},
{num:389,time:"00:30:07,480 --> 00:30:11,619",arabic:"حِفْظُ الْقُرْآنِ الْكَرِيمِ مُقَدَّمٌ عَلَى حِفْظِ الْحَدِيثِ الشَّرِيفِ.",segs:[{ar:"حِفْظُ الْقُرْآنِ الْكَرِيمِ",uz:"Qur’oni karimni yodlash"},{ar:"مُقَدَّمٌ",uz:"oldin qo‘yiladi"},{ar:"عَلَى حِفْظِ الْحَدِيثِ الشَّرِيفِ",uz:"hadisi sharifni yodlashdan"}],full_uz:"Qur’oni karimni yodlash hadisi sharifni yodlashdan oldin qo‘yiladi.",note:"مُقَدَّمٌ عَلَى — «...dan oldin yoki ustun qo‘yilgan». مُقَدَّمٌ — ismi maf’ul."},
{num:390,time:"00:30:11,619 --> 00:30:13,900",arabic:"فَمَتَى انْتَهَيْتَ مِنْ حِفْظِ الْقُرْآنِ الْكَرِيمِ...",segs:[{ar:"فَمَتَى انْتَهَيْتَ",uz:"qachon tugatsangiz"},{ar:"مِنْ حِفْظِ الْقُرْآنِ الْكَرِيمِ",uz:"Qur’oni karimni yodlashni"}],full_uz:"Qur’oni karimni yodlashni qachon tugatsangiz...",note:"مَتَى bu yerda so‘roq emas, shart ma’nosida: «qachon ...sangiz»."},
{num:391,time:"00:30:13,900 --> 00:30:16,259",arabic:"فَاحْمِلْ قَرَاطِيسَكَ وَاحْضُرْ إِلَى دَارِي.",segs:[{ar:"فَاحْمِلْ قَرَاطِيسَكَ",uz:"qog‘ozlaringizni oling"},{ar:"وَاحْضُرْ إِلَى دَارِي",uz:"va uyimga keling"}],full_uz:"Qog‘ozlaringizni olib, uyimga keling.",note:"قَرَاطِيسُ — قِرْطَاسٌ («yozuv qog‘ozi, varaq»)ning ko‘pligi. اِحْضُرْ — «keling, hozir bo‘ling»."},
{num:392,time:"00:30:16,259 --> 00:30:17,299",arabic:"فَأَنَا فِي انْتِظَارِكَ.",segs:null,full_uz:"Men sizni kutaman.",note:"أَنَا فِي انْتِظَارِكَ so‘zma-so‘z «men sizni kutishdaman»; «sizni kutyapman, kutaman»."},
{num:393,time:"00:30:17,299 --> 00:30:18,019",arabic:"أَفَهِمْتَ؟",segs:null,full_uz:"Tushundingizmi?",note:null},
{num:394,time:"00:30:18,440 --> 00:30:19,859",arabic:"بَارَكَ اللَّهُ فِيكَ.",segs:null,full_uz:"Alloh sizga baraka bersin.",note:null},
{num:395,time:"00:30:49,859 --> 00:30:53,799",arabic:"مَنْ هَذَا الرَّجُلُ؟",segs:null,full_uz:"Bu kishi kim?",note:null},
{num:396,time:"00:30:53,799 --> 00:30:55,279",arabic:"إِنَّهُ الْبُهْلُولُ، أَعَزَّكَ اللَّهُ.",segs:[{ar:"إِنَّهُ الْبُهْلُولُ",uz:"u Bahlul"},{ar:"أَعَزَّكَ اللَّهُ",uz:"Alloh sizni aziz qilsin"}],full_uz:"U Bahlul, Alloh sizni aziz qilsin.",note:"أَعَزَّ — «aziz qildi, izzat berdi». أَعَزَّكَ اللَّهُ hurmat ifodalovchi duo."},
{num:397,time:"00:30:55,279 --> 00:30:58,059",arabic:"أُرِيدُ أَنْ أُكَلِّمَهُ.",segs:[{ar:"أُرِيدُ",uz:"istayman"},{ar:"أَنْ أُكَلِّمَهُ",uz:"u bilan gaplashishni"}],full_uz:"U bilan gaplashishni istayman.",note:"كَلَّمَهُ — «u bilan gaplashdi». Arabchada bevosita to‘ldiruvchi olmosh bilan keladi."},
{num:398,time:"00:30:58,059 --> 00:31:04,439",arabic:"لَا تَفْعَلْ ذَلِكَ يَا مَوْلَايَ.",segs:[{ar:"لَا تَفْعَلْ ذَلِكَ",uz:"bunday qilmang"},{ar:"يَا مَوْلَايَ",uz:"ey hukmdorim"}],full_uz:"Bunday qilmang, hukmdorim.",note:null},
{num:399,time:"00:31:06,099 --> 00:31:08,059",arabic:"لِأَنَّهُ بُهْلُولٌ.",segs:null,full_uz:"Chunki u Bahlul.",note:"Suhbatda Bahlulning nomi uning g‘ayrioddiy xatti-harakatlariga ishora sifatida ham ishlatilmoqda."},
{num:400,time:"00:31:08,059 --> 00:31:10,779",arabic:"وَمَا الضَّيْرُ فِي ذَلِكَ يَا ابْنَ أَكْثَمَ؟",segs:[{ar:"وَمَا الضَّيْرُ فِي ذَلِكَ",uz:"buning nimasi zarar"},{ar:"يَا ابْنَ أَكْثَمَ",uz:"ey Ibn Aksam"}],full_uz:"Buning nimasi zarar, Ibn Aksam?",note:"الضَّيْرُ — «zarar, ziyon». مَا الضَّيْرُ فِي ذَلِكَ؟ — «buning qanday zarari bor?»."},
{num:401,time:"00:31:10,779 --> 00:31:13,539",arabic:"مَوْلَايَ، أَنْتَ تَعْرِفُ شَطَحَاتِ الْبُهْلُولِ.",segs:[{ar:"مَوْلَايَ",uz:"hukmdorim"},{ar:"أَنْتَ تَعْرِفُ",uz:"siz bilasiz"},{ar:"شَطَحَاتِ الْبُهْلُولِ",uz:"Bahlulning g‘ayrioddiy gap-so‘zlarini"}],full_uz:"Hukmdorim, siz Bahlulning g‘ayrioddiy gap-so‘zlarini bilasiz.",note:"شَطَحَاتٌ — odatiy me’yordan chiqadigan gaplar yoki xatti-harakatlar."},
{num:402,time:"00:31:13,539 --> 00:31:16,559",arabic:"لِأَنَّنِي أَعْرِفُهَا أُرِيدُ أَنْ أُكَلِّمَهُ.",segs:[{ar:"لِأَنَّنِي أَعْرِفُهَا",uz:"ularni bilganim uchun"},{ar:"أُرِيدُ أَنْ أُكَلِّمَهُ",uz:"u bilan gaplashishni istayman"}],full_uz:"Ularni bilganim uchun u bilan gaplashishni istayman.",note:"أَعْرِفُهَا dagi ـهَا oldingi شَطَحَاتِ so‘ziga, أُكَلِّمَهُ dagi ـهُ esa Bahlulga qaytadi."},
{num:403,time:"00:31:16,559 --> 00:31:17,500",arabic:"اِتْبَعْنِي.",segs:null,full_uz:"Ortimdan yuring.",note:"تَبِعَ — يَتْبَعُ — «ergashdi». اِتْبَعْنِي — «menga ergashing»."},
{num:404,time:"00:31:17,500 --> 00:31:25,940",arabic:"السَّلَامُ عَلَيْكُمْ.",segs:null,full_uz:"Sizlarga salom bo‘lsin.",note:null},
{num:405,time:"00:31:25,940 --> 00:31:28,380",arabic:"وَعَلَيْكُمُ السَّلَامُ.",segs:null,full_uz:"Sizlarga ham salom bo‘lsin.",note:null},
{num:406,time:"00:31:28,380 --> 00:31:32,420",arabic:"أَلَكَ اسْمٌ سِوَى بُهْلُولٍ؟",segs:[{ar:"أَلَكَ اسْمٌ",uz:"ismingiz bormi"},{ar:"سِوَى بُهْلُولٍ",uz:"Bahluldan boshqa"}],full_uz:"Bahluldan boshqa ismingiz bormi?",note:"أَلَكَ — so‘roq أَ va لَكَ birikmasi. سِوَى — «...dan boshqa»."},
{num:407,time:"00:31:32,420 --> 00:31:34,700",arabic:"وَمَا يُفِيدُكَ ذَلِكَ؟",segs:null,full_uz:"Buning sizga nima foydasi bor?",note:"أَفَادَ — يُفِيدُ — «foyda berdi, foyda beradi»."},
{num:408,time:"00:31:34,700 --> 00:31:35,859",arabic:"الْحَقُّ فِيمَا تَقُولُ.",segs:null,full_uz:"Aytayotgan gapingizda haqiqat bor.",note:"فِيمَا — فِي + مَا: «...ayotgan narsada»."},
{num:409,time:"00:31:35,859 --> 00:31:40,160",arabic:"إِنَّ الْأَسْمَاءَ لَا تُفِيدُ بِقَدْرِ مَا يُفِيدُ الْمُسَمَّى.",segs:[{ar:"إِنَّ الْأَسْمَاءَ لَا تُفِيدُ",uz:"ismlar foyda bermaydi"},{ar:"بِقَدْرِ مَا يُفِيدُ الْمُسَمَّى",uz:"nom egasi foyda bergan darajada"}],full_uz:"Ismlar nom egasining o‘zi bergan darajada foyda bermaydi.",note:"الْمُسَمَّى — nomlangan kishi yoki narsa. بِقَدْرِ مَا — «...gan darajada, ...ganicha»."},
{num:410,time:"00:31:40,160 --> 00:31:46,700",arabic:"إِذَنْ فَلِمَ تَسْأَلُ عَنْ اسْمِي؟",segs:[{ar:"إِذَنْ فَلِمَ تَسْأَلُ",uz:"unday bo‘lsa, nega so‘rayapsiz"},{ar:"عَنْ اسْمِي",uz:"ismim haqida"}],full_uz:"Unday bo‘lsa, nega ismimni so‘rayapsiz?",note:"سَأَلَ عَنْ — «...haqida so‘radi». لِمَ — «nega?»."},
{num:411,time:"00:31:47,500 --> 00:31:48,799",arabic:"دَعْكَ مِمَّا لَا يُفِيدُ.",segs:[{ar:"دَعْكَ",uz:"qo‘ying"},{ar:"مِمَّا لَا يُفِيدُ",uz:"foydasi yo‘q narsalarni"}],full_uz:"Foydasi yo‘q narsalarni qo‘ying.",note:"دَعْكَ مِنْ — «...ni qo‘ying, ...bilan ovora bo‘lmang» ma’nosidagi ibora."},
{num:412,time:"00:31:48,799 --> 00:31:53,500",arabic:"كَمْ لَكَ مِنَ السِّنِينَ؟",segs:[{ar:"كَمْ لَكَ",uz:"sizda qancha bor"},{ar:"مِنَ السِّنِينَ",uz:"yillardan"}],full_uz:"Yoshingiz nechada?",note:"Savol yoshni so‘raydi, lekin so‘zma-so‘z «sizning qancha yilingiz bor?» shaklida. Keyingi javob aynan shu egalik ma’nosi ustida qurilgan."},
{num:413,time:"00:31:55,259 --> 00:31:56,500",arabic:"لَيْسَ لِي مِنَ السِّنِينَ شَيْءٌ.",segs:[{ar:"لَيْسَ لِي",uz:"menga tegishli emas"},{ar:"مِنَ السِّنِينَ شَيْءٌ",uz:"yillardan birortasi"}],full_uz:"Yillardan birortasi ham menga tegishli emas.",note:"لِي — «menga tegishli». Javob savoldagi egalik ifodasini to‘g‘ridan-to‘g‘ri ma’noda qabul qilmoqda."},
{num:414,time:"00:31:57,240 --> 00:31:58,880",arabic:"كُلُّهَا لِلَّهِ.",segs:null,full_uz:"Ularning hammasi Allohnikidir.",note:null},
{num:415,time:"00:31:58,880 --> 00:32:01,119",arabic:"أَمِيرُ الْمُؤْمِنِينَ يَقْصِدُ...",segs:[{ar:"أَمِيرُ الْمُؤْمِنِينَ",uz:"mo‘minlar amiri"},{ar:"يَقْصِدُ",uz:"nazarda tutmoqda"}],full_uz:"Mo‘minlar amiri shuni nazarda tutmoqda...",note:"قَصَدَ — «maqsad qildi, nazarda tutdi»."},
{num:416,time:"00:32:01,119 --> 00:32:02,500",arabic:"كَمْ سِنُّكَ؟",segs:null,full_uz:"Yoshingiz nechada?",note:"سِنٌّ ham «yosh», ham «tish» degani. Keyingi javob shu ikki ma’no o‘rtasidagi so‘z o‘yiniga asoslangan."},
{num:417,time:"00:32:04,980 --> 00:32:05,500",arabic:"سِنِّي؟",segs:null,full_uz:"Tishimmi?",note:"So‘zlovchi سِنٌّ ning «yosh» emas, «tish» ma’nosini tanlab javob bermoqda."},
{num:418,time:"00:32:05,500 --> 00:32:08,619",arabic:"عَظْمٌ.",segs:null,full_uz:"Suyak.",note:"Bu javob suhbatdagi so‘z o‘yinining davomi."},
{num:419,time:"00:32:08,619 --> 00:32:11,500",arabic:"فَابْنُ كَمْ أَنْتَ؟",segs:null,full_uz:"Unda necha yoshdasiz?",note:"ابْنُ كَمْ أَنْتَ؟ — yoshni so‘rash shakli; so‘zma-so‘z «siz nechaning o‘g‘lisiz?»."},
{num:420,time:"00:32:12,259 --> 00:32:13,680",arabic:"ابْنُ اثْنَيْنِ.",segs:null,full_uz:"Ikkitasining o‘g‘liman.",note:"Savoldagi ابْنُ («o‘g‘il») so‘zi yosh ma’nosida emas, qarindoshlik ma’nosida talqin qilinmoqda."},
{num:421,time:"00:32:13,680 --> 00:32:15,440",arabic:"أُمٍّ وَأَبٍ.",segs:[{ar:"أُمٍّ",uz:"bir onaning"},{ar:"وَأَبٍ",uz:"va bir otaning"}],full_uz:"Bir ona va bir otaning.",note:"Oldingi اثْنَيْنِ («ikki kishi») kimlar ekanini izohlaydi."},
{num:422,time:"00:32:15,440 --> 00:32:18,559",arabic:"كَمْ أَتَى عَلَيْكَ؟",segs:null,full_uz:"Boshingizdan qancha yil o‘tdi?",note:"أَتَى عَلَيْهِ vaqtga nisbatan «uning ustidan o‘tdi», boshqa holatda esa «uni halok qildi» ma’nosida kelishi mumkin."},
{num:423,time:"00:32:18,559 --> 00:32:21,000",arabic:"لَوْ أَتَى عَلَيَّ شَيْءٌ لَقَتَلَنِي.",segs:[{ar:"لَوْ أَتَى عَلَيَّ شَيْءٌ",uz:"agar ustimga biror narsa kelganida"},{ar:"لَقَتَلَنِي",uz:"meni o‘ldirgan bo‘lardi"}],full_uz:"Agar ustimga biror narsa kelganida, meni o‘ldirgan bo‘lardi.",note:"Javob أَتَى عَلَى iborasini vaqt o‘tishi emas, halokat yetishi ma’nosida talqin qilmoqda."},
{num:424,time:"00:32:21,000 --> 00:32:24,640",arabic:"فَكَيْفَ إِذَنْ نَقُولُ يَا بُهْلُولُ؟",segs:[{ar:"فَكَيْفَ إِذَنْ نَقُولُ",uz:"unday bo‘lsa, qanday aytaylik"},{ar:"يَا بُهْلُولُ",uz:"ey Bahlul"}],full_uz:"Unday bo‘lsa, qanday aytaylik, Bahlul?",note:null},
{num:425,time:"00:32:24,640 --> 00:32:27,220",arabic:"قُولُوا: كَمْ مَضَى مِنْ عُمْرِكَ؟",segs:[{ar:"قُولُوا",uz:"aytinglar"},{ar:"كَمْ مَضَى مِنْ عُمْرِكَ",uz:"umringizdan qanchasi o‘tdi"}],full_uz:"«Umringizdan qanchasi o‘tdi?» deb aytinglar.",note:"مَضَى — «o‘tdi». قُولُوا — قَالَ fe’lining ko‘plik buyruq shakli."},
{num:426,time:"00:32:27,220 --> 00:32:32,220",arabic:"وَأَنَا أُجِيبُ: قَدْ مَضَى الْكَثِيرُ وَلَمْ يَبْقَ إِلَّا الْقَلِيلُ.",segs:[{ar:"وَأَنَا أُجِيبُ",uz:"men esa javob beraman"},{ar:"قَدْ مَضَى الْكَثِيرُ",uz:"ko‘pi o‘tib ketdi"},{ar:"وَلَمْ يَبْقَ إِلَّا الْقَلِيلُ",uz:"faqat ozi qoldi"}],full_uz:"Men esa: «Ko‘pi o‘tib ketdi, faqat ozi qoldi», deb javob beraman.",note:"يَبْقَى fe’li لَمْ dan keyin oxirgi alifini yo‘qotadi: يَبْقَ. لَمْ ... إِلَّا — «faqat ...qoldi»."},
{num:427,time:"00:32:32,220 --> 00:32:37,220",arabic:"أَلَمْ أُخْبِرْكَ يَا مَوْلَايَ أَنْ لَا فَائِدَةَ مِنَ الْحَدِيثِ مَعَ الْبُهْلُولِ؟",segs:[{ar:"أَلَمْ أُخْبِرْكَ",uz:"sizga aytmaganmidim"},{ar:"يَا مَوْلَايَ",uz:"ey hukmdorim"},{ar:"أَنْ لَا فَائِدَةَ",uz:"foyda yo‘qligini"},{ar:"مِنَ الْحَدِيثِ مَعَ الْبُهْلُولِ",uz:"Bahlul bilan suhbatlashishdan"}],full_uz:"Bahlul bilan suhbatlashishdan foyda yo‘qligini sizga aytmaganmidim, hukmdorim?",note:"لَا فَائِدَةَ مِنْ — «...dan foyda yo‘q». الْحَدِيثُ bu yerda «suhbat, gaplashish» ma’nosida."},
{num:428,time:"00:32:37,220 --> 00:32:50,640",arabic:"كَيْفَ تَرَى أَمِيرَ الْمُؤْمِنِينَ الْمَأْمُونَ فِي عَيْنَيْكَ يَا بُهْلُولُ؟",segs:[{ar:"كَيْفَ تَرَى",uz:"qanday ko‘rasiz"},{ar:"أَمِيرَ الْمُؤْمِنِينَ الْمَأْمُونَ",uz:"mo‘minlar amiri Ma’munni"},{ar:"فِي عَيْنَيْكَ",uz:"o‘z ko‘zingizda"},{ar:"يَا بُهْلُولُ",uz:"ey Bahlul"}],full_uz:"Mo‘minlar amiri Ma’mun sizning ko‘zingizda qanday, Bahlul?",note:"فِي عَيْنَيْكَ bu yerda jismoniy ko‘rishni emas, kishining nazaridagi bahosini bildiradi."},
{num:429,time:"00:32:50,640 --> 00:32:59,200",arabic:"أَتَظُنُّ أَنَّ هَذَا الْمَأْمُونَ يَنْبُلُ فِي عَيْنَيَّ...",segs:[{ar:"أَتَظُنُّ",uz:"o‘ylaysizmi"},{ar:"أَنَّ هَذَا الْمَأْمُونَ يَنْبُلُ",uz:"bu Ma’mun ulug‘ ko‘rinadi deb"},{ar:"فِي عَيْنَيَّ",uz:"mening ko‘zimda"}],full_uz:"Bu Ma’mun mening ko‘zimda ulug‘ ko‘rinadi deb o‘ylaysizmi...",note:"نَبُلَ — يَنْبُلُ — «olijanob, ulug‘ bo‘ldi». عَيْنَيَّ — «mening ikki ko‘zim»; عَيْنَيْكَ — «sizning ikki ko‘zingiz»."},
{num:430,time:"00:32:59,200 --> 00:33:01,420",arabic:"وَقَدْ قَتَلَ أَخَاهُ؟",segs:null,full_uz:"Holbuki, u birodarini o‘ldirgan-ku?",note:"وَقَدْ + o‘tgan zamon fe’li holni bildiradi: «holbuki, ...qilgan»."},
{num:431,time:"00:33:07,220 --> 00:33:09,259",arabic:"أَمْسِ.",segs:null,full_uz:"Kecha.",note:"أَمْسِ — «kecha». Muayyan oldingi kunni bildirganda ko‘pincha kasraga mabniy keladi."},
{num:432,time:"00:34:07,220 --> 00:34:36,380",arabic:"مَا هَذَا الْبَلَاءُ الَّذِي نَزَلَ عَلَى الْمُسْلِمِينَ؟",segs:[{ar:"مَا هَذَا الْبَلَاءُ",uz:"bu qanday balo"},{ar:"الَّذِي نَزَلَ عَلَى الْمُسْلِمِينَ",uz:"musulmonlar boshiga tushgan"}],full_uz:"Musulmonlar boshiga tushgan bu qanday balo?",note:"نَزَلَ الْبَلَاءُ عَلَى — «...ning boshiga balo tushdi»."},
{num:433,time:"00:34:36,380 --> 00:34:43,000",arabic:"مَاذَا يُرِيدُ هَؤُلَاءِ الْقَوْمُ مِنَ الْخَوْضِ فِي أَحَادِيثَ لَمْ يَخُضْ فِيهَا الرَّسُولُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟",segs:[{ar:"مَاذَا يُرِيدُ هَؤُلَاءِ الْقَوْمُ",uz:"bu qavm nima istaydi"},{ar:"مِنَ الْخَوْضِ فِي أَحَادِيثَ",uz:"shunday bahslarga kirishishdan"},{ar:"لَمْ يَخُضْ فِيهَا الرَّسُولُ",uz:"Rasul kirishmagan"},{ar:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",uz:"Alloh u zotga salovot va salom yo‘llasin"}],full_uz:"Bu qavm Rasul — Alloh u zotga salovot va salom yo‘llasin — kirishmagan bahslarga kirishishdan nima istaydi?",note:"خَاضَ فِي — «...ga sho‘ng‘idi, muhokamasiga kirishdi». يَخُوضُ fe’li لَمْ dan keyin يَخُضْ bo‘ladi. أَحَادِيثَ bu yerda «gaplar, bahslar»."},
{num:434,time:"00:34:43,000 --> 00:34:45,300",arabic:"وَلَا حَتَّى صَحَابَتُهُ.",segs:null,full_uz:"Hatto u zotning sahobalari ham kirishmagan.",note:"Oldingi gapdagi لَمْ يَخُضْ ma’nosi bu bandda ham davom etadi."},
{num:435,time:"00:34:45,300 --> 00:34:54,360",arabic:"أَيُّ عَقْلٍ أَنْ تَتَحَوَّلَ رِسَالَةُ الْمُسْلِمِينَ مِنْ نَشْرِ الْإِسْلَامِ شَرْقًا وَغَرْبًا...",segs:[{ar:"أَيُّ عَقْلٍ",uz:"bu qaysi aqlga sig‘adi"},{ar:"أَنْ تَتَحَوَّلَ رِسَالَةُ الْمُسْلِمِينَ",uz:"musulmonlarning vazifasi o‘zgarishi"},{ar:"مِنْ نَشْرِ الْإِسْلَامِ",uz:"Islomni yoyishdan"},{ar:"شَرْقًا وَغَرْبًا",uz:"sharqqa va g‘arbga"}],full_uz:"Musulmonlarning vazifasi Islomni sharq va g‘arbga yoyishdan ...ga aylanishi qaysi aqlga sig‘adi?",note:"تَحَوَّلَ مِنْ ... إِلَى — «...dan ...ga aylandi». رِسَالَةٌ bu yerda «zimmasidagi vazifa, maqsad»."},
{num:436,time:"00:34:54,360 --> 00:34:56,539",arabic:"إِلَى نَشْرِ الْبِدَعِ وَالضَّلَالَاتِ بَيْنَهُمْ؟",segs:[{ar:"إِلَى نَشْرِ الْبِدَعِ وَالضَّلَالَاتِ",uz:"bid’atlar va adashishlarni yoyishga"},{ar:"بَيْنَهُمْ",uz:"o‘z oralarida"}],full_uz:"O‘z oralarida bid’atlar va adashishlarni yoyishga?",note:null},
{num:437,time:"00:34:56,539 --> 00:35:02,320",arabic:"مَاذَا يُفِيدُ الْإِسْلَامَ مِنْ كُلِّ تِلْكَ الْمَقُولَاتِ الْبَاطِلَةِ؟",segs:[{ar:"مَاذَا يُفِيدُ الْإِسْلَامَ",uz:"Islomga qanday foyda bor"},{ar:"مِنْ كُلِّ تِلْكَ الْمَقُولَاتِ الْبَاطِلَةِ",uz:"o‘sha barcha asossiz gaplardan"}],full_uz:"O‘sha barcha asossiz gaplardan Islomga qanday foyda bor?",note:"مَقُولَاتٌ — aytilgan fikrlar, da’volar. بَاطِلَةٌ — «asossiz, noto‘g‘ri»."},
{num:438,time:"00:35:02,320 --> 00:35:04,360",arabic:"وَالْفَلْسَفَاتِ الْفَارِغَةِ؟",segs:null,full_uz:"Va mazmunsiz falsafalardan?",note:"فَارِغٌ aslida «bo‘sh»; fikrga nisbatan «mazmunsiz» ma’nosida keladi."},
{num:439,time:"00:35:04,360 --> 00:35:12,360",arabic:"إِنَّ مَا يَجْنِيهِ الْمُسْلِمُونَ عَلَى دِينِهِمْ أَشَدُّ ضَرَاوَةً عَلَيْهِ مِنْ صُنْعِ أَعْدَائِهِ بِهِ.",segs:[{ar:"إِنَّ مَا يَجْنِيهِ الْمُسْلِمُونَ",uz:"musulmonlarning yetkazayotgan zarari"},{ar:"عَلَى دِينِهِمْ",uz:"o‘z dinlariga"},{ar:"أَشَدُّ ضَرَاوَةً عَلَيْهِ",uz:"unga yanada shiddatliroq zarar qiladi"},{ar:"مِنْ صُنْعِ أَعْدَائِهِ بِهِ",uz:"dushmanlarining unga qilganidan ko‘ra"}],full_uz:"Musulmonlarning o‘z dinlariga yetkazayotgan zarari unga dushmanlari yetkazayotgan zarardan ham shiddatliroqdir.",note:"جَنَى عَلَى — «...ga zarar yetkazdi, yomonlik qildi». ضَرَاوَةً tamyiz bo‘lib, shiddatning qaysi jihatini aniqlaydi."},
{num:440,time:"00:35:16,360 --> 00:35:19,360",arabic:"وَقَانَا اللَّهُ شَرَّ الْفِتَنِ.",segs:[{ar:"وَقَانَا اللَّهُ",uz:"Alloh bizni asrasin"},{ar:"شَرَّ الْفِتَنِ",uz:"fitnalarning yomonligidan"}],full_uz:"Alloh bizni fitnalarning yomonligidan asrasin.",note:"وَقَى — يَقِي — «asradi, himoya qildi». وَقَانَا dagi وَ fe’l ildizining birinchi harfi."},
{num:441,time:"00:35:26,360 --> 00:35:29,360",arabic:"أَلَمْ تَنَمْ بَعْدُ يَا أَحْمَدُ؟",segs:[{ar:"أَلَمْ تَنَمْ بَعْدُ",uz:"hali uxlamadingizmi"},{ar:"يَا أَحْمَدُ",uz:"ey Ahmad"}],full_uz:"Hali uxlamadingizmi, Ahmad?",note:"تَنَامُ fe’li لَمْ dan keyin تَنَمْ bo‘ladi. بَعْدُ inkor bilan «hali» ma’nosini beradi."},
{num:442,time:"00:35:29,360 --> 00:35:32,360",arabic:"نِمْتُ قَلِيلًا أَوَّلَ اللَّيْلِ.",segs:[{ar:"نِمْتُ قَلِيلًا",uz:"biroz uxladim"},{ar:"أَوَّلَ اللَّيْلِ",uz:"tunning boshida"}],full_uz:"Tunning boshida biroz uxladim.",note:"نَامَ fe’liga ـتُ qo‘shilganda نِمْتُ bo‘ladi: «uxladim»."},
{num:443,time:"00:35:32,360 --> 00:35:34,640",arabic:"أَنْتَ تُرْهِقُ نَفْسَكَ.",segs:null,full_uz:"Siz o‘zingizni toliqtiryapsiz.",note:"أَرْهَقَ — «juda charchatdi, toliqtirdi». نَفْسَكَ — «o‘zingizni»."},
{num:444,time:"00:35:34,640 --> 00:35:37,599",arabic:"إِنَّ لِبَدَنِكَ عَلَيْكَ حَقًّا.",segs:[{ar:"إِنَّ لِبَدَنِكَ",uz:"albatta, tanangizning bor"},{ar:"عَلَيْكَ حَقًّا",uz:"sizning zimmangizda haqqi"}],full_uz:"Albatta, tanangizning ham sizning zimmangizda haqqi bor.",note:"حَقًّا — إِنَّ ning keyinga surilgan ismi. لِبَدَنِكَ oldinga chiqqan xabar."},
{num:445,time:"00:35:37,599 --> 00:35:41,240",arabic:"وَبَدَنِي قَدْ نَالَ مِنَ الرَّاحَةِ مَا يَكْفِيهِ يَا أُمَّ صَالِحٍ.",segs:[{ar:"وَبَدَنِي قَدْ نَالَ",uz:"tanam esa oldi"},{ar:"مِنَ الرَّاحَةِ مَا يَكْفِيهِ",uz:"o‘ziga yetarli damni"},{ar:"يَا أُمَّ صَالِحٍ",uz:"ey Ummu Solih"}],full_uz:"Tanam esa o‘ziga yetarli damni oldi, Ummu Solih.",note:"مَا يَكْفِيهِ — «unga yetadigan narsa yoki miqdor». نَالَ — «oldi, erishdi»."},
{num:446,time:"00:35:41,240 --> 00:35:44,980",arabic:"مَا دَامَ اللَّهُ قَدْ مَنَّ عَلَيَّ بِالصِّحَّةِ وَالْعَافِيَةِ...",segs:[{ar:"مَا دَامَ اللَّهُ قَدْ مَنَّ عَلَيَّ",uz:"Alloh menga in’om etgan ekan"},{ar:"بِالصِّحَّةِ وَالْعَافِيَةِ",uz:"sog‘lik va omonlikni"}],full_uz:"Alloh menga sog‘lik va omonlikni in’om etgan ekan...",note:"الصِّحَّةُ — sog‘lik. الْعَافِيَةُ — kasallik va balolardan omonlik."},
{num:447,time:"00:35:44,980 --> 00:35:47,140",arabic:"فَلَا أَقَلَّ مِنْ أَنْ أَقُومَ بِحَقِّهِمَا.",segs:[{ar:"فَلَا أَقَلَّ مِنْ",uz:"hech bo‘lmaganda lozim"},{ar:"أَنْ أَقُومَ بِحَقِّهِمَا",uz:"ikkalasining haqqini ado etishim"}],full_uz:"Hech bo‘lmaganda ikkalasining haqqini ado etishim lozim.",note:"قَامَ بِحَقِّهِ — «uning haqqini ado etdi». ـهُمَا sog‘lik va omonlikka qaytadi."},
{num:448,time:"00:35:47,140 --> 00:35:51,900",arabic:"هَيَّا، دَعْكِ مِنَ الْإِشْفَاقِ عَلَيَّ وَتَوَضَّئِي لِصَلَاةِ اللَّيْلِ.",segs:[{ar:"هَيَّا",uz:"qani"},{ar:"دَعْكِ مِنَ الْإِشْفَاقِ عَلَيَّ",uz:"menga achinishni qo‘ying"},{ar:"وَتَوَضَّئِي",uz:"va tahorat oling"},{ar:"لِصَلَاةِ اللَّيْلِ",uz:"tungi namoz uchun"}],full_uz:"Qani, menga achinishni qo‘yib, tungi namoz uchun tahorat oling.",note:"تَوَضَّئِي — ayol kishiga buyruq: «tahorat oling». الْإِشْفَاقُ عَلَى — achinish, tashvishlanish."},
{num:449,time:"00:35:51,900 --> 00:35:53,680",arabic:"فَقَدْ أَشْرَفَ اللَّيْلُ عَلَى الِانْقِضَاءِ.",segs:[{ar:"فَقَدْ أَشْرَفَ اللَّيْلُ",uz:"chunki tun yaqinlashdi"},{ar:"عَلَى الِانْقِضَاءِ",uz:"tugashga"}],full_uz:"Chunki tun tugashiga oz qoldi.",note:"أَشْرَفَ عَلَى — «...ga yaqinlashdi, arafasiga yetdi». اِنْقِضَاءٌ — tugash, nihoyasiga yetish."},
{num:450,time:"00:37:02,360 --> 00:37:05,800",arabic:"فِي لِقَاءِ أَمِيرِ الْمُؤْمِنِينَ، وَأُعْجِبَ بِكَ.",segs:[{ar:"فِي لِقَاءِ أَمِيرِ الْمُؤْمِنِينَ",uz:"mo‘minlar amiri bilan uchrashuvda"},{ar:"وَأُعْجِبَ بِكَ",uz:"va siz unga ma’qul keldingiz"}],full_uz:"Mo‘minlar amiri bilan uchrashuvda... Siz unga ma’qul keldingiz.",note:"أُعْجِبَ بِفُلَانٍ — «falonchini yoqtirdi, undan yaxshi taassurot oldi»."},
{num:451,time:"00:37:05,800 --> 00:37:07,599",arabic:"أَتَعْلَمُ لِمَاذَا؟",segs:null,full_uz:"Nega ekanini bilasizmi?",note:null},
{num:452,time:"00:37:07,599 --> 00:37:08,500",arabic:"لِأَنَّكَ سَيِّدٌ.",segs:null,full_uz:"Chunki siz ulug‘ kishisiz.",note:"سَيِّدٌ — «ulug‘ kishi, yetakchi, hurmatli zot». Ma’nosi vaziyatga qarab aniqlanadi."},
{num:453,time:"00:37:08,500 --> 00:37:11,300",arabic:"سَيِّدٌ مُنْذُ وَلَدَتْكَ أُمُّكَ.",segs:[{ar:"سَيِّدٌ",uz:"ulug‘ kishisiz"},{ar:"مُنْذُ وَلَدَتْكَ أُمُّكَ",uz:"onangiz sizni dunyoga keltirganidan beri"}],full_uz:"Onangiz sizni dunyoga keltirganidan beri ulug‘ kishisiz.",note:"مُنْذُ fe’lli gap bilan kelib, vaqtning boshlanish nuqtasini bildiradi: «...ganidan beri»."},
{num:454,time:"00:37:11,300 --> 00:37:15,420",arabic:"إِنِّي أَتَحَرَّقُ شَوْقًا لِلِقَاءِ أَمِيرِ الْمُؤْمِنِينَ.",segs:[{ar:"إِنِّي أَتَحَرَّقُ شَوْقًا",uz:"men intizorlikdan yonmoqdaman"},{ar:"لِلِقَاءِ أَمِيرِ الْمُؤْمِنِينَ",uz:"mo‘minlar amiri bilan uchrashishga"}],full_uz:"Mo‘minlar amiri bilan uchrashish intizorligidan yonmoqdaman.",note:"تَحَرَّقَ شَوْقًا — «kuchli intizorlik his qildi». شَوْقًا yonishning sababini bildiradi."},
{num:455,time:"00:37:17,079 --> 00:37:22,140",arabic:"الرَّجُلِ الَّذِي لَمْ نَرَ إِلَّا فِي عَهْدِهِ الْأَمْنَ وَالطُّمَأْنِينَةَ.",segs:[{ar:"الرَّجُلِ الَّذِي",uz:"o‘sha kishining"},{ar:"لَمْ نَرَ إِلَّا فِي عَهْدِهِ",uz:"faqat uning davridagina ko‘rdik"},{ar:"الْأَمْنَ وَالطُّمَأْنِينَةَ",uz:"xavfsizlik va xotirjamlikni"}],full_uz:"Xavfsizlik va xotirjamlikni faqat uning davridagina ko‘rganimiz o‘sha kishi bilan.",note:"نَرَى fe’li لَمْ dan keyin oxirgi alifini yo‘qotadi: نَرَ. الْعَهْدُ bu yerda hukmronlik davrini bildiradi."},
{num:456,time:"00:37:22,140 --> 00:37:24,960",arabic:"وَإِنَّهُ، وَلَا أُزَكِّيهِ عَلَى اللَّهِ...",segs:[{ar:"وَإِنَّهُ",uz:"albatta, u"},{ar:"وَلَا أُزَكِّيهِ عَلَى اللَّهِ",uz:"uni Alloh oldida pok deb kafolatlamayman"}],full_uz:"Albatta, u — uni Alloh oldida pok deb kafolatlamayman...",note:"لَا أُزَكِّيهِ عَلَى اللَّهِ — kishini maqtayotganda uning asl holatini Alloh bilishini e’tirof etuvchi ibora."},
{num:457,time:"00:37:24,960 --> 00:37:27,960",arabic:"رَجُلٌ قَلَّ فِي الْخُلَفَاءِ مِثْلُهُ.",segs:[{ar:"رَجُلٌ",uz:"shunday kishiki"},{ar:"قَلَّ فِي الْخُلَفَاءِ مِثْلُهُ",uz:"xalifalar orasida unga o‘xshagani kam"}],full_uz:"Xalifalar orasida unga o‘xshagani kam bo‘lgan kishidir.",note:"قَلَّ مِثْلُهُ — «unga o‘xshagani kam uchraydi». خُلَفَاءُ — خَلِيفَةٌ ning ko‘pligi."},
{num:458,time:"00:37:27,960 --> 00:37:30,860",arabic:"هَيَّا بِنَا، لَقَدْ تَأَخَّرْنَا يَا رَجُلُ.",segs:[{ar:"هَيَّا بِنَا",uz:"qani, ketdik"},{ar:"لَقَدْ تَأَخَّرْنَا",uz:"kechikdik"},{ar:"يَا رَجُلُ",uz:"ey birodar"}],full_uz:"Qani, ketdik, kechikdik, birodar.",note:null},
{num:459,time:"00:37:30,860 --> 00:37:43,640",arabic:"وَسُؤْرُ الْكَلْبِ يَخْتَلِفُ حُكْمُهُ عَنْ سُؤْرِ الْهِرِّ.",segs:[{ar:"وَسُؤْرُ الْكَلْبِ",uz:"itdan qolgan ichimlikning"},{ar:"يَخْتَلِفُ حُكْمُهُ",uz:"hukmi farq qiladi"},{ar:"عَنْ سُؤْرِ الْهِرِّ",uz:"mushukdan qolgan ichimliknikidan"}],full_uz:"It ichganidan qolgan suyuqlikning hukmi mushuk ichganidan qolgan suyuqliknikidan farq qiladi.",note:"سُؤْرٌ — odam yoki hayvon ichganidan keyin idishda qolgan suyuqlik. الْهِرُّ — mushuk."},
{num:460,time:"00:37:43,640 --> 00:37:46,140",arabic:"فَفِي وُلُوغِ الْكَلْبِ فِي الْإِنَاءِ...",segs:[{ar:"فَفِي وُلُوغِ الْكَلْبِ",uz:"itning tili bilan ichishi haqida"},{ar:"فِي الْإِنَاءِ",uz:"idishdan"}],full_uz:"Itning idishdan tili bilan ichishi haqida...",note:"وُلُوغٌ — hayvonning tilini suyuqlikka tekkizib ichishi. الْإِنَاءُ — idish."},
{num:461,time:"00:37:46,140 --> 00:37:50,280",arabic:"رُوِيَ عَنْ أَبِي هُرَيْرَةَ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ...",segs:[{ar:"رُوِيَ عَنْ أَبِي هُرَيْرَةَ",uz:"Abu Hurayradan rivoyat qilindi"},{ar:"عَنِ النَّبِيِّ",uz:"Payg‘ambardan"},{ar:"صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ",uz:"Alloh u zotga salovot va salom yo‘llasin"},{ar:"قَالَ",uz:"u zot aytdilar"}],full_uz:"Abu Hurayradan, u esa Payg‘ambardan — Alloh u zotga salovot va salom yo‘llasin — rivoyat qilgan: u zot aytdilar...",note:"رُوِيَ — رَوَى («rivoyat qildi») fe’lining majhul shakli: «rivoyat qilindi»."},
{num:462,time:"00:37:52,079 --> 00:37:54,120",arabic:"إِذَا وَلَغَ الْكَلْبُ فِي إِنَاءٍ...",segs:[{ar:"إِذَا وَلَغَ الْكَلْبُ",uz:"agar it tili bilan ichsa"},{ar:"فِي إِنَاءٍ",uz:"bir idishdan"}],full_uz:"Agar it bir idishdan tili bilan ichsa...",note:"وَلَغَ — يَلَغُ — «tili bilan suyuqlik ichdi». إِذَا bu yerda shart ma’nosida."},
{num:463,time:"00:37:54,120 --> 00:37:57,220",arabic:"غُسِلَ سَبْعَ مَرَّاتٍ أُولَاهَا بِالتُّرَابِ.",segs:[{ar:"غُسِلَ سَبْعَ مَرَّاتٍ",uz:"u yetti marta yuviladi"},{ar:"أُولَاهَا بِالتُّرَابِ",uz:"birinchisi tuproq bilan"}],full_uz:"U yetti marta yuviladi, birinchisi tuproq bilan.",note:"غُسِلَ majhul nisbatda: «yuvildi»; shartga bog‘langani uchun bu yerda «yuviladi» deb tarjima qilinadi. أُولَاهَا — «ularning birinchisi»."},
{num:464,time:"00:37:57,220 --> 00:38:00,400",arabic:"أَمَّا سُؤْرُ الْهِرِّ فَلَا بَأْسَ بِهِ.",segs:[{ar:"أَمَّا سُؤْرُ الْهِرِّ",uz:"mushuk ichganidan qolgan suyuqlikka kelsak"},{ar:"فَلَا بَأْسَ بِهِ",uz:"unda zarar yo‘q"}],full_uz:"Mushuk ichganidan qolgan suyuqlikka kelsak, undan foydalanishda zarar yo‘q.",note:"أَمَّا ... فَـ — «...ga kelsak, ...». لَا بَأْسَ بِهِ — «zarari yo‘q, monelik yo‘q»."},
{num:465,time:"00:38:00,400 --> 00:38:03,639",arabic:"فَقَدْ قَالَ النَّبِيُّ عَنِ الْهِرَّةِ: لَيْسَتْ بِنَجَسٍ.",segs:[{ar:"فَقَدْ قَالَ النَّبِيُّ",uz:"chunki Payg‘ambar aytganlar"},{ar:"عَنِ الْهِرَّةِ",uz:"mushuk haqida"},{ar:"لَيْسَتْ بِنَجَسٍ",uz:"u najas emas"}],full_uz:"Chunki Payg‘ambar mushuk haqida: «U najas emas», deganlar.",note:"لَيْسَتْ muannas shaklda, chunki الْهِرَّةُ muannas ot. بِـ inkorni ta’kidlaydi."},
{num:466,time:"00:38:03,639 --> 00:38:06,880",arabic:"إِنَّهَا مِنَ الطَّوَّافِينَ عَلَيْكُمْ وَالطَّوَّافَاتِ.",segs:[{ar:"إِنَّهَا مِنَ",uz:"u ...lardan"},{ar:"الطَّوَّافِينَ عَلَيْكُمْ",uz:"atrofingizda ko‘p aylanib yuradigan erkak jinslilardan"},{ar:"وَالطَّوَّافَاتِ",uz:"va urg‘ochi jinslilardan"}],full_uz:"U atrofingizda ko‘p aylanib yuradigan erkak va urg‘ochi jonivorlardandir.",note:"طَوَّافٌ ko‘p aylanib yurishni bildiruvchi mubolag‘a shakli. الطَّوَّافِينَ va الطَّوَّافَاتِ erkak hamda ayol jinsidagi ko‘plik shakllaridir."},
{num:467,time:"00:38:25,760 --> 00:38:30,099",arabic:"خَادِمُكَ أَحْمَدُ بْنُ أَبِي دُؤَادٍ الْإِيَادِيُّ يَا أَمِيرَ الْمُؤْمِنِينَ.",segs:[{ar:"خَادِمُكَ",uz:"xizmatkoringiz"},{ar:"أَحْمَدُ بْنُ أَبِي دُؤَادٍ الْإِيَادِيُّ",uz:"Ahmad ibn Abu Duod Iyodiy"},{ar:"يَا أَمِيرَ الْمُؤْمِنِينَ",uz:"ey mo‘minlar amiri"}],full_uz:"Xizmatkoringiz Ahmad ibn Abu Duod Iyodiyman, ey mo‘minlar amiri.",note:"خَادِمُكَ — «sizning xizmatkoringiz». So‘zlovchi shu ifoda bilan o‘zini tanishtirmoqda."},
{num:468,time:"00:38:30,099 --> 00:38:34,819",arabic:"قَدْ أَفَاضَ قَاضِينَا يَحْيَى بْنُ أَكْثَمَ فِي الثَّنَاءِ عَلَيْكَ.",segs:[{ar:"قَدْ أَفَاضَ قَاضِينَا",uz:"qozimiz ko‘p gapirdi"},{ar:"يَحْيَى بْنُ أَكْثَمَ",uz:"Yahyo ibn Aksam"},{ar:"فِي الثَّنَاءِ عَلَيْكَ",uz:"sizni maqtashda"}],full_uz:"Qozimiz Yahyo ibn Aksam sizni juda ko‘p maqtadi.",note:"أَفَاضَ فِي الْحَدِيثِ — «batafsil, keng gapirdi». الثَّنَاءُ عَلَى — «...ni maqtash»."},
{num:469,time:"00:38:34,819 --> 00:38:48,559",arabic:"أَخْبَرَنِي ابْنُ أَكْثَمَ أَنَّكَ دَرَسْتَ الْفِقْهَ وَتَمَرَّسْتَ فِي صِنَاعَةِ الْكَلَامِ.",segs:[{ar:"أَخْبَرَنِي ابْنُ أَكْثَمَ",uz:"Ibn Aksam menga aytdi"},{ar:"أَنَّكَ دَرَسْتَ الْفِقْهَ",uz:"fiqhni o‘rganganingizni"},{ar:"وَتَمَرَّسْتَ",uz:"va mahorat orttirganingizni"},{ar:"فِي صِنَاعَةِ الْكَلَامِ",uz:"kalom ilmida"}],full_uz:"Ibn Aksam menga fiqhni o‘rganganingizni va kalom ilmida mahorat orttirganingizni aytdi.",note:"تَمَرَّسَ فِي — «...da tajriba va mahorat orttirdi». صِنَاعَةُ الْكَلَامِ bu yerda e’tiqodiy masalalarni dalillar bilan muhokama qilish ilmini bildiradi."},
{num:470,time:"00:38:48,559 --> 00:38:52,559",arabic:"فَعَلَى يَدِ مَنْ طَلَبْتَ الْفِقْهَ؟",segs:[{ar:"فَعَلَى يَدِ مَنْ",uz:"kimning qo‘lida"},{ar:"طَلَبْتَ الْفِقْهَ",uz:"fiqh o‘rgandingiz"}],full_uz:"Fiqhni kimning qo‘lida o‘rgandingiz?",note:"عَلَى يَدِ مَنْ — «kimdan ta’lim olib, kimning ustozligida»."},
{num:471,time:"00:38:52,559 --> 00:38:54,579",arabic:"بَدَأْتُ فِي طَلَبِ الْفِقْهِ يَا مَوْلَايَ...",segs:[{ar:"بَدَأْتُ فِي طَلَبِ الْفِقْهِ",uz:"fiqh o‘rganishni boshladim"},{ar:"يَا مَوْلَايَ",uz:"ey hukmdorim"}],full_uz:"Fiqh o‘rganishni boshladim, hukmdorim...",note:"طَلَبُ الْفِقْهِ — fiqh o‘rganishga kirishish, shu ilmni talab qilish."},
{num:472,time:"00:38:54,579 --> 00:38:59,440",arabic:"عَلَى يَدِ الْإِمَامِ هَيَّاجِ بْنِ الْعَلَاءِ السُّلَمِيِّ.",segs:[{ar:"عَلَى يَدِ الْإِمَامِ",uz:"imomning qo‘lida"},{ar:"هَيَّاجِ بْنِ الْعَلَاءِ السُّلَمِيِّ",uz:"Hayyoj ibn Alo Sulamiyning"}],full_uz:"Imom Hayyoj ibn Alo Sulamiyning qo‘lida.",note:"السُّلَمِيُّ — Sulaym qabilasiga mansublikni bildiruvchi nisba."},
{num:473,time:"00:38:59,440 --> 00:39:01,220",arabic:"صَاحِبِ وَاصِلِ بْنِ عَطَاءٍ.",segs:null,full_uz:"Vosil ibn Atoning hamrohi bo‘lgan.",note:"صَاحِبٌ bu kabi ilmiy kontekstda bir olim bilan yaqin bo‘lgan, undan ta’lim olgan yoki unga ergashgan kishini ham anglatadi."},
{num:474,time:"00:39:01,220 --> 00:39:03,700",arabic:"نِعْمَ الْمُعَلِّمُ هُوَ.",segs:null,full_uz:"U qanday yaxshi ustoz!",note:"نِعْمَ — maqtov fe’li. هُوَ maqtov qaratilgan kishini bildiradi."},
{num:475,time:"00:39:03,700 --> 00:39:08,559",arabic:"رَحِمَهُ اللَّهُ وَرَحِمَ اللَّهُ وَاصِلَ بْنَ عَطَاءٍ.",segs:[{ar:"رَحِمَهُ اللَّهُ",uz:"Alloh uni rahmatiga olsin"},{ar:"وَرَحِمَ اللَّهُ وَاصِلَ بْنَ عَطَاءٍ",uz:"va Alloh Vosil ibn Atoni rahmatiga olsin"}],full_uz:"Alloh uni ham, Vosil ibn Atoni ham rahmatiga olsin.",note:null},
{num:476,time:"00:39:08,559 --> 00:39:10,220",arabic:"شَيْخَ الْمُتَكَلِّمِينَ.",segs:null,full_uz:"Kalom olimlarining shayxini.",note:"الْمُتَكَلِّمُونَ bu yerda oddiy «gapiruvchilar» emas, kalom ilmi bilan shug‘ullanuvchi olimlar."},
{num:477,time:"00:39:10,220 --> 00:39:13,360",arabic:"أَدَامَكَ اللَّهُ يَا مَوْلَايَ...",segs:[{ar:"أَدَامَكَ اللَّهُ",uz:"Alloh sizni doim saqlasin"},{ar:"يَا مَوْلَايَ",uz:"ey hukmdorim"}],full_uz:"Alloh sizni doim saqlasin, hukmdorim...",note:"أَدَامَ — «davomli qildi, saqlab turdi». Qaysi holatda saqlash tilanayotgani keyingi bandda keladi."},
{num:478,time:"00:39:13,360 --> 00:39:16,059",arabic:"مُدَافِعًا عَنْ أَهْلِ الْحَقِّ وَالْعَقْلِ.",segs:[{ar:"مُدَافِعًا",uz:"himoya qiluvchi bo‘lib"},{ar:"عَنْ أَهْلِ الْحَقِّ وَالْعَقْلِ",uz:"haq va aql ahlini"}],full_uz:"Haq va aql ahlini himoya qiluvchi bo‘lib.",note:"دَافَعَ عَنْ — «...ni himoya qildi». مُدَافِعًا oldingi banddagi murojaat qilinayotgan kishining holatini bildiradi."},
{num:479,time:"00:39:16,059 --> 00:39:18,280",arabic:"وَإِنِّي لَأَشْكُرُ اللَّهَ عَزَّ وَجَلَّ.",segs:[{ar:"وَإِنِّي لَأَشْكُرُ اللَّهَ",uz:"men, albatta, Allohga shukr qilaman"},{ar:"عَزَّ وَجَلَّ",uz:"U qudratli va ulug‘dir"}],full_uz:"Men, albatta, qudratli va ulug‘ Allohga shukr qilaman.",note:"إِنَّ va لَـ birgalikda fikrni kuchli ta’kidlaydi. عَزَّ وَجَلَّ — Allohning ulug‘ligini ifodalovchi ibora."},
{num:480,time:"00:39:18,280 --> 00:39:21,099",arabic:"الَّذِي حَبَانِي شَرَفَ اللِّقَاءِ بِكَ.",segs:[{ar:"الَّذِي حَبَانِي",uz:"menga ato etgan"},{ar:"شَرَفَ اللِّقَاءِ بِكَ",uz:"siz bilan uchrashish sharafini"}],full_uz:"Menga siz bilan uchrashish sharafini ato etgan Allohga.",note:"حَبَا — «ato etdi, in’om qildi». حَبَانِي — «menga ato etdi»."},
{num:481,time:"00:39:21,099 --> 00:39:22,920",arabic:"وَالْمُثُولِ بَيْنَ يَدَيْكَ.",segs:[{ar:"وَالْمُثُولِ",uz:"va hozir bo‘lish"},{ar:"بَيْنَ يَدَيْكَ",uz:"sizning huzuringizda"}],full_uz:"Va sizning huzuringizda hozir bo‘lish sharafini.",note:"الْمُثُولُ بَيْنَ يَدَيْ فُلَانٍ — «falonchining huzurida hozir bo‘lish»."},
{num:482,time:"00:39:22,920 --> 00:39:25,139",arabic:"فَقَدْ عَقَدْتُ عَلَيْكَ الْآمَالَ.",segs:[{ar:"فَقَدْ عَقَدْتُ عَلَيْكَ",uz:"sizga bog‘ladim"},{ar:"الْآمَالَ",uz:"umidlarimni"}],full_uz:"Men sizga umidlarimni bog‘ladim.",note:"عَقَدَ عَلَيْهِ الْآمَالَ — «unga umid bog‘ladi». آمَالٌ — أَمَلٌ so‘zining ko‘pligi."},
{num:483,time:"00:39:25,139 --> 00:39:27,240",arabic:"بَعْدَ أَنْ وَفَّقَكَ اللَّهُ.",segs:[{ar:"بَعْدَ أَنْ",uz:"...ganidan keyin"},{ar:"وَفَّقَكَ اللَّهُ",uz:"Alloh sizga muvaffaqiyat bergan"}],full_uz:"Alloh sizga muvaffaqiyat berganidan keyin.",note:null},
{num:484,time:"00:39:27,239 --> 00:39:31,059",arabic:"وَحَبَانِي بِأَنْ أَكُونَ خَادِمًا مِنْ خَدَمِكَ.",segs:[{ar:"وَحَبَانِي",uz:"va menga ato etganidan keyin"},{ar:"بِأَنْ أَكُونَ خَادِمًا",uz:"xizmatkor bo‘lishni"},{ar:"مِنْ خَدَمِكَ",uz:"xizmatkorlaringizdan biri"}],full_uz:"Va menga xizmatkorlaringizdan biri bo‘lishni ato etganidan keyin.",note:"خَدَمٌ — خَادِمٌ («xizmatkor»)ning ko‘pligi."},
{num:485,time:"00:39:31,059 --> 00:39:33,979",arabic:"بَارَكَ اللَّهُ فِيكَ أَيُّهَا الْإِيَادِيُّ.",segs:[{ar:"بَارَكَ اللَّهُ فِيكَ",uz:"Alloh sizga baraka bersin"},{ar:"أَيُّهَا الْإِيَادِيُّ",uz:"ey Iyodiy"}],full_uz:"Alloh sizga baraka bersin, ey Iyodiy.",note:"أَيُّهَا aniq artiklli so‘zga murojaat qilishda ishlatiladi. الْإِيَادِيُّ marfu’ kelgan."},
{num:486,time:"00:39:33,979 --> 00:39:39,519",arabic:"يُعْجِبُنِي مِنْكَ طِيبُ الْحَدِيثِ وَدِقَّةُ اللَّفْظِ وَعُمْقُ الْمَعْنَى.",segs:[{ar:"يُعْجِبُنِي مِنْكَ",uz:"sizda menga yoqadi"},{ar:"طِيبُ الْحَدِيثِ",uz:"yoqimli nutq"},{ar:"وَدِقَّةُ اللَّفْظِ",uz:"so‘zning aniqligi"},{ar:"وَعُمْقُ الْمَعْنَى",uz:"va ma’noning chuqurligi"}],full_uz:"Sizning yoqimli nutqingiz, so‘zlaringizning aniqligi va ma’nolaringizning chuqurligi menga yoqadi.",note:"اللَّفْظُ — ifodalangan so‘z, lafz. دِقَّةُ اللَّفْظِ — so‘z tanlashdagi aniqlik."},
{num:487,time:"00:39:46,439 --> 00:39:52,539",arabic:"دَعْنِي أَسْأَلْكَ عَنْ رَأْيِكَ فِي الْجَدَلِ الدَّائِرِ فِي أَوْسَاطِ فُقَهَاءِ بَغْدَادَ وَعُلَمَائِهَا.",segs:[{ar:"دَعْنِي أَسْأَلْكَ",uz:"sizdan so‘rashimga ijozat bering"},{ar:"عَنْ رَأْيِكَ",uz:"fikringiz haqida"},{ar:"فِي الْجَدَلِ الدَّائِرِ",uz:"davom etayotgan bahs borasida"},{ar:"فِي أَوْسَاطِ فُقَهَاءِ بَغْدَادَ",uz:"Bag‘dod faqihlari orasida"},{ar:"وَعُلَمَائِهَا",uz:"va uning olimlari"}],full_uz:"Bag‘dod faqihlari va olimlari orasida davom etayotgan bahs haqidagi fikringizni so‘rashimga ijozat bering.",note:"الْجَدَلُ الدَّائِرُ — «davom etayotgan bahs». فِي أَوْسَاطِ — «...orasida, ...doiralarida»."},
{num:488,time:"00:39:52,539 --> 00:39:56,299",arabic:"مَوْلَايَ الْمَأْمُونُ يَعْلَمُ أَنَّنِي، وَالْحَمْدُ لِلَّهِ...",segs:[{ar:"مَوْلَايَ الْمَأْمُونُ يَعْلَمُ",uz:"hukmdorim Ma’mun biladilarki"},{ar:"أَنَّنِي",uz:"men"},{ar:"وَالْحَمْدُ لِلَّهِ",uz:"Allohga hamd bo‘lsin"}],full_uz:"Hukmdorim Ma’mun biladilarki, men, Allohga hamd bo‘lsin...",note:null},
{num:489,time:"00:39:56,300 --> 00:40:01,420",arabic:"بَعِيدٌ عَمَّا يُغْضِبُ اللَّهَ مِنْ أَنْ يُنْسَبَ التَّجْسِيمُ إِلَيْهِ.",segs:[{ar:"بَعِيدٌ عَمَّا يُغْضِبُ اللَّهَ",uz:"Allohni g‘azablantiradigan narsadan yiroqman"},{ar:"مِنْ أَنْ يُنْسَبَ التَّجْسِيمُ إِلَيْهِ",uz:"Unga jism nisbat berilishidan"}],full_uz:"Allohni g‘azablantiradigan Unga jism nisbat berishdan yiroqman.",note:"التَّجْسِيمُ — jism deb tasavvur qilish yoki jism nisbat berish. يُنْسَبَ — majhul nisbat: «nisbat berilishi»."},
{num:490,time:"00:40:01,420 --> 00:40:05,980",arabic:"وَمِمَّا يَدَّعِيهِ بَعْضُهُمْ مِنْ جَوَازِ رُؤْيَةِ اللَّهِ فِي الْآخِرَةِ.",segs:[{ar:"وَمِمَّا يَدَّعِيهِ بَعْضُهُمْ",uz:"va ba’zilarining da’vosidan"},{ar:"مِنْ جَوَازِ رُؤْيَةِ اللَّهِ",uz:"Allohni ko‘rish mumkinligi haqidagi"},{ar:"فِي الْآخِرَةِ",uz:"oxiratda"}],full_uz:"Va ba’zilarining oxiratda Allohni ko‘rish mumkinligi haqidagi da’vosidan ham yiroqman.",note:"جَوَازٌ bu yerda «mumkinlik». اِدَّعَى — «da’vo qildi»."},
{num:491,time:"00:40:05,980 --> 00:40:07,420",arabic:"أَعَاذَنَا اللَّهُ مِنْ ذَلِكَ.",segs:[{ar:"أَعَاذَنَا اللَّهُ",uz:"Alloh bizni asrasin"},{ar:"مِنْ ذَلِكَ",uz:"bundan"}],full_uz:"Alloh bizni bundan asrasin.",note:"أَعَاذَ — يُعِيذُ — «panoh berdi, asradi»."},
{num:492,time:"00:40:07,420 --> 00:40:11,980",arabic:"كَمَا أَنَّنِي أَسْتَغْفِرُ اللَّهَ مِنْ قَوْلِهِمْ فِي الْقُرْآنِ الْكَرِيمِ.",segs:[{ar:"كَمَا أَنَّنِي أَسْتَغْفِرُ اللَّهَ",uz:"shuningdek, Allohdan mag‘firat so‘rayman"},{ar:"مِنْ قَوْلِهِمْ",uz:"ularning gapi uchun"},{ar:"فِي الْقُرْآنِ الْكَرِيمِ",uz:"Qur’oni karim haqidagi"}],full_uz:"Shuningdek, ularning Qur’oni karim haqidagi gapi uchun Allohdan mag‘firat so‘rayman.",note:"اِسْتَغْفَرَ اللَّهَ — «Allohdan mag‘firat so‘radi». فِي bu yerda «...haqida» ma’nosida."},
{num:493,time:"00:40:11,980 --> 00:40:14,940",arabic:"إِذْ يَقُولُونَ إِنَّهُ لَيْسَ مَخْلُوقًا.",segs:[{ar:"إِذْ يَقُولُونَ",uz:"chunki ular aytadilar"},{ar:"إِنَّهُ لَيْسَ مَخْلُوقًا",uz:"u yaratilgan emas deb"}],full_uz:"Chunki ular uni yaratilgan emas, deydilar.",note:"مَخْلُوقًا — لَيْسَ ning mansub xabari. إِذْ bu yerda izoh va sabab ma’nosini beradi."},
{num:494,time:"00:40:14,940 --> 00:40:20,480",arabic:"فَيَضَعُونَهُ بِذَلِكَ مَوْضِعًا لَا يَلِيقُ إِلَّا بِاللَّهِ عَزَّ وَجَلَّ.",segs:[{ar:"فَيَضَعُونَهُ بِذَلِكَ",uz:"shu bilan uni qo‘yadilar"},{ar:"مَوْضِعًا لَا يَلِيقُ",uz:"munosib bo‘lmaydigan o‘ringa"},{ar:"إِلَّا بِاللَّهِ",uz:"faqat Allohgagina munosib bo‘lgan"},{ar:"عَزَّ وَجَلَّ",uz:"U qudratli va ulug‘dir"}],full_uz:"Shu bilan uni faqat qudratli va ulug‘ Allohgagina munosib bo‘lgan o‘ringa qo‘yadilar.",note:"لَاقَ بِـ — يَلِيقُ بِـ — «...ga munosib bo‘ldi, bo‘ladi». مَوْضِعٌ bu yerda maqom yoki darajani bildiradi."},
{num:495,time:"00:40:20,480 --> 00:40:27,199",arabic:"لَكَ مِنَ الْقُرْبَةِ مِنَّا فَوْقَ مَا تُرِيدُ يَا ابْنَ أَبِي دُؤَادٍ.",segs:[{ar:"لَكَ مِنَ الْقُرْبَةِ مِنَّا",uz:"bizga yaqinlikdan sizga nasib etadi"},{ar:"فَوْقَ مَا تُرِيدُ",uz:"istaganingizdan ham ortig‘i"},{ar:"يَا ابْنَ أَبِي دُؤَادٍ",uz:"ey Ibn Abu Duod"}],full_uz:"Sizga bizga yaqinlikdan istaganingizdan ham ortig‘i nasib etadi, Ibn Abu Duod.",note:"الْقُرْبَةُ bu yerda hukmdor huzuridagi yaqinlik va e’tiborni bildiradi. فَوْقَ مَا تُرِيدُ — «istaganingizdan ortiq»."},
{num:496,time:"00:40:45,199 --> 00:40:48,300",arabic:"بَارَكَ اللَّهُ فِي أَحْمَدَ بْنِ نَصْرٍ الْخُزَاعِيِّ.",segs:[{ar:"بَارَكَ اللَّهُ",uz:"Alloh baraka bersin"},{ar:"فِي أَحْمَدَ بْنِ نَصْرٍ الْخُزَاعِيِّ",uz:"Ahmad ibn Nasr Xuzo’iyga"}],full_uz:"Alloh Ahmad ibn Nasr Xuzo’iyga baraka bersin.",note:"أَحْمَدَ g‘ayri munsarif ism bo‘lgani uchun فِي dan keyin ham fatha bilan majrur kelgan."},
{num:497,time:"00:40:48,300 --> 00:40:49,860",arabic:"نِعْمَ الرَّجُلُ هُوَ.",segs:null,full_uz:"U qanday yaxshi kishi!",note:"نِعْمَ maqtov bildiradi; bu yerda نَعَمْ («ha») bilan adashtirmaslik kerak."},
{num:498,time:"00:40:49,860 --> 00:40:53,740",arabic:"يَصْدَعُ بِالْحَقِّ أَيْنَمَا حَلَّ، وَلَا تَأْخُذُهُ فِي اللَّهِ لَوْمَةُ لَائِمٍ.",segs:[{ar:"يَصْدَعُ بِالْحَقِّ",uz:"haqni baralla aytadi"},{ar:"أَيْنَمَا حَلَّ",uz:"qayerga bormasin"},{ar:"وَلَا تَأْخُذُهُ فِي اللَّهِ",uz:"Alloh yo‘lida uni to‘xtatmaydi"},{ar:"لَوْمَةُ لَائِمٍ",uz:"malomat qiluvchining malomati"}],full_uz:"Qayerga bormasin, haqni baralla aytadi va Alloh yo‘lida malomat qiluvchining malomatidan cho‘chimaydi.",note:"صَدَعَ بِالْحَقِّ — «haqni ochiq va dadil aytdi». أَيْنَمَا — «qayerda bo‘lmasin»."},
{num:499,time:"00:40:53,740 --> 00:40:58,039",arabic:"مَا وَجَدْتُ رَجُلًا أَحْنَقَ عَلَى الْمُعْتَزِلَةِ مِنْهُ.",segs:[{ar:"مَا وَجَدْتُ رَجُلًا",uz:"biror kishini ko‘rmadim"},{ar:"أَحْنَقَ عَلَى الْمُعْتَزِلَةِ",uz:"mu’taziliylarga ko‘proq g‘azabli"},{ar:"مِنْهُ",uz:"undan"}],full_uz:"Mu’taziliylarga undan ko‘proq g‘azabli kishini ko‘rmadim.",note:"أَحْنَقُ — «ko‘proq g‘azablangan». حَنَقٌ — kuchli g‘azab, ichki achchiqlanish."},
{num:500,time:"00:40:58,039 --> 00:41:01,680",arabic:"وَلَوْلَا أَنَّنَا نَتَخَوَّلُهُ بِالنُّصْحِ وَالْمَوْعِظَةِ...",segs:[{ar:"وَلَوْلَا أَنَّنَا نَتَخَوَّلُهُ",uz:"agar biz unga vaqti-vaqti bilan murojaat qilib turmaganimizda"},{ar:"بِالنُّصْحِ وَالْمَوْعِظَةِ",uz:"nasihat va o‘git bilan"}],full_uz:"Agar biz unga vaqti-vaqti bilan nasihat va o‘git berib turmaganimizda...",note:"تَخَوَّلَهُ بِالْمَوْعِظَةِ — «unga vaqti-vaqti bilan o‘git berib turdi». لَوْلَا shartining javobi keyingi bandda."},
{num:501,time:"00:41:01,680 --> 00:41:04,380",arabic:"لَخَشِيتُ أَنْ يُعْمِلَ سَيْفَهُ فِيهِمْ.",segs:[{ar:"لَخَشِيتُ",uz:"qo‘rqqan bo‘lardim"},{ar:"أَنْ يُعْمِلَ سَيْفَهُ فِيهِمْ",uz:"ularga qarshi qilich ishlatishidan"}],full_uz:"Ularga qarshi qilich ishlatishidan qo‘rqqan bo‘lardim.",note:"أَعْمَلَ سَيْفَهُ فِيهِمْ — «ularga qarshi qilichini ishlatdi». أَعْمَلَ — «ishga soldi»."},
{num:502,time:"00:41:04,380 --> 00:41:07,140",arabic:"السَّيْفُ مَرْحَلَةُ الْفَصْلِ يَا ابْنَ مَعِينٍ.",segs:[{ar:"السَّيْفُ مَرْحَلَةُ الْفَصْلِ",uz:"qilich — uzil-kesil hal qilish bosqichi"},{ar:"يَا ابْنَ مَعِينٍ",uz:"ey Ibn Ma’in"}],full_uz:"Qilich — uzil-kesil hal qilish bosqichi, Ibn Ma’in.",note:"الْفَصْلُ bu yerda nizoni yakuniy hal qilish, ajrim chiqarishni anglatadi."},
{num:503,time:"00:41:07,140 --> 00:41:12,039",arabic:"لِيَنْتَبِهِ الْخُزَاعِيُّ إِلَى نَفْسِهِ.",segs:[{ar:"لِيَنْتَبِهِ الْخُزَاعِيُّ",uz:"Xuzo’iy e’tiborli bo‘lsin"},{ar:"إِلَى نَفْسِهِ",uz:"o‘ziga"}],full_uz:"Xuzo’iy o‘ziga ehtiyot bo‘lsin.",note:"لِـ buyruq lomi: لِيَنْتَبِهْ — «e’tibor bersin». Keyingi so‘zga ulab o‘qilganda oxirgi harf kasra olgan."},
{num:504,time:"00:41:12,039 --> 00:41:14,519",arabic:"فَرُبَّمَا جَرَّ عَمَلُهُ ذَاكَ...",segs:[{ar:"فَرُبَّمَا جَرَّ",uz:"chunki keltirib chiqarishi mumkin"},{ar:"عَمَلُهُ ذَاكَ",uz:"uning o‘sha ishi"}],full_uz:"Chunki uning o‘sha ishi keltirib chiqarishi mumkin...",note:"جَرَّ bu yerda «bir oqibatga sabab bo‘ldi». رُبَّمَا ehtimolni bildiradi."},
{num:505,time:"00:41:14,519 --> 00:41:19,380",arabic:"فِتْنَةً عَلَى الْمُسْلِمِينَ أَكْبَرَ مِنْ فِتْنَةِ الْمُعْتَزِلَةِ أَنْفُسِهِمْ.",segs:[{ar:"فِتْنَةً عَلَى الْمُسْلِمِينَ",uz:"musulmonlar boshiga fitnani"},{ar:"أَكْبَرَ مِنْ فِتْنَةِ الْمُعْتَزِلَةِ",uz:"mu’taziliylarning fitnasidan kattaroq"},{ar:"أَنْفُسِهِمْ",uz:"ularning o‘zlarining"}],full_uz:"Musulmonlar boshiga mu’taziliylarning o‘z fitnasidan ham kattaroq fitna keltirib chiqarishi mumkin.",note:"أَنْفُسِهِمْ oldingi الْمُعْتَزِلَةِ ni ta’kidlaydi: «ularning aynan o‘zlari»."},
{num:506,time:"00:41:19,380 --> 00:41:23,000",arabic:"إِنَّهُ رَجُلٌ يَعِزُّ مَثِيلُهُ يَا ابْنَ حَنْبَلٍ.",segs:[{ar:"إِنَّهُ رَجُلٌ",uz:"u shunday kishiki"},{ar:"يَعِزُّ مَثِيلُهُ",uz:"unga o‘xshaganini topish qiyin"},{ar:"يَا ابْنَ حَنْبَلٍ",uz:"ey Ibn Hanbal"}],full_uz:"Unga o‘xshagan kishini topish qiyin, Ibn Hanbal.",note:"عَزَّ الشَّيْءُ — «noyob bo‘ldi, topilishi qiyinlashdi». مَثِيلٌ — o‘xshash, teng keladigan kishi."},
{num:507,time:"00:41:23,000 --> 00:41:25,320",arabic:"نَحْنُ نُرِيدُ أَمْثَالَهُ.",segs:[{ar:"نَحْنُ نُرِيدُ",uz:"biz istaymiz"},{ar:"أَمْثَالَهُ",uz:"unga o‘xshaganlarni"}],full_uz:"Biz unga o‘xshaganlarni istaymiz.",note:"أَمْثَالٌ — مِثْلٌ ning ko‘pligi: «o‘xshashlar»."},
{num:508,time:"00:41:25,320 --> 00:41:31,180",arabic:"فَإِنَّ أَهْلَ الْبَاطِلِ لَا يَرْدَعُهُمْ إِلَّا سَيْفٌ كَسَيْفِ هَذَا الرَّجُلِ.",segs:[{ar:"فَإِنَّ أَهْلَ الْبَاطِلِ",uz:"chunki botil ahlini"},{ar:"لَا يَرْدَعُهُمْ إِلَّا سَيْفٌ",uz:"faqat qilich tiyib turadi"},{ar:"كَسَيْفِ هَذَا الرَّجُلِ",uz:"bu kishining qilichidek"}],full_uz:"Chunki botil ahlini faqat bu kishining qilichidek qilich tiyib turadi.",note:"رَدَعَ — «tiydi, qaytardi». لَا ... إِلَّا cheklash ma’nosini bildiradi."},
{num:509,time:"00:41:31,180 --> 00:41:37,180",arabic:"رَجُلٌ سَمِعَ مِنِ ابْنِ عُيَيْنَةَ وَمَالِكِ بْنِ أَنَسٍ وَحَمَّادِ بْنِ زَيْدٍ.",segs:[{ar:"رَجُلٌ سَمِعَ",uz:"hadis eshitgan kishi"},{ar:"مِنِ ابْنِ عُيَيْنَةَ",uz:"Ibn Uyay­nadan"},{ar:"وَمَالِكِ بْنِ أَنَسٍ",uz:"va Molik ibn Anasdan"},{ar:"وَحَمَّادِ بْنِ زَيْدٍ",uz:"hamda Hammod ibn Zayddan"}],full_uz:"Ibn Uyayna, Molik ibn Anas va Hammod ibn Zayddan hadis eshitgan kishi.",note:"سَمِعَ مِنْ ilmiy tarjimayi hollarda bir ustozdan hadis tinglab, rivoyat olganini bildiradi."},
{num:510,time:"00:41:37,180 --> 00:41:41,800",arabic:"وَمَعَ ذَلِكَ يَرْفُضُ أَنْ يَتَصَدَّرَ حَلَقَاتِ الدَّرْسِ.",segs:[{ar:"وَمَعَ ذَلِكَ",uz:"shunga qaramay"},{ar:"يَرْفُضُ أَنْ يَتَصَدَّرَ",uz:"boshida turishni rad etadi"},{ar:"حَلَقَاتِ الدَّرْسِ",uz:"dars davralarining"}],full_uz:"Shunga qaramay, dars davralariga bosh bo‘lib ta’lim berishni rad etadi.",note:"تَصَدَّرَ الْمَجْلِسَ — «majlisning boshida turdi». حَلَقَاتُ الدَّرْسِ — ustoz atrofida to‘planib o‘tiladigan dars davralari."},
{num:511,time:"00:41:41,800 --> 00:41:44,380",arabic:"لِمَاذَا يَا ابْنَ مَعِينٍ؟",segs:[{ar:"لِمَاذَا",uz:"nega"},{ar:"يَا ابْنَ مَعِينٍ",uz:"ey Ibn Ma’in"}],full_uz:"Nega, Ibn Ma’in?",note:null},
{num:512,time:"00:41:45,119 --> 00:41:46,320",arabic:"التَّوَاضُعُ.",segs:null,full_uz:"Kamtarlik.",note:"التَّوَاضُعُ — o‘zini boshqalardan yuqori qo‘ymaslik, kamtarlik."},
{num:513,time:"00:41:46,320 --> 00:41:52,340",arabic:"كُلَّمَا سَأَلْتُهُ لِمَاذَا لَا يَتَصَدَّرُ حَلَقَاتِ الدَّرْسِ وَهُوَ مَا هُوَ عَلَيْهِ مِنَ الْعِلْمِ...",segs:[{ar:"كُلَّمَا سَأَلْتُهُ",uz:"har gal undan so‘raganimda"},{ar:"لِمَاذَا لَا يَتَصَدَّرُ حَلَقَاتِ الدَّرْسِ",uz:"nega dars davralariga bosh bo‘lmasligini"},{ar:"وَهُوَ مَا هُوَ عَلَيْهِ مِنَ الْعِلْمِ",uz:"shuncha ilmga ega bo‘la turib"}],full_uz:"Har gal undan shuncha ilmga ega bo‘la turib, nega dars davralariga bosh bo‘lmasligini so‘raganimda...",note:"كُلَّمَا — «har gal ...ganda». وَهُوَ مَا هُوَ عَلَيْهِ مِنَ الْعِلْمِ kishining ilmdagi yuksak darajasini ta’kidlaydi."},
{num:514,time:"00:41:52,340 --> 00:41:55,100",arabic:"أَجَابَنِي: لَسْتُ أَهْلًا لِذَلِكَ.",segs:[{ar:"أَجَابَنِي",uz:"menga javob berdi"},{ar:"لَسْتُ أَهْلًا لِذَلِكَ",uz:"men bunga munosib emasman"}],full_uz:"Menga: «Men bunga munosib emasman», deb javob beradi.",note:"أَهْلٌ لِـ — «...ga munosib, layoqatli». Oldingi كُلَّمَا bilan birga takrorlanadigan javobni bildiradi."},
{num:515,time:"00:41:55,100 --> 00:42:00,180",arabic:"التَّوَاضُعُ مِنْ صِفَاتِ الْأَنْبِيَاءِ وَالصَّالِحِينَ، لَا أُزَكِّيهِ عَلَى اللَّهِ.",segs:[{ar:"التَّوَاضُعُ مِنْ صِفَاتِ",uz:"kamtarlik sifatlaridandir"},{ar:"الْأَنْبِيَاءِ وَالصَّالِحِينَ",uz:"payg‘ambarlar va solihlarning"},{ar:"لَا أُزَكِّيهِ عَلَى اللَّهِ",uz:"uni Alloh oldida pok deb kafolatlamayman"}],full_uz:"Kamtarlik payg‘ambarlar va solihlarning sifatlaridandir. Uni Alloh oldida pok deb kafolatlamayman.",note:"صِفَاتٌ — صِفَةٌ ning ko‘pligi. لَا أُزَكِّيهِ عَلَى اللَّهِ kishining asl darajasini Alloh bilishini e’tirof etadi."},
{num:516,time:"00:42:00,180 --> 00:42:04,660",arabic:"يَتَوَاضَعُ عَلَى الرَّغْمِ مِنْ عِلْمِهِ وَإِمَامَتِهِ فِي الْحَدِيثِ.",segs:[{ar:"يَتَوَاضَعُ",uz:"kamtarlik qiladi"},{ar:"عَلَى الرَّغْمِ مِنْ عِلْمِهِ",uz:"ilmiga qaramay"},{ar:"وَإِمَامَتِهِ فِي الْحَدِيثِ",uz:"va hadisdagi peshqadamligiga"}],full_uz:"Ilmiga va hadisdagi peshqadamligiga qaramay, kamtarlik qiladi.",note:"عَلَى الرَّغْمِ مِنْ — «...ga qaramay». إِمَامَةٌ bu yerda ilmiy yetakchilik va yuksak daraja."},
{num:517,time:"00:42:04,660 --> 00:42:08,840",arabic:"وَقَدِ ابْتُلِيَتِ الْأُمَّةُ بِآفَةِ الْفَتْوَى بِدُونِ فِقْهٍ.",segs:[{ar:"وَقَدِ ابْتُلِيَتِ الْأُمَّةُ",uz:"ummat esa duchor bo‘ldi"},{ar:"بِآفَةِ الْفَتْوَى",uz:"fatvo berish ofatiga"},{ar:"بِدُونِ فِقْهٍ",uz:"fiqhni bilmasdan"}],full_uz:"Ummat esa fiqhni bilmasdan fatvo berish ofatiga duchor bo‘ldi.",note:"اُبْتُلِيَتْ — majhul nisbat: «sinovga, baloga duchor qilindi». آفَةٌ — zarar keltiruvchi illat yoki ofat."},
{num:518,time:"00:42:08,840 --> 00:42:11,440",arabic:"وَالْحَدِيثِ بِدُونِ عِلْمٍ.",segs:[{ar:"وَالْحَدِيثِ",uz:"va gapirish"},{ar:"بِدُونِ عِلْمٍ",uz:"ilmsiz"}],full_uz:"Va ilmsiz gapirish ofatiga.",note:"الْحَدِيثُ bu yerda «so‘zlash, gapirish» ma’nosida."},
{num:519,time:"00:42:11,440 --> 00:42:13,519",arabic:"وَصَدَارَةِ الْمَجَالِسِ بِلَا رَأْيٍ.",segs:[{ar:"وَصَدَارَةِ الْمَجَالِسِ",uz:"va majlislarning boshida turish"},{ar:"بِلَا رَأْيٍ",uz:"asosli fikrsiz"}],full_uz:"Va asosli fikri bo‘lmay turib majlislarning boshida turish ofatiga.",note:"صَدَارَةٌ — boshchilik, oldingi o‘rinda turish. رَأْيٌ bu yerda mulohaza va asosli fikrni bildiradi."},
{num:520,time:"00:42:13,519 --> 00:42:19,719",arabic:"تَرَى الْوَاحِدَ مِنْهُمْ وَكَأَنَّهُ أَبُو حَنِيفَةَ أَوْ مَالِكُ بْنُ أَنَسٍ أَوِ الشَّافِعِيُّ.",segs:[{ar:"تَرَى الْوَاحِدَ مِنْهُمْ",uz:"ulardan birini ko‘rasiz"},{ar:"وَكَأَنَّهُ أَبُو حَنِيفَةَ",uz:"go‘yo u Abu Hanifa"},{ar:"أَوْ مَالِكُ بْنُ أَنَسٍ",uz:"yoki Molik ibn Anas"},{ar:"أَوِ الشَّافِعِيُّ",uz:"yoki Shofi’iydek"}],full_uz:"Ulardan birini ko‘rsangiz, go‘yo u Abu Hanifa, Molik ibn Anas yoki Shofi’iydek.",note:"كَأَنَّ — «go‘yo, xuddi ...dek». Bu yerda kishilarning o‘zini buyuk olimdek tutishi kinoya bilan aytilmoqda."},
{num:521,time:"00:42:19,719 --> 00:42:22,440",arabic:"فَيَا لَلْعَجَبِ وَيَا لَلْمُفَارَقَةِ!",segs:[{ar:"فَيَا لَلْعَجَبِ",uz:"naqadar ajablanarli"},{ar:"وَيَا لَلْمُفَارَقَةِ",uz:"naqadar qarama-qarshi holat"}],full_uz:"Naqadar ajablanarli, naqadar qarama-qarshi holat!",note:"يَا لَـ bu yerda taajjub ifodalaydi. الْمُفَارَقَةُ — ikki holat orasidagi keskin tafovut yoki nomuvofiqlik."},
{num:522,time:"00:42:22,440 --> 00:42:25,340",arabic:"الْحَقُّ أَنَّهُ يُثْنِي عَلَيْكَ كَثِيرًا يَا ابْنَ حَنْبَلٍ.",segs:[{ar:"الْحَقُّ أَنَّهُ",uz:"rostini aytganda, u"},{ar:"يُثْنِي عَلَيْكَ كَثِيرًا",uz:"sizni juda ko‘p maqtaydi"},{ar:"يَا ابْنَ حَنْبَلٍ",uz:"ey Ibn Hanbal"}],full_uz:"Rostini aytganda, u sizni juda ko‘p maqtaydi, Ibn Hanbal.",note:"أَثْنَى عَلَى — يُثْنِي عَلَى — «maqtadi, maqtaydi»."},
{num:523,time:"00:42:25,340 --> 00:42:29,019",arabic:"يَبْدُو أَنَّهُ حَضَرَ مَجَالِسَكَ فِي الْمَسْجِدِ الْجَامِعِ.",segs:[{ar:"يَبْدُو أَنَّهُ حَضَرَ",uz:"aftidan, u qatnashgan"},{ar:"مَجَالِسَكَ",uz:"majlislaringizda"},{ar:"فِي الْمَسْجِدِ الْجَامِعِ",uz:"jome masjididagi"}],full_uz:"Aftidan, u jome masjididagi majlislaringizda qatnashgan.",note:"حَضَرَ الْمَجْلِسَ — «majlisda qatnashdi». الْمَسْجِدُ الْجَامِعُ — juma namozi o‘qiladigan jome masjidi."},
{num:524,time:"00:42:29,019 --> 00:42:32,920",arabic:"فَأَعْجَبَهُ مَا سَمِعَهُ وَرَآهُ فِي حَلَقَاتِ دَرْسِكَ.",segs:[{ar:"فَأَعْجَبَهُ",uz:"unga yoqibdi"},{ar:"مَا سَمِعَهُ وَرَآهُ",uz:"eshitgan va ko‘rgan narsalari"},{ar:"فِي حَلَقَاتِ دَرْسِكَ",uz:"dars davralaringizda"}],full_uz:"Dars davralaringizda eshitgan va ko‘rgan narsalari unga yoqibdi.",note:"أَعْجَبَهُ الشَّيْءُ — «bir narsa unga yoqdi». Gapda yoqqan narsa ega, ـهُ esa to‘ldiruvchidir."},
{num:525,time:"00:42:32,920 --> 00:42:37,539",arabic:"جَزَاهُ اللَّهُ خَيْرًا عَلَى حُسْنِ ظَنِّهِ وَرَفَعَ لَهُ قَدْرَهُ.",segs:[{ar:"جَزَاهُ اللَّهُ خَيْرًا",uz:"Alloh uni yaxshilik bilan mukofotlasin"},{ar:"عَلَى حُسْنِ ظَنِّهِ",uz:"yaxshi gumoni uchun"},{ar:"وَرَفَعَ لَهُ قَدْرَهُ",uz:"va uning qadrini yuksaltirsin"}],full_uz:"Alloh uni yaxshi gumoni uchun yaxshilik bilan mukofotlasin va qadrini yuksaltirsin.",note:"حُسْنُ الظَّنِّ — yaxshi gumonda bo‘lish. رَفَعَ قَدْرَهُ — «uning qadrini, martabasini yuksaltirdi»."}
];

